export const spisiSearch: { slug: string; chunks: { text: string; headingId: string; headingText: string }[] }[] = [{"slug":"Meka-i-Jesrib-u-Bibliji","chunks":[{"text":"1. Mojsijeva 10:30 spominje naziv Meša, koji se dovodi u vezu sa Mekom. Prevod Biblije iz Njukasla iz 1811. godine to mesto donosi kao „od Meke dok ne dođeš do Medine\". Raši, ugledni jevrejski učenjak, poistovetio je Mišu sa Mekom, a i prevod Saadje Gaona izričito spominje oba grada. Uz to, kumranski rukopis iz četvrte pećine opisuje budući Dom Božiji u koji stranci neće ući i u kojem je borba zabranjena.","headingId":"","headingText":""},{"text":"1. Mojsijeva 10:30 1. Mojsijeva 10:30 Njihova su se naselja protezala od Mase do Safira, istočnog gorja. Naziv Meša, odnosno Masa, dovodi se u vezu sa Mekom. Istorija Biblije i Otkrića vezana za istraživanje Palestine, izričito pominju Meku i Medinu u tekstu 1. Mojsijeva 10:30. Postoje i drugi rukopisi u kojima se to navodi. „Njihovo prebivalište prostiralo se od Miše, kada se ide prema Sefaru, istočnoj planini.“ Istaknuti navod govori o Miši (ميشا) i navodi da je „Miša“ bila naseobina Joktanovih sinova, kao i da su se kedarska plemena Ismailovi potomci približila Miši ili naselila u njenoj blizini. Napomena izričito povezuje kedarska, odnosno ismailićanska arapska plemena sa Mišom, predstavljajući to kao geografsku vezu koja se koristi u raspravama o prisustvu","headingId":"1-mojsijeva-1030","headingText":"1. Mojsijeva 10:30"},{"text":"Arapa i Ismailićana u biblijskim oblastima. Jedan od najistaknutijih i najpoznatijih jevrejskih učenjaka, Radak, poistovećuje Mišu sa Mekom. https://www.sefaria.org/Radak on Genesis.10.30.1?lang=en Glas kaf zamenjen je glasom šin , što se javlja u nekim arapskim dijalektima i naziva se „kaškaša“. Ova jezička pojava postoji u govoru stanovnika Eš Šihra, koji pripadaju plemenu Kuda'a ibn Himjar. U Knjizi postanja nalazi se tekst koji pominje mesto u kojem su živeli Joktanovi sinovi…","headingId":"1-mojsijeva-1030","headingText":"1. Mojsijeva 10:30"},{"text":"Gde se, dakle, nalazi „Miša“ ili „Masa“ pomenuta u tekstu? 1. Mojsijeva 10:30 Njihova su se naselja protezala od Mase do Safira, istočnog gorja. Pogledajmo Biblijski rečnik, pod odrednicom Mesto Miše : „Mesto na istočnoj granici zemlje Joktanaca (1. Mojsijeva 10:30). Možda je to bila ista oblast u kojoj je živelo pleme Masa.“ To znači da je „Miša“ ili „Masa“ ime čoveka čije je poznato pleme živelo u „zemlji koza“","headingId":"gde-se-dakle-nalazi-misa-ili-masa-pomenuta-u-tekstu","headingText":"Gde se, dakle, nalazi „Miša“ ili „Masa“ pomenuta u tekstu?"},{"text":"Pitanje glasi: gde su živeli Joktanovci? Joktan, odnosno Kahtan, bio je prvi kralj Arabijskog poluostrva. Vladao je njegovim južnim delom, u Jemenu, a zatim ga je nasledio njegov sin Ja'rub. To je bilo stotinama godina pre Hrista. Prema Biblijskom rečniku, zemlja Joktanaca bila je ista oblast u kojoj je živelo pleme Miša, odnosno Mesa. Ako se vratimo hebrejskom tekstu Starog zaveta i potražimo značenje reči ממשׁא u Strongovom rečniku, nalazimo sledeće: „Miša, mesto u Arabiji.“ Narodi Kahtanskog kraljevstva, među kojima je bilo i pleme Miša, odnosno Masa, živeli su na Arabijskom poluostrvu. Sada se postavlja pitanje: ko je Miša ili Masa, pomenut u 1. Mojsijeva 10:30, za koga autori Biblijskog rečnika kažu da je živeo u zemlji Joktanaca na Arabijskom","headingId":"pitanje-glasi-gde-su-ziveli-joktanovci","headingText":"Pitanje glasi: gde su živeli Joktanovci?"},{"text":"poluostrvu? Prema Biblijskoj enciklopediji , pod odrednicom „Masa“: „To je ime jednog od Avrahamovih potomaka preko njegovog sina Ismaila… Živeli su u istočnom delu Arabijskog poluostrva, u blizini Vavilona. Prvi stih 31. poglavlja Priča Solomonovih glasi: ‘Reči Lemuila, kralja Mase’, što znači da je bio kralj plemena koje je poticalo od Mase, Ismailovog sina, ili oblasti koju je to pleme naseljavalo.“ To znači da je Miša, odnosno Masa, bio jedan od Avrahamovih potomaka preko njegovog sina Ismaila i da je živeo u zemlji Kahtanaca na Arabijskom poluostrvu…","headingId":"pitanje-glasi-gde-su-ziveli-joktanovci","headingText":"Pitanje glasi: gde su živeli Joktanovci?"},{"text":"Ali u kojem delu Arabijskog poluostrva je živeo? To je skriveno u većini prevoda Biblije i izmenjeno u odnosu na drevne rukopise i prepise, ali se ipak pojavljuje u pojedinim biblijskim prevodima. Na primer, u izdanju Biblije objavljenom 1811. godine u Njukaslu, prebivalište plemena „Mesa“ izričito je navedeno po imenu „Meka“. „Njihovo prebivalište prostiralo se od Meke pa sve do Medine, prema istočnoj planini.“ Da li znate zašto su prepisivači i prevodioci Biblije sakrili ime „Meka“ iz biblijskog teksta? Bio je to njihov očajnički pokušaj da obmanu ljude i izmene starozavetna proročanstva o poslednjem proroku koji će se pojaviti u Meki planinskom gradu u kojem se nalazi Dom Gospodnji, ka kojem hodočaste ljudi iz svih naroda. Da obični hrišćani iz","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"reči Psalma 26: „Obilaziću oko Tvoga oltara, Gospode“, ne bi razumeli da je to proročanstvo o obilaženju Kabe u Meki. Da obični hrišćani iz Isaije 42: „Pevajte Gospodu novu pesmu, hvalu Njegovu od krajeva zemlje… gradovi u kojima Kedar prebiva“, ne bi razumeli da je to proročanstvo o novom proroku koji će doći iz Kedarove zemlje Meke. Da iz Psalma 93: „Svetost priliči Tvome domu, Gospode, doveka“, niko ne bi zaključio da se Božji sveti Dom, koji će zauvek ostati svet, nalazi u Meki. Da niko ne bi pomislio kako tekst iz Ageja 2: „Doći će Želja svih naroda i ispuniću ovaj dom slavom“, govori o proroku koji će Božji Dom ispuniti slavom u Meki. Da niko iz Isaije 35:","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"„Tamo će biti put i staza koja će se zvati Sveti put; niko nečist neće njime prolaziti“, ne bi razumeo da je taj sveti put zapravo put ka Meki. Da niko objavu koja će doći iz arapske zemlje u Isaiji 21: „Objava o Arabiji“, ne bi povezao sa Mekom. …i tako dalje. Postoje desetine proročanstava koja opisuju osobine Meke, njenu zemlju, njene posetioce i hodočašće u Meku. Zato su rani crkveni oci pokušavali da uklone sve što se odnosilo na Meku ili na proročanstva o arapskom proroku koji će se pojaviti u Meki. U najstarijim jevrejskim izvorima, Ismailovi ﷺ potomci Adnan i Kahtan izričito su označeni kao „Arapi“, dok je njihov jezik, arapski, uvršten među četiri jezika kojima je Bog","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"govorio prilikom davanja Tore, prema Knjizi Zohar Berešit . Pominjanje „živeo u pustinji Faran“, odnosno Meke, povezano je s njihovim jezikom, jer se ona u Tori smatra Ismailovim prebivalištem (1. Mojsijeva 21:21). Izraz „Be’emek Habaka“, odnosno „Dolina Baka“, koji se pominje u Psalmu 84, preveden je na nekoliko načina: 1. Dolina plača 2. Dolina suše 3. Dolina balzama 4. Dolina Baka Prvi prevod, „Dolina plača“, nije ispravan jer je hebrejska reč (בכא) Beka , a ne (בכה). Što se tiče prevoda „Dolina suše“ i „Dolina balzama“, suša je svakako jedna od osobina Meke, dok je balzam biljka karakteristična za Meku, kao što navode biblijski stručnjaci. Ali priznaju li oni da je ova dolina Meka? Naravno da ne! Tvrde da je","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"balzam u davna vremena rastao u Palestini, ali da ga tamo više nema. Međutim, njihova opravdanja nisu uverljiva. Arheolog Aleksander Makalister navodi da balzam uopšte nije rastao u Palestini. Neki hrišćanski misionari kritikovali su prevod Tore rabina Saadije Gaona zato što je pomenuo Meku, tvrdeći da je bio pod uticajem islamske kulture. Međutim, kulturni uticaj ne menja nužno geografiju, već samo nazive. Na primer, Arapi izgovaraju Meku kao „Miša“. Prema tome, osoba koja živi u islamskom kulturnom okruženju rekla bi „Meka“, ali time se ne bi promenio geografski položaj tog mesta. Rabin Mojsije Majmonid rekao je: „Da nije bilo našeg učitelja Saadije Gaona, Tora Izrailja bila bi izgubljena.“ Kada čitamo njihove reči i tumačenja, vidimo da ne prestaju da obmanjuju","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"i unose zabunu u pogledu značenja Bake. Njihova tumačenja čas su promenljiva, a čas zamršena i akrobatska. Prema samarićanskom aramejskom tekstu poznatom kao Asatir , Meku su sagradili sinovi Nevajota prvenca našeg učitelja Ismaila, mir neka je na njega. Naziv „Baka“ iz ovog teksta u samarićanskom hebrejskom čita se upravo kao „Baka“ i predstavlja jasnu naznaku mesta koje se u Kur anu naziva Baka, odnosno Meka. Kontekst teksta takođe ga povezuje sa Ismailovom smrću. Tora pripoveda o životu Avrahama, mir neka je na njega, navodeći da je „napustio Hauran i preselio se u zemlju Hananaca. Nastanio se u dolini Sihema, a odatle je otišao u Obećanu zemlju i boravio između Kadeša i Sura.“ 1. Mojsijeva 20:1 Odande Avraham ode u","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"krajeve Negeva i nastani se između Kadisa i Sura. Dok je u Geraru živeo kao stranac, Položaj Kadeša predmet je neslaganja jer se širom Tore pojavljuje na različitim mestima, zbog čega ga je teško precizno odrediti. Poznato je da je Avraham živeo u Meki, ali zašto Tora navodi da je boravio blizu Kadeša? Hebrejska reč (קָדֵ֖שׁ) izgovara se Kadeš , dok na arapskom glasi Kadis , zbog zamene slova šin slovom sin , koja se naročito javlja između hebrejskog i arapskog jezika, poput Moses/Moše i salam/šalom . Veoma je zanimljivo da je „Kadis“ u prošlosti bio jedan od naziva Meke. Pominjanje Meke u spisima Ananije iz Širaka nalazi se u delu Geografija Ananije iz Širaka: duža i kraća redakcija ,","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"koje je preveo Robert H. Hjusen. Tekst glasi: „…gde se nalazi grad Faran, za koji verujem da ga Arapi nazivaju Mekom.“ Ananija je bio astrolog na kojeg su uticali Ptolemejevi i Papovi spisi o drevnoj geografiji Grčke i Jermenije. Zato njegova dela predstavljaju spoj podataka preuzetih iz izvora nastalih između 2. i 7. veka nove ere. Meka se pominje u poglavlju pod naslovom „Kamena Arabija“, geografskoj oblasti koju je zabeležio Ptolemej, a koja se prostirala preko severozapadne Arabije i Sinajskog poluostrva. Zanimljivo je da Ananijini spisi poistovećuju Faran sa Mekom, zbog čega spadaju među najstarije poznate tekstove koji Meku povezuju sa Faranom. Ako je delo nastalo pre 636. godine, to bi značilo da su Jermeni poznavali Meku i njen značaj","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"pre islamskih osvajanja, a možda čak i pre početka poslaničke misije Muhameda, mir neka je na njega. Međutim, neki orijentalisti tvrde da je Meka u Ananijine spise uneta tek nakon islamskih osvajanja. Zapanjujuće je što čas tvrde da su Arapi spaljivali knjige, a čas da su ih prepravljali.","headingId":"ali-u-kojem-delu-arabijskog-poluostrva-je-ziveo","headingText":"Ali u kojem delu Arabijskog poluostrva je živeo?"},{"text":"Još napomena Ovde jedan od crkvenih otaca i istaknuti tumač objašnjava tekst, pokazujući kako se on savršeno podudara sa stanjem muslimana i njihovim verovanjima: Ismail će naslediti Obećanu zemlju i biće otac dvanaest naroda, a to su: Banu Hašim, Banu Abas, Banu el Safah, Banu el Hatab, Banu Jezid i Muavija, Banu Sufjan, Banu Mervan, Banu Abd el Aziz, Banu Afan, Banu Džafer, Banu el Mudi, Banu el Valid i Banu Umeja. Od njih je potekao arapski rod, a među njima su se pojavili muslimani. Avraham i njegova žena nastanili su se u gradu Jesribu u Hidžazu, među pripadnicima Banu Hašima. Ismail se ženio Arapkinjama i postao otac dvanaest plemena, kao što mu je Bog obećao. Hrišćani iznose prigovor u","headingId":"jos-napomena","headingText":"Još napomena"},{"text":"vezi sa proročanstvom o dolini Baka u Psalmu 84, pitajući zašto rani muslimani nisu pominjali ovo jasno proročanstvo kao što su pominjali proročanstva o Faranu i Isaijino proročanstvo o dolasku sluge. Božjom milošću, pronašao sam verodostojno predanje od Mudžahida, koji je umro 104. godine po Hidžri. On je rekao: „Pronašao sam u Psalmima: ‘Ja sam Bog Bake’ (Psalam 84:6); ‘prolazeći dolinom Bake, postavio sam je između dve planine’ (Psalam 84:7); ‘idući od planine do planine’ (Psalam 84:6); ‘blagoslovio sam njene stanovnike’ (Psalam 84:6); ‘blagoslovima je prekrivaju.’“ Prema tome, muslimani su bili upoznati sa ovim proročanstvom još od samih početaka islama. Fatimidski novčići nazivaju Meku Bakom, potvrđujući da je Meka zaista Baka.","headingId":"jos-napomena","headingText":"Još napomena"}]},{"slug":"Agej-2-7-zelja-svih-naroda","chunks":[{"text":"U hebrejskom tekstu Ageja 2:7 javlja se koren hmd, koji odgovara arapskom korenu h m d, od kojeg dolazi ime Muhammed, u značenju hvaljeni ili najhvaljeniji. Ser Godfri Higins navodi da je Muhammed kod Ageja izričito najavljen i po imenu, te da tu nema umetanja niti načina da se taj jasan tekst zaobiđe.","headingId":"","headingText":""},{"text":"Tekst proročanstva Agej 2:7 Uzdrmaću sve narode pa će doći Čežnja svih naroda. Ispuniću ovaj Dom slavom – kaže Gospod nad vojskama.","headingId":"tekst-prorocanstva","headingText":"Tekst proročanstva"},{"text":"Hebrejski koren hmd U hebrejskom tekstu javlja se koren hmd, odnosno חמד, koji se prevodi kao željeni, a nosi značenje hvaljenog, odnosno onoga koga svi narodi žele i hvale. Taj hebrejski koren odgovara arapskom korenu ح م د h m d, od kojeg dolazi ime مُحَمَّد Muhammed, u značenju onaj koji je hvaljen, odnosno najhvaljeniji.","headingId":"hebrejski-koren-hmd","headingText":"Hebrejski koren hmd"},{"text":"Svedočanstva nemuslimanskih istraživača Ovde je Muhammed izričito najavljen kod Ageja, i to po imenu. Ovde nema umetanja. Nema načina da se izbegne ovaj jasan tekst i njegovo značenje. Godfrey Higgins, Anacalypsis, tom 1, str. 679. M. A. Jusuf upućuje na to da hebrejska slova na tom mestu daju oblik hamd, odnosno hmd, prema samom hebrejskom tekstu. M. A. Youssef, The Dead Sea Scrolls, str. 110. Na istu vezu upućuje se i u časopisu Notes and Queries and Historic Magazine. Notes and Queries and Historic Magazine, tom 23, str. 122.","headingId":"svedocanstva-nemuslimanskih-istrazivaca","headingText":"Svedočanstva nemuslimanskih istraživača"}]},{"slug":"Da-li-je-Ibrahim-bio-Jevrejin","chunks":[{"text":"Reč Hebrej razlikuje se od reči Jevrejin i po poreklu i po tvorbi i po značenju. U celoj Bibliji ne postoji nijedno mesto na kojem se za Ibrahima kaže da je bio Jevrejin. Uz to, ako jevrejstvo kao vera počinje sa Musaom, onda Ibrahim, koji mu prethodi, ne može biti Jevrejin. To priznaju i jevrejski i hrišćanski izvori.","headingId":"","headingText":""},{"text":"Primedba Pojedini misionari tvrde da je Ibrahim bio Jevrejin, a ne musliman, kako navodi Kur'an, i to iznose kao navodnu istorijsku grešku. 1. Mojsijeva 14:13 Ali neki begunac dođe i sve ispriča Avramu Jevrejinu , dok je boravio kod hrastova Amorejca Mamrije, brata Eshola i Anera, koji su bili njegovi saveznici. 1. Mojsijeva 12:7 Gospod se ukazao Avramu i rekao mu: „Tvome potomstvu ću dati ovu zemlju.“ Na tom mestu je Avram sagradio žrtvenik Gospodu koji mu se ukazao. Oltari/žrtvenik se nalaze samo u judaizmu i hrišćanstvu; i ovo je snažan dokaz da je Abraham bio Jevrejin. U odgovoru na ovo kažem da: Nije prikladno da se hrišćanin raspravlja protiv \"Svetog Kur'ana\", čiji je izvor, način prenošenja i čuvanja, i","headingId":"primedba","headingText":"Primedba"},{"text":"čija je autentičnost poznata kroz usmeno i pismeno prenošenje, njegova izopačena, ustajala knjiga, za koju ni oni sami ne znaju ko ju je napisao, kada je napisana, niti gde je napisana. Ono što je čudno i iznenađujuće jeste da su sami hrišćani ti koji su optužili jevreje da su izopačili tekstove Starog zaveta, a dokaza za to ima na desetine, ako ne i stotine!","headingId":"primedba","headingText":"Primedba"},{"text":"Prvo Hrišćani optužuju jevreje za izopačenost Starog zaveta Iz knjige Uvod u Stari zavet od Samjuela Džozefa čitamo: Samarijani su izmenili 6.000 mesta u Tori kako bi ih prilagodili svojim uverenjima! Uvod u Stari zavet od Samjuela Džozefa, str. 52 Iz knjige Biblijska enciklopedija, tom 4 čitamo: 6.000 razlika između samaritanske i masoretske Tore... namerne izmene kako bi podržali svoja uverenja! Biblijska enciklopedija, tom 4, str. 324 Iz knjige Kratka istorija država od Ibnul Arabija čitamo: Jevrejski rabini su izmenili godine starosti ljudi u svojoj knjizi kako se proročanstva ne bi odnosila na Hrista Kratka istorija država od Ibnul Arabija, str. 114, I iz knjige Vodič za studente kroz dragocenu Bibliju čitamo: Neslaganje između hebrejskog i Septuaginte bilo je namerno;","headingId":"prvo-hriscani-optuzuju-jevreje-za-izopacenost-starog-zaveta","headingText":"Prvo - Hrišćani optužuju jevreje za izopačenost Starog zaveta"},{"text":"Jevreji su namerno izvršili izmenu kako bi dokazali svoje mišljenje! Vodič za studente kroz dragocenu Bibliju, str. 571","headingId":"prvo-hriscani-optuzuju-jevreje-za-izopacenost-starog-zaveta","headingText":"Prvo - Hrišćani optužuju jevreje za izopačenost Starog zaveta"},{"text":"Drugo Hebrej nije isto što i Jevrejin Reč Hebrej razlikuje se od reči Jevrejin i po poreklu i po tvorbi i po značenju. Hebreji su jedna od grana semitske porodice. Njihovo ime vezuje se za Ebera, jednog od Ibrahimovih predaka. Čitamo u rečniku Svete Biblije i Enciklopediji Biblije pod odrednicom \"Hebreji\" (oni su jedna od grana semitske porodice. Njihovo ime se pripisuje Eberu, jednom od predaka Abrahama, koji ih je doveo u Palestinu i dao im naziv Kanaanci) Poreklo imena uz koje se Abraham vezivao seže do jednog od predaka Abrahama, alejhis selam, i nema nikakve veze sa jevrejskom religijom, ni sa Jevrejima, ni sa njihovim obredima, ni na koji način. U celoj Bibliji, u oba njena zaveta, ne postoji","headingId":"drugo-hebrej-nije-isto-sto-i-jevrejin","headingText":"Drugo - Hebrej nije isto što i Jevrejin"},{"text":"nijedno mesto na kojem se za Ibrahima kaže da je bio Jevrejin. Hebreji ne predstavljaju rasu niti jednu vrstu rase, koliko predstavljaju pomešane grupe, klanove i plemena, i njihova loza nije bila ograničena samo na sinove Israilove. Prvi sinovi Israilovi, na čelu sa samim Jakubom, smatraju se Hebrejima, pa čak i njegov otac Ishak i njegov deda Ibrahim, alejhimus selam, smatraju se Hebrejima prema tome, a sinovi Israilovi predstavljali su samo mali ogranak Hebreja, a zatim su se Jevreji ubrzo pripisivali Hebrejima i nikome drugome. Reč \"Jevrejin\" nije naziv religije već naziv naroda; što se tiče religije, to je Islam i predanje Jedinom Bogu od večnosti i to je religija svih poslanika. Čitamo iz Hebrejskog i haldejskog leksikona za tekst","headingId":"drugo-hebrej-nije-isto-sto-i-jevrejin","headingText":"Drugo - Hebrej nije isto što i Jevrejin"},{"text":"Starog zaveta; prevedenog, sa dodacima i ispravkama iz autorskog Tezaurusa i drugih dela (1857), na strani 830, pod rečju \"שלם\" čitamo: Kratak prevod: Ova reč \"שלם šalom šalim (salm aslam)\" znači da se osoba predaje u miru \"putem Islama\" i koristi se kod \"muslimanskih\" Arapa u značenju predanja Bogu i sledenja Muhameda.","headingId":"drugo-hebrej-nije-isto-sto-i-jevrejin","headingText":"Drugo - Hebrej nije isto što i Jevrejin"},{"text":"Treće Ibrahimova vera bila je predanost Bogu Sura Ali Imran 3:67 Avram nije bio ni jevrej ni hrišćanin, već pravi vernik, Allahu predan. On nije bio od onih koji drugima daju mesto koje samo pripada Allahu. Sura El Bekara 2:131 Kada je njemu Gospodar njegov rekao: \"Predan budi!\" On je odgovorio: \"Ja sam predan Gospodaru svetova.\" Religija Islama je religija svih poslanika od Adema do Muhameda, sallallahu alejhi ve sellem, i Allahova religija je jedna, ali se zakoni mogu razlikovati od jednog poslanika do drugog u skladu sa interesima njegovih sledbenika i onim što odgovara njihovom mestu i vremenu. Religija poslanika je jedna, a njihovi zakoni su različiti; kao što je Allahov Poslanik, sallallahu alejhi ve sellem, rekao: \"Poslanici su","headingId":"trece-ibrahimova-vera-bila-je-predanost-bogu","headingText":"Treće - Ibrahimova vera bila je predanost Bogu"},{"text":"braća po očinstvu: njihova religija je jedna, ali su im majke različite, a ja sam najbliži ljudi Isau, sinu Merjeminom.\" Buhari 3443 Ovo je priznala i Jevrejska enciklopedija (Encyclopaedia Judaica) Tom I, Drugo izdanje:","headingId":"trece-ibrahimova-vera-bila-je-predanost-bogu","headingText":"Treće - Ibrahimova vera bila je predanost Bogu"},{"text":"Četvrti hronološka nemogućnost Ako se smatra da jevrejstvo kao vera počinje sa Musaom, mir neka je na njega, kako onda Ibrahim može biti Jevrejin? Zar ovi ljudi ne znaju da su sinovi Israilovi poreklom od potomaka Ibrahima i njegovog sina Israila (Jakuba koji se borio sa Bogom!!). I jevrejski i hrišćanski izvori slažu se da Ibrahim prethodi jevrejstvu. Sajt jewfaq.org navodi: „Pogrešno je Ibrahima, Ishaka i Jakova smatrati Jevrejima , jer se naziv jevrejski i judaizam nije primenjivao na taj narod. \" http://www.jewfaq.org/origins.htm Isto navodi i hrišćanski sajt rcg.org. https://rcg.org/questions/p095.a.html Ne postoji nijedan tekst u Svetoj knjizi u kome Musa, alejhis selam, kaže da je njihova religija \"Judaizam\", kao što ne postoji nijedan tekst u kome Isa kaže da je","headingId":"cetvrti-hronoloska-nemogucnost","headingText":"Četvrti - hronološka nemogućnost"},{"text":"njegova religija \"Hrišćanstvo\"!! Ako sami Jevreji poriču da je Poslanik Ibrahim, alejhis selam, bio Jevrejin, kako se usudjuju misionari, kradljivci religija i razbojnici šerijata, bez trunke stida na licu, da tvrde i sa praznom laži da je ovaj plemeniti Poslanik, alejhis selam, Jevrejin??!!!","headingId":"cetvrti-hronoloska-nemogucnost","headingText":"Četvrti - hronološka nemogućnost"},{"text":"Svedočanstva Među Jevrejima postoje rabini, od kojih neki pripadaju najvećim rabinskim školama. Rabin Tovija Singer na primer, koji govore svom snagom: \"Hrišćanin koji tvrdi da se muslimani ne klanjaju istom Bogu kao i Poslanik Ibrahim alejhis selam čini sebe najvećim budalom! Poslanik Ibrahim alejhis selam bio je musliman u smislu potpunog predanja Bogu! Hrišćanin koji veruje da se muslimani klanjaju bogu Meseca (ili nekom drugom paganskom bogu) je bolesna osoba kojoj je potrebno lečenje jer ne zna o čemu govori! Muslimani se klanjaju jedinom istinitom Bogu, Islam ima posebno i poštovano mesto u jevrejskoj veri!!!\" https://www.youtube.com/watch?v=udYM4FuYdiA&t=5s","headingId":"svedocanstva","headingText":"Svedočanstva"}]},{"slug":"Hodocasce-u-Izlasku-5-1","chunks":[{"text":"U Izlasku 5:1 javlja se hebrejski oblik וְיָחֹגּוּ, izveden iz korena hagag. Strongov rečnik, pod brojem H2287, taj koren prevodi kao obaviti hodočašće, a Braunov rečnik ga izričito upoređuje sa arapskim glagolom u značenju uputiti se ka predmetu poštovanja i obaviti hodočašće u Meku. Više savremenih engleskih prevoda to mesto i prevodi rečju hodočašće.","headingId":"","headingText":""},{"text":"Tekst 2. Mojsijeva 5:1 Nakon toga Mojsije i Aron odu k faraonu i reknu mu: „Govori Gospod, Bog Izrailjev: ’Pusti moj narod da ode i u moju čast proslavi praznik u pustinji.’“ Izraz o kojem je reč jeste וְיָחֹגּוּ.","headingId":"tekst","headingText":"Tekst"},{"text":"Rečničke odrednice Strongov rečnik, pod brojem H2287, taj koren određuje u značenju obaviti hodočašće/Hadž. Strong's Dictionary, H2287. Braunov rečnik navodi Brown Driver Briggs Lexicon, odrednica חָגַג. : חָגַג, glagol: obaviti hodočašće, održati hodočasnički praznik; arapski: uputiti se ka predmetu poštovanja, obaviti hodočašće u Meku. Uporedni koren, glasi חוּג i znači načiniti krug. Strong's Dictionary, H2328.","headingId":"recnicke-odrednice","headingText":"Rečničke odrednice"},{"text":"Kruženje kao obred Jedino mesto na Zemlji na kojem ljudi hodočaste i obožavanje Musaovom Bogu iskazuju kruženjem, odnosno tavafom, jeste Časna Kaba. Ako neko zna za neko drugo mesto na Zemlji gde se isti Bog obožava na isti način, neka nam da njegovo ime i koordinate… Neki će reći: Da, muslimani obožavaju svoje bogove crtajući krugove tokom tavafa, ali ne obožavaju na ovaj način istog Boga Musaa, Ibrahima, Ishaka i Jakuba, alejhimus selam! Odgovor: Ostavimo jevrejskog rabina koji je od svih ljudi najupoznatiji sa svojom knjigom da im da odgovor!!! Jevrejski rabin Tovija Singer kaže: Tvrditi da se muslimani ne klanjaju istom Bogu kao i Ibrahim alejhis selam čini hrišćanina koji to tvrdi najvećom budalom! Muslimani čvrsto veruju da je","headingId":"kruzenje-kao-obred","headingText":"Kruženje kao obred"},{"text":"Ibrahim alejhis selam bio musliman, musliman u smislu potpunog predanja Bogu. Vera svakog muslimana ukazuje da su Ishak i Jakub alejhimus selam svi bili poslanici. Muslimani veruju u Boga mnogih poslanika, uključujući Ibrahima, Ishaka i Jakuba alejhimus selam. Hrišćanin koji tvrdi da se muslimani klanjaju bogu Meseca je osoba kojoj je potrebno lečenje jer ne zna o čemu govori! Muslimani se klanjaju jedinom istinitom Bogu! Islam ima veliko poštovanje prema jevrejskoj veri!! https://www.youtube.com/watch?v=bU5uz6XzxPQ&t=6s","headingId":"kruzenje-kao-obred","headingText":"Kruženje kao obred"},{"text":"Savremeni prevodi Ono što se da za primetit jeste da nijedan srpski prevod ne prevodi hodočašće u ovom stihu (1.Mojsijeva 5:1) !!!","headingId":"savremeni-prevodi","headingText":"Savremeni prevodi"},{"text":"Predaje o Musau i telbiji Allahov Poslanik ﷺ prošao je pored doline El Ezrek i rekao: Koja je ovo dolina? Rekli su: Ovo je dolina El Ezrek. Rekao je: Kao da vidim Musa a, mir neka je na njega, kako silazi sa prevoja i uči telbiju Allahu. Sahih Muslim, br. 166. Što se tiče Musaa, on je tamnoput čovek kovrdžave kose, jaše crvenu devu sa ularom. Kao da ga gledam kako silazi u dolinu učeći telbiju. Sahih Buhari 5913 Temelje Kabe podigli su Ibrahim i njegov sin Ismail, mir neka je na njih obojicu, a Allah je poslanicima dozvolio da obave hadž odazivajući se Ibrahimovom pozivu.","headingId":"predaje-o-musau-i-telbiji","headingText":"Predaje o Musau i telbiji"},{"text":"Odeća Izlazak 33:5 6 Gospod reče Mojsiju: „Reci Izrailjcima: ’Vi ste narod tvrdovrat. Kad bih samo za tren išao gore sa vama, pobio bih vas. Zato skinite sa sebe nakit, a ja ću videti kako da postupim s vama.’“ Tako su Izrailjci poskidali sa sebe nakit kod gore Horiv. Prošireni prevod to mesto donosi rečima: „Skinite sav svoj nakit, i odlučiću šta ću sa vama. I narod Izrailjev skinuo je svoj nakit kod gore Sinaj.\" Muslimana u ihramima pokrivaju se sa samo dva dela odeće Reč koja se ovde koristi je: stripped, što znači potpuno skidati odeću! stripped – bez odeće! Komentar jedne hrišćanske Biblije iz 1833. godine navodi: Tako su se sinovi Izrailjevi skinuli sa svoje odeće i nakita.","headingId":"odeca","headingText":"Odeća"},{"text":"Taj običaj bio je poznat u prošlosti, a i danas se održava na Istoku, tokom hodočasničkih obreda muslimana u Meku. Komentar hrišćanske Biblije, 1833.","headingId":"odeca","headingText":"Odeća"}]},{"slug":"Isaija-29-12-i-nepismeni","chunks":[{"text":"Isaija 29:12 govori o knjizi koja se predaje onome ko nije učen, sa rečima „pročitaj ovo\", na šta on odgovara da ne zna čitati. Hebrejska reč קְרָא, kara, znači čitati. To se poredi sa predajom o prvom susretu u pećini Hira, gde na naredbu „Čitaj\" Poslanik ﷺ odgovara da ne zna da čita.","headingId":"","headingText":""},{"text":"Tekst Isaija 29:12 Onda daju nekom ko ne zna da čita i kažu mu: „Hajde, čitaj to!“ On će odgovoriti: „Ne znam da čitam.“ Kai dothisetai to livelion all butto eis chiras anthropouu: mi epistamenou gramʼmata ˙ kai eri afto: anagnothi tafta kai eri. Ouk aipistamai gramʼmata Ključno pitanje: Zar to nije upravo ono što je objavljeno Poslaniku ﷺ na samom početku objave — kada mu je Džibril ﷺ sišao dok je bio u osami u pećini Hira i rekao mu: \"Čitaj\"? Istorijski kontekst: Jedna od najvažnijih stvari koje morate znati jeste da nije postojala arapska verzija Svete Biblije u šestom veku nove ere , to jest, u vreme kada je Muhamed ﷺ bio živ. Štaviše, on je bio nepismen.","headingId":"tekst","headingText":"Tekst"},{"text":"Al A'raf 7:157 „onima koji će da slede Poslanika, Verovesnika, koji neće da zna ni da čita ni da piše, kojeg oni kod sebe, u Tori i Jevanđelju, nalaze zapisanog, koji će od njih da traži da čine dobra dela, a od odvratnih da odvraća, koji će lepa jela da im dozvoli, a ružna zabrani, koji će da ih tereta i teškoća koje su oni imali oslobodi. A oni koji u njega budu verovali, koji ga budu podržavali i pomagali i svetlo po njemu poslato sledili oni će sigurno uspeti.“","headingId":"tekst","headingText":"Tekst"},{"text":"Arapski prevodi Isaije 29:9–14 Uobičajeni arapski prevod: Budite zbunjeni i začuđeni! Budite slepi i slepi! Opijte se, ali ne vinom! Posrću, ali ne od jakog pića. Gospod je izlio na vas duh omamljenosti; zatvorio je oči vašim prorocima i pokrio glave onima koji među vama vide. Sve vaše vizije postale su nejasne, kao reči zapečaćene knjige. Dajete je onome ko ume da čita, govoreći: \"Pročitaj ovo.\" On kaže: \"Ne mogu, jer je zapečaćena.\" Zatim je dajete onome ko ne ume da čita, govoreći: \"Pročitaj ovo.\" I on odgovara: (Ne znam da čitam). Izmena u arapskom prevodu (Smit i Van Dajk) Prevod Smita i Van Dajka na arapski jezik promenio je frazu od (Ne znam da čitam) u (Ne znam da","headingId":"arapski-prevodi-isaije-29914","headingText":"Arapski prevodi Isaije 29:9–14"},{"text":"pišem). Ovo je namerna izmena s ciljem da se arapski čitalac odvrati od prepoznavanja ispunjenja priče u njenim rečima u pećini Hira.","headingId":"arapski-prevodi-isaije-29914","headingText":"Arapski prevodi Isaije 29:9–14"},{"text":"Hebrejska reč U hebrejskom tekstu javlja se reč קְרָא, koja se izgovara kara i znači čitanje, a ne pisanje. Hebrejski teks: וְנִתַּן הַסֵּפֶר, עַל אֲשֶׁר לֹא יָדַע סֵפֶר לֵאמֹר— קְרָא נָא זֶה; וְאָמַר, לֹא יָדַעְתִּי סֵפֶר Razrada reč po reč: | Hebrejski | Transliteracija | Značenje | | | | | | וְנִתַּן | wə·nit·tan | predaje se | | הַסֵּפֶר | wə·nit·tan | knjiga | | עַל | ’al | na njega | | אֲשֶׁר | ’ă·šer | koji | | לֹא | lō | ne | | קְרָא | qə·rā | Čitaj | | נָא | qə·rā | molim se | Iz Biblijskog rečnika , reč: קְרָא Strong's hebrejski 7123 1. Vrsta reči: Glagol 2. Transliteracija: qera 3.","headingId":"hebrejska-rec","headingText":"Hebrejska reč"},{"text":"Fonetski pravopis: (keraw’) 4. Kratka definicija: čitati 5. Definicija: zvati, čitati naglas ili glasno 6. NASB prevod: nazvan (1), objavljen (1), čitan (7), povikao (1), pozvan (1)","headingId":"hebrejska-rec","headingText":"Hebrejska reč"},{"text":"Svitci sa Mrtvog mora U manuskriptu \"svitsci sa Mrtvog mora\" se takodje spominje \"ne zna da čita\". https://www.ao.net/%7Efmoeller/qa tran.htm c23","headingId":"svitci-sa-mrtvog-mora","headingText":"Svitci sa Mrtvog mora"},{"text":"Grčki tekst (Septuaginta i Sinaitski) Grčki tekst ostaje trajni i snažni argument protiv njih, jer je to originalni tekst na kome je napisana njihova knjiga i iz koga su sačinjeni svi drugi prevodi. Isaija 29:12(Sinaitski) καὶ δοθήσεται τὸ βιβλίον τοῦτο εἰς χιρας ανθρωπου · μη επιϲταμενου γραμʼματα ˙ και ερι αυτω · αναγνωθι ταυτα και ερι . ουκ αιπιϲταμαι γραμʼματα Posmatranjem rukopisa Knjige proroka Isaije, komentatori Biblije su su dodali detalj na frazu: ειϲ χιραϲ touto eis chiras što znači u pećini Hira. Ova fraza je namerno izmenjena jer su je oni koji je nisu razumeli u to vreme dodali. Fraza koja je editovana: ον τοῦτο εἰς χ ε ῖρα ς ον τοῦτο εἰς χῖρα Sada pogledajte prevod ove fraze:","headingId":"grcki-tekst-septuaginta-i-sinaitski","headingText":"Grčki tekst (Septuaginta i Sinaitski)"},{"text":"Reč حراء znači pećina Hira Kako je izvršeno falsifikovanje Umetnuto slovo ε ς Pošto je Sinaitski rukopis napisan velikim slovima, a pošto su mala slova naknadno dodata zbog njihovog nerazumevanja nejasnih reči u to vreme, ili zato što su im te reči bile nove, kao što je reč Pećina Hira (ειϲ χιρα), dodali su malo slovo ε (epsilon), koje je dodavanjem potpuno promenilo značenje reči. Tako je od (Pećina Hira) → postalo (ruke) εἰς χεῖρας = u ruke (izmenjeno) ειϲ χιρα = Pećina Hira (izvorno) Možda se to dogodilo zato što u trećem veku nisu poznavali reč (Hira) pa im je ta reč bila nepoznata. Ili kada su saznali da se ovaj događaj desio Muhamedu ﷺ u Pećini Hira, dodali","headingId":"grcki-tekst-septuaginta-i-sinaitski","headingText":"Grčki tekst (Septuaginta i Sinaitski)"},{"text":"su ovo umetnuto slovo u rukopis. Međutim, rukopis nam je potvrdio falsifikovanje ruku još jednom, u najvažnijim tekstovima ikada. Potvrda iz Knjiga o Jovu 4:3 u istom rukopisu: ει γαρ ϲυ ενουθετηϲαϲ πολλουϲ . και χειραϲ αϲθενουϲ παρεκαλεϲαϲ Ovde je slovo (ε epsilon) jasno vidljivo i dobro srazmerno u reči (χειραϲ). Ovo potvrđuje da je prepisivač znao i razlikovao ove dve reči: 1. καιχειραϲ (i ruke) 2. ταϲχιρα (Pećina Hira) Potvrda iz Dela apostolskih 21:11 u istom rukopisu: και ελθων προϲ ημαϲ και αραϲ χιραϲ ειπεν ταδε λεγι Tekst se ovde pojavljuje bez dodatka epsilona to jest, bez izmene: ταϲ χιρα bez ikakvog dodatka. To znači da je prepisivač ovog rukopisa, kao što smo ranije rekli, razlikovao ove dve reči:","headingId":"grcki-tekst-septuaginta-i-sinaitski","headingText":"Grčki tekst (Septuaginta i Sinaitski)"},{"text":"1. καιχειραϲ 2. ταϲχιρα Da li je reč koja se pojavljuje u Isaiji (ταϲ χιραϲ) greška prepisivača koji je zaboravio ovo slovo? Ili je prepisivač ovog rukopisa zaista razlikovao ove dve reči: 1. τοῦτο εἰς χεῖρας (u ruke) 2. τοῦτο εἰς χῖρα (Pećina Hira) Kako bi dodatno obmanuli, počeli su da dovode u pitanje tekst, ali umesto da navode ono što stoji u tekstu Isaije, počeli su da navode drugi tekst koji se nalazi u Jevanđelju po Mateju i koji nema nikakve veze sa tekstom o kome je reč. Navode iz Mateja 15:2, 17:22, 18:8, 19:13 i donose ga umesto Knjige proroka Isaije kako bi obmanuli.","headingId":"grcki-tekst-septuaginta-i-sinaitski","headingText":"Grčki tekst (Septuaginta i Sinaitski)"},{"text":"Reč Anthropou A sada, šta znači reč ανθρωπου (anthropou), koja se nalazi u istom tekstu? και δοθηϲεται το βιβλιον τουτο ειϲ χιραϲ ανθρωπου · μη επιϲταμενου γραμʼματα ˙ και ερι αυτω · αναγνωθι ανθρωπου = anthropou = čovek / ljudsko biće Dakle, tačan i potpun prevod stiha glasi (tačan prevod Isaije 29:12): \"Ili se knjiga daje u pećini Hira čoveku koji ne zna da čita, i kaže mu se: 'Pročitaj ovo.' A on kaže: 'Ne znam da čitam.'\" Isaija 29:12 A o reči \"knjiga\" u tekstu, vratimo se na hebrejski: Reč סֵפֶר (Sefer) pojavljuje se u Starom zavetu 186 puta i prevodi se kao knjiga ili svitak. A grčka reč γράμματα (gramata) na grčkom takođe znači pismo i stoga je","headingId":"rec-anthropou","headingText":"Reč Anthropou"},{"text":"to pridev za onoga ko ne zna da piše. I isto tako, reč χιρας (kheras) što znači Pećina Hira je reč koja se izvorno nalazi u Septuaginti na grčkom, a ne u hebrejskom tekstu.","headingId":"rec-anthropou","headingText":"Reč Anthropou"},{"text":"Hadis o prvoj objavi Zato će svako vaše viđenje biti kao reči u zapečaćenom svitku. Daju nekom ko zna da čita i kažu: „Hajde, čitaj ovo!“ On će odgovoriti: „Ne mogu zato što je zapečaćeno.“ Onda daju nekom ko ne zna da čita i kažu mu: „Hajde, čitaj to!“ On će odgovoriti: „Ne znam da čitam.“ — Isaija 29:11 12 Ovaj tekst beleži veliki trenutak u kome objava počinje da silazi Poslaniku ﷺ. Iz Sahihul Buharija, prenosi Majka vernika, Aiša (radijallahu anha): Početak objave Božijem Poslaniku, s.a.v.s., bili su istiniti snovi. Sve što bi vidio u snu, to se i ostvarivalo poput jutarnjeg svitanja. Omiljena mu je samoća i on se osamljivao u pećini Hira i tu se posvećivao molitvama,","headingId":"hadis-o-prvoj-objavi","headingText":"Hadis o prvoj objavi"},{"text":"provodeći u pobožnosti mnoge noći prije nego bi se vratio svojima. Potom se vratio Hatidži i ponio opskrbu, dok ga istiniti nije iznenadio dok se on nalazio u pećini Hira. Naime, došao mu je melek i rekao mu: 'Čitaj!' 'Ja ne znam čitati!', odgovorio je on. (Kasnije je pričao): 'Zatim me je uzeo k sebi i tako me stisnuo da me je spopala muka, a onda me pustio i rekao mi: 'Čitaj!' 'Ja ne znam čitati!' rekao sam, a on me opet uzeo i ponovo me stisnuo da me je spopala muka. Potom me pustio i rekao mi: 'Čitaj!' 'Ja ne znam čitati!', kazao sam ja, a on me stisnuo i po treći put tako da me je spopala muka.","headingId":"hadis-o-prvoj-objavi","headingText":"Hadis o prvoj objavi"},{"text":"Onda me pustio i rekao: 'Čitaj u ime tvoga Gospodara koji stvara; stvara čovjeka od ugruška. Čitaj, plemenit je Gospodar tvoj, koji je čovjeka poučio peru...'' S tim se Božiji Poslanik, s.a.v.s., vratio nazad, dok mu je srce snažno lupalo.. Sahih Buhari, 3, i Sahih Muslim, 160. Osama Poslanika ﷺ u pećini Hira, način na koji mu je Kur'an objavljivan, i to što je bio nepismen, poklapaju se sa opisom iz Isaije 29:12.","headingId":"hadis-o-prvoj-objavi","headingText":"Hadis o prvoj objavi"},{"text":"Kur'anski reference Allah kaže u suri Er Ra'd: Ar Ra'd 13:43 Oni koji ne veruju govore: „Ti nisi poslanik.“ Reci: „Meni i vama Allah će da bude dovoljan kao svedok, i oni koji znanje iz Knjige imaju.“ Uzvišeni Allah kaže, objašnjavajući da je ovo proročanstvo kod njih i upozoravajući ih na laž i klevetu: Al 'Ankabut 29:46 49 I sa sledbenicima Knjige raspravljajte na najlepši način, ali ne i s onima među njima koji su nepravedni, i recite: „Mi verujemo u ono što se nama objavljuje i u ono što je vama objavljeno, a naš Bog i vaš Bog je jedan, i Njemu smo mi predani!“ Tako isto i tebi objavljujemo Knjigu, a neki od onih kojima smo već dali","headingId":"kuranski-reference","headingText":"Kur'anski reference"},{"text":"Knjigu i u nju veruju, a i među ovima ima onih koji u nju veruju, a Naše reči i dokaze negiraju samo nevernici. Ti pre nje nijednu knjigu nisi čitao, a nisi je ni svojom desnom rukom pisao, inače, posumnjali bi oni koji govore laži. Međutim, Kur'an je sačinjen od jasnih reči; u grudima su onih kojima je dato znanje, a Naše reči negiraju samo nepravednici, Al A’raf 7:157 „onima koji će da slede Poslanika, Verovesnika, koji neće da zna ni da čita ni da piše, kojeg oni kod sebe, u Tori i Jevanđelju, nalaze zapisanog, koji će od njih da traži da čine dobra dela, a od odvratnih da odvraća, koji će lepa jela da im dozvoli, a ružna","headingId":"kuranski-reference","headingText":"Kur'anski reference"},{"text":"zabrani, koji će da ih tereta i teškoća koje su oni imali oslobodi. A oni koji u njega budu verovali, koji ga budu podržavali i pomagali i svetlo po njemu poslato sledili oni će sigurno uspeti.“","headingId":"kuranski-reference","headingText":"Kur'anski reference"},{"text":"Dodatne napomene Možda je do ovog dodatka došlo zato što u trećem veku nisu poznavali reč (Hira) pa im je ta reč bila strana. Međutim, rukopis nam je potvrdio falsifikovanje ruku još jednom, u najvažnijim tekstovima ikada. Grčki tekst ostaje trajni i snažni argument protiv njih. Jasno je u rukopisu pred vama: dodatak slova ε je očigledan. Ako ispitamo reč [χιρα] nakon ispravke i izmene ili dodatka slova (ε grčkog epsilona)u jednom od drugih tekstova, kao što je tekst Jova (4:3): ειγαρ ϲυ ενουθετηϲαϲ πολλουϲ . και χειραϲ αϲθενουϲ παρεκαλεϲαϲ Nalazimo da je slovo (ε epsilon) jasno vidljivo, što potvrđuje da je prepisivač znao i razlikovao ove dve reči καιχειραϲ i ταϲχιραϲ gde primećujemo da je ovo slovo veliko (ε)","headingId":"dodatne-napomene","headingText":"Dodatne napomene"},{"text":"i dobro srazmerno. Što znači da je prepisivač rukopisa u trećem veku razlikovao [ειϲχιραϲ] i [καιχειραϲ]. Tekst u Delima apostolskim 21:11 pojavljuje se bez dodatka epsilona, kao što možete videti: καιελθων προϲ ημαϲ και αραϲ ειραϲ ειπεν ταδε λεγι δηϲουϲ ι εν ϊερουϲαλημ οιϊουδ αιοι καιπαρα Tekst je, kao što primećujete, bez izmene [ταϲχιραϲ] to jest, bez dodatka osim dodatka slova [ε], grčkog epsilona. Dok rukopis pred vama ima grčko slovo epsilon to znači da je prepisivač ovog rukopisa, kao što smo ranije rekli, već razlikovao ove dve reči [καιχειραϲ] i [ταϲχιραϲ]. Pitanje koje se sada postavlja je: Da li je reč koja se pojavljuje u Isaiji [ταϲχιρα] greška prepisivača koji je zaboravio ovo slovo? Ili je prepisivač ovog rukopisa","headingId":"dodatne-napomene","headingText":"Dodatne napomene"},{"text":"zaista razlikovao ove dve reči: τοῦτο εἰς χεῖρας i τοῦτο εἰς χῖρα? Ovo nam je dovoljno, ceo vaš odgovor vrti se oko izmišljanja u osnovi mog proučavanja.","headingId":"dodatne-napomene","headingText":"Dodatne napomene"}]},{"slug":"Isaija-42-1-i-oblik-ahmad","chunks":[{"text":"Masoretski tekst Isaije 42:1 ima אֶתְמָךְ בּוֹ, dok se predlaže izvorno čitanje אַחְמַד. Ta dva oblika grafički su bliska. Koren תמך, prema Jastrovom rečniku, znači podupreti, poduprti se, pritisnuti, i nema veze sa naklonošću. Matej 12:18 to mesto ipak prenosi grčkom rečju agapetos, ljubljeni, koja se iz tog korena ne može izvesti, nego iz korena חמד.","headingId":"","headingText":""},{"text":"Kur'anski osnov Sura Es Saff 61:6 A kada Isus, Marijin sin, reče: “O sinovi Izrailjevi, ja sam vam Allahov poslanik, da vam potvrdim pre mene objavljenu Toru i da vam donesem radosnu vest o poslaniku čije je ime Ahmed, koji će posle mene doći”, i kad im je doneo jasne dokaze, oni rekoše: “Ovo je očigledna vradžbina!”","headingId":"kuranski-osnov","headingText":"Kur'anski osnov"},{"text":"Svedočanstvo Ka'ba al Ahbara Ashab Ka'b el Ahbar (radijallahu anhu) učeni jevrej(prihvatio je islam) koji je doneo duboko poznavanje Tore, preneo je da je pronašao ime \"Ahmed\" u jednom primerku Tore. Iz Tarih Medineti Dimashk od Ibn Asakira (umro 571. godine po Hidžri). Reči Ka'ba el Ahbara: \"Našao sam u Tori: Ahmed el Muhtar, on nije ni grub ni surov, niti viče na pijacama, niti uzvraća zlo zlom, već prašta i oprašta. Njegovo rodno mesto je Mekka, njegova seoba je u Tajbu (Medinu), a njegova oblast je Velika Sirija...\" Najbliži biblijski tekst onome što je Ka'b preneo je Isaija 42. Isaija 42:1 3 Evo Sluge moga, kome sam potpora, izabranika moga, miljenika duše moje. Na njega sam Duha svoga izlio","headingId":"svedocanstvo-kaba-al-ahbara","headingText":"Svedočanstvo Ka'ba al-Ahbara"},{"text":"da donosi pravdu narodima. On ne viče, niti buku pravi, na ulici glasa svog ne diže. On ne lomi trsku napuknutu, niti gasi fitilj koji tinja, nego on donosi pravo istinito.","headingId":"svedocanstvo-kaba-al-ahbara","headingText":"Svedočanstvo Ka'ba al-Ahbara"},{"text":"Masoretski tekst naspram Ka'bovog rukopisa Prva ključna razlika između Ka'bovog rukopisa i standardnih masoretskih rukopisa jeste reč koja se pojavljuje između \"Mog sluge\" (עבדי) i \"Mog izabranika\" (מוכתרי): | Rukopis | Isaija 42:1 (srednji izraz) | | | | | Ka'bov rukopis | עבדי אחמד המוכתר \"Moj sluga Ahmad, Izabrani\" | | Masoretski tekst | עבדי אתמך בו מוכתרי \"Moj sluga koga podupirem, Moj izabranik\" |","headingId":"masoretski-tekst-naspram-kabovog-rukopisa","headingText":"Masoretski tekst naspram Ka'bovog rukopisa"},{"text":"Lenjingradski kodeks Isaija 42:1 Lenjingradski kodeks (str. 236), najstariji kompletan hebrejski Biblijski rukopis sa rečju אֶתְמָךְ בּוֹ (atamakh bo) istaknutom žutom bojom. Ceo hebrejski tekst glasi: הֵן עַבְדִּי אֶתְמָךְ בּוֹ בְּחִירִי רָצְתָה נַפְשִׁי נָתַתִּי רוּחִי עָלָיו מִשְׁפָּט לַגּוֹיִם יוֹצִיא Fraza אֶתְמָךְ בּוֹ (atamakh bo) sastoji se iz dva dela: 1. אֶתְמָךְ (atamakh) glagol \"podupirem\", od korena תמך (tamakh) 2. בּוֹ (bo) zamenica \"njega\"","headingId":"lenjingradski-kodeks-isaija-421","headingText":"Lenjingradski kodeks - Isaija 42:1"},{"text":"Šta znači koren תמך? Jastrowov rečnik Targuma, Vavilonskog i Jerusalimskog Talmuda (1903): koren תמך znači \"podupirati, podmetati se, oslanjati se na, pritiskati\"; bez ikakve veze sa ljubavlju ili naklonošću. Reč \"koji/koga\" (אֲשֶׁר / ašer) koja se pojavljuje u nekim prevodima je interpretativni dodatak i ne pojavljuje se u izvornom hebrejskom.","headingId":"sta-znaci-koren-","headingText":"Šta znači koren תמך?"},{"text":"Vizuelna sličnost: אתמך naspram אחמד Na hebrejskom, glagol אֶתְמָךְ (atamakh \"podupirem\") vizuelno je gotovo identičan imenu אַחְמַד (Ahmad). Razlike u masoretskom pismu su manji dodaci koji se lako uočavaju na uvid.","headingId":"vizuelna-slicnost-naspram-","headingText":"Vizuelna sličnost: אתמך naspram אחמד"},{"text":"Poređenje hebrejskog kvadratnog pisma Gornji red: masoretsko אתמך (atamakh / \"podupirem\"). Donji red: ime אחמד (Ahmad). Mali dodaci u crvenim okvirima su jedine vizuelne razlike.","headingId":"poredjenje-hebrejskog-kvadratnog-pisma","headingText":"Poređenje hebrejskog kvadratnog pisma"},{"text":"Poređenje imperijalnog aramejskog pisma Isto poređenje u imperijalnom aramejskom pismu, korišćenom u najranijim fazama prenošenja hebrejskih rukopisa. Sličnost je još izraženija. Zbunjenost nastaje kroz dve supstitucije slova: | Ahmad (אחמד) | → pobrkano sa | Atamakh (אתמך) | | | | | | ח (Het) | → | ת (Tav) | | ד (Dalet) | → | כ (Kaf) | Tako umesto da čita אחמד (Ahmad), rani pisar čita kao אתמך (atamakh) i piše ono što je pročitao, gubeći tako izvorno ime. Završno slovo כ (Kaf sofit) često se izgovara kao \"Kh\", identično arapskom خ što čini zvučnu zbunjenost još lakšom.","headingId":"poredjenje-imperijalnog-aramejskog-pisma","headingText":"Poređenje imperijalnog aramejskog pisma"},{"text":"Nauka o tekstualnoj kritici: Pisarske greške Ovaj tip greške je dobro dokumentovan u nauci o tekstualnoj kritici (Nakd el Nasi), gde je vizuelna sličnost na nivou slova dovodila do toga da pisari nehotice zamenjuju jednu reč drugom tokom prepisivanja, ono što naučnici nazivaju \"vizuelnim/optičkim greškama\" (أخطاء العين والرؤية). \"Uvod u tumačenje Novog zaveta\" od Džordža Faradža (str. 39), opisuje kako je tokom 1.400 godina ručnog prepisivanja došlo do bezbrojnih različitih grešaka: vizuelnih grešaka, zamena slova/reči, grešaka u diktiranju, te pisara koji su \"ispravljali\" ono što su smatrali greškama u izvoru. \"Biblijski rukopisi na njihovim izvornim jezicima\", izričito navodi \"greške oka\" kao primarni izvor varijanti u rukopisima. Primećuje da je do zabune posebno sklono dolaziti između slično oblikovanih hebrejskih i grčkih","headingId":"nauka-o-tekstualnoj-kritici-pisarske-greske","headingText":"Nauka o tekstualnoj kritici: Pisarske greške"},{"text":"slova. \"Nadahnuće Svetog pisma\" od Jusufa Rijada, navodi glavne kategorije pisarskih grešaka: (1) izostavljanje slova/reči/reda, (2) ponavljanje, (3) pravopisne greške, (4) greške u diktiranju i (5) greške pamćenja. Ako je izvorni tekst Isaije 42:1 sadržavao ime Ahmad (אחמד), onda ništa ne sprečava pisara da ga nehotice zameni vizuelno sličnim glagolom atamakh (אתמך), naročito u ranim fazama prepisivanja rukopisa.","headingId":"nauka-o-tekstualnoj-kritici-pisarske-greske","headingText":"Nauka o tekstualnoj kritici: Pisarske greške"},{"text":"Tri argumenta koja dokazuju pisarsku grešku","headingId":"tri-argumenta-koja-dokazuju-pisarsku-gresku","headingText":"Tri argumenta koja dokazuju pisarsku grešku"},{"text":"Prvi argument: Književni obrazac Biblije Biblija nikada ne spominje dve reči \"Moj sluga\" (עבדי) i \"Moj izabranik\" (מוכתרי / בחירי) zajedno u jednom odlomku, a da pored njih ne imenuje i nekog proroka: | Odlomak | Prisutni termini | Imenovani prorok | | | | | | 1. O carevima 11:34 | Moj sluga + koga sam izabrao | David | | Psalmi 89:3 | Moj izabranik + Moj sluga | David | | Isaija 41:8 | Moj sluga + koga sam izabrao | Jakov / Izrael | | Isaija 44:1 | Moj sluga + koga sam izabrao | Jakov / Izrael | | Isaija 45:4 | Moj sluga + Moj izabranik | Jakov / Izrael | | Isaija 42:1","headingId":"prvi-argument-knjizevni-obrazac-biblije","headingText":"Prvi argument: Književni obrazac Biblije"},{"text":"| Moj sluga + Moj izabranik | ❌ Nema imena samo אתמך | Isaija 42:1 je jedini izuzetak — jedini odlomak u kome se ime proroka ne pojavljuje uz oba termina. Upravo ovde nalazimo atamakh bo, čiji prvi segment vizuelno odgovara imenu Ahmad (אחמד). Isaija 42:1 Evo Sluge moga, kome sam potpora, (אתמך בו), izabranika mog u kome duša moja uživa. izabranika moga, miljenika duše moje. Na njega sam Duha svoga izlio da donosi pravdu narodima. Uspostavljeni biblijski obrazac je ovde narušen bez razloga ili opravdanja osim ako prvobitna reč nije bilo lično ime koje je od tada izgubljeno.","headingId":"prvi-argument-knjizevni-obrazac-biblije","headingText":"Prvi argument: Književni obrazac Biblije"},{"text":"Drugi argument: Citat Jevanđeliste Mateja U Mateju 12:17–21, Matej citira Isaiju 42:1 iz jednog hebrejskog rukopisa, onog koji nije sadržavao \"podupirem ga\" (atamakh bo), već reč koju je na grčki preveo kao ἀγαπητός (agapetos \"moj ljubljeni\"): Codex Sinaiticus Matej 12:18, sa ἀγαπητός (\"moj ljubljeni\") vidljivim u grčkom tekstu na levoj strani i istaknutim u prevodilačkom panelu na desnoj strani: \"Evo Sluge moga, koga sam izabrao, voljenog mog, miljenika duše moje.\" Stih 18 u celini glasi: Matej 12:18 Evo Sluge moga, koga sam izabrao, voljenog mog, miljenika duše moje. Na njega ću Duha svoga izliti, da objavi pravdu narodima. Ovo stvara dva moguća objašnjenja za Matejevo \"voljenog mog\": | Opcija | hebrejska reč | → Matejev grčki | | | |","headingId":"drugi-argument-citat-jevandjeliste-mateja","headingText":"Drugi argument: Citat Jevanđeliste Mateja"},{"text":"| | Opcija 1 | אתמך בו (atamakh bo) — \"podupirem ga\" | → \"moj voljeni\" (ἀγαπητός)? | | Opcija 2 | אחמד (Ahmad) — lično ime | → \"moj voljeni\" (ἀγαπητός) ✓ | Ključno pitanje: koja reč može dati značenje \"voljen/ljubljen\" na hebrejskom? Ime Ahmad (אחמד) potiče od korena חמד (khamad) što znači \"ljubljeni\", \"željeni\", \"hvale vredan\". Reči iz ovog korena (kao מחמד / Mahmad / Muhammed) dosledno se prevode kao \"moj ljubljeni\" ili \"željeni\". \"Vodič za biblijskog studenta\" od R. Vilsona, D.D. (2. izdanje, London 1870, str. 523) potvrđuje da hebrejska reč מחמד (mahmad / muhamed) znači \"ljubljeni, željeni, lepi, ljupki, prijatni, prijatna stvar.\" Glagol atamakh (אתמך), nasuprot tome, potiče od korena תמך (tamakh) koji znači samo: podrška,","headingId":"drugi-argument-citat-jevandjeliste-mateja","headingText":"Drugi argument: Citat Jevanđeliste Mateja"},{"text":"potpora, pomoć. Nema nikakve veze sa ljubavlju ni u jednom hebrejskom leksikonu. Ime Ahmad bilo je prisutno u Matejevom hebrejskom rukopisu. On ga je semantički preveo kao \"moj ljubljeni\" (ἀγαπητός) baš kao što bi neko ime Sa'id mogao prevesti kao \"Srećni\", umesto da ga fonetski transkribuje kao Saeed. Izraz atamakh koji se nalazi u masoretskim rukopisima stoga nije ništa drugo do pisarska greška nastala zbog zabune slova usled vizuelne sličnosti naročito u drevnim oblicima pisma. Inače, da je atamakh zaista izvorna reč, bilo bi jezički nemoguće da je Matej prevede kao \"moj ljubljeni\", jer potiče od korena koji nema veze sa ljubavlju. Varijanta iz Svitaka sa Mrtvog mora Reč \"podupirem\" u Isaiji 42:1 pojavljuje se u Svitcima sa Mrtvog mora","headingId":"drugi-argument-citat-jevandjeliste-mateja","headingText":"Drugi argument: Citat Jevanđeliste Mateja"},{"text":"u nešto drugačijem obliku אתמוכה (atamokha): Fragment Isaije iz Svitaka sa Mrtvog mora istaknuta reč pokazuje אתמוכה (atamokha), varijantni oblik masoretskog אתמך. Ako je atamakh korupcija od Ahmad, onda atamokha u Svitcima sa Mrtvog mora mora odgovarajuće biti korupcija od: 1. אחמודה (Akhmuda), ili 2. אחמידה (Akhmida) Oba su aramejski dijalekatski izgovori istog imena.","headingId":"drugi-argument-citat-jevandjeliste-mateja","headingText":"Drugi argument: Citat Jevanđeliste Mateja"},{"text":"Treći argument: Kontekstualna naznaka u Mateju 12:21 Matej 12:21 Ime njegovo nada narodima biće. Dva ključna zapažanja moraju se izneti: 1. Zapažanje 1 Ime se podrazumeva: Fraza \"ime njegovo\" posredno ukazuje na to da je lično ime prisutno u kontekstu. Nositelj ovog imena biće \"Želja svih naroda\" (חמדת כל הגוים / khemdath kol ha goyim) pomenuta u Agaju 2:7 oba odlomka dele isti mesijanski opseg, kako su naučnici univerzalno saglasni. 1. Zapažanje 2 Stih nedostaje u masoretskom tekstu: Ovaj stih je u potpunosti odsutan iz masoretskih rukopisa istih rukopisa koji zamenjuju \"moj ljubljeni / Ahmad\" sa \"podupirem ga\" (atamakh bo). Septuaginta (LXX) verzija Isaije 42:1 uključuje ovaj stih i pominje ime proroka Jakova (יעקב / Ja'kub) u odlomku: Septuaginta (LXX)","headingId":"treci-argument-kontekstualna-naznaka-u-mateju-1221","headingText":"Treći argument: Kontekstualna naznaka u Mateju 12:21"},{"text":"interlinearni prevod Isaija 42:1 počinje sa Ιακώβ (Jakov) što potvrđuje da je čak i grčka tradicija znala da ime proroka pripada ovde. Ipak, Matej nije priznao Jakovljevo ime, on je priznao drugačiju reč koja se može prevesti kao \"moj ljubljeni\". Ovo dokazuje da Matej nije citirao iz Septuaginte. Da je to činio, nikada ne bi propustio priliku da navede Jakovljevo ime protiv Jevreja, tvrdeći da lik nije bio sam Jakov već potomak iz njegove loze naročito s obzirom na Matejevu dobro poznatu praksu povezivanja starozavetnih proročanstava sa Isusom (alejhi selam).","headingId":"treci-argument-kontekstualna-naznaka-u-mateju-1221","headingText":"Treći argument: Kontekstualna naznaka u Mateju 12:21"},{"text":"Četvrti argument: Targum Jonathan i Agaj 2:7 Targum Jonathan (תרגום יונתן) autoritativna aramejska parafraza Proroka, navodi Isaiju 42:1 u celini, bez fraze \"podupirem ga\" (אתמך בו), i umesto toga figuru zamenjuje sa \"Mesija\" (מְשִׁיחָא / Meshikha). Sefaria Targum Jonathan o Isaiji 42 (London \"Haldejska parafraza\", 1871): \"Gledajte, sluga moj, Mesija, koga dovodim, izabranik moj u kome uživam... on će objaviti sud moj narodima.\" Pošto je Isaija 42:1 klasifikovana kao mesijansko proročanstvo o čemu se univerzalno slaže najizričitije potvrđujuće svedočanstvo dolazi iz Agaja 2:7: Agej 2:7 Uzdrmaću sve narode pa će doći Čežnja svih naroda. Ispuniću ovaj Dom slavom – kaže Gospod nad vojskama. Agaj 2:7 interlinearni hebrejski, sa חֶמְדַּת (khemdath — \"Želja\") istaknutom žutom bojom. Reč khemdath (חמדת) potiče od","headingId":"cetvrti-argument-targum-jonathan-i-agaj-27","headingText":"Četvrti argument: Targum Jonathan i Agaj 2:7"},{"text":"korena חמד (khamad) \"ljubljeni\" / \"željeni\" što je čini direktnim hebrejskim sinonimom za imena Ahmad (أحمد) i Muhamed (محمد). Neki učenjaci su to smatrali imenom ili titulom očekivanog Mesije mada su lažno optuživali da je Poslanik ﷺ, daleko je uzvišeniji od takve tvrdnje, to su prisvojili od Isusa (alejhis selam).","headingId":"cetvrti-argument-targum-jonathan-i-agaj-27","headingText":"Četvrti argument: Targum Jonathan i Agaj 2:7"},{"text":"Parkhustov leksikon to potvrđuje Džon Parkhust, \"An Hebrew and English Lexicon, without points\" (London, 5. izdanje, 1807, str. 217): \"Od ovog korena Muhamed, ili (prema našem pokvarenom izgovoru) Mahomet, dobio je svoje ime; ali da li mu je to bilo izvorno ime, ili ga je uzeo nakon što se proglasio za Mesiju Jevreja, Želju svih naroda, ne mogu da utvrdim.\" Čak je i neprijateljska zapadna akademska nauka otvoreno priznala da ime \"Muhamed\" potiče od korena חמד istog korena kao i khemdath iz Agaja 2:7 \"Želja svih naroda.\"","headingId":"parkhustov-leksikon-to-potvrdjuje","headingText":"Parkhustov leksikon to potvrđuje"},{"text":"Dodatni naučni komentari F.F. Brus i dr., \"Teška mesta u Bibliji\" (arapsko izdanje) opširni komentar na Agaja 2:6–7. Priznaje da traje naučna debata o tome da li se \"Želja\" (mušteha) odnosi na Mesiju ili na materijalna blaga, i primećuje da su najstarija jevrejska i hrišćanska tumačenja to razumela kao referencu na Mesiju.","headingId":"dodatni-naucni-komentari","headingText":"Dodatni naučni komentari"},{"text":"Septuaginta potvrđuje \"Ahmad = Izabrani\" Septuaginta (LXX) prevod Agaja 2:7 zamenio je חמדת (khemdath) sa ἐκλεκτά (eklekta — \"Izabrani\"): Agaj 2:7 u LXX prikazuje ἐκλεκτά (eklekta / izabrani) tamo gde hebrejski ima חמדת (khemdath / Želja). Ne postoji jezički put da se khemdath (\"želja/ljubljeni\") prevede kao eklekta (\"Izabrani\") osim ako se ne prizna da Isaija 42:1 sadrži ime Ahmad, jedini tekst koji opisuje Mesiju iz korena khamad kao \"izabranog\" (מוכתר) od Allaha: \"Evo sluge mog Ahmada (אחמד), izabranika mog (מוכתר) u kome duša moja uživa. Metnuću duh svoj na njega; pravdu će narodima doneti.\" Isaija 42:1 (obnovljeno čitanje)","headingId":"septuaginta-potvrdjuje-ahmad-izabrani","headingText":"Septuaginta potvrđuje \"Ahmad = Izabrani\""},{"text":"Odgovor na prigovor: Šta je sa בּוֹ (bo)? Prigovor: Fraza atamakh bo ima dva dela: atamakh i bo. Ako je prvi deo prvobitno bio Ahmad (zamenjen pisarskom greškom), šta je sa zamenicom bo (\"njega\")? Postoje dve mogućnosti.","headingId":"odgovor-na-prigovor-sta-je-sa-bo","headingText":"Odgovor na prigovor: Šta je sa בּוֹ (bo)?"},{"text":"Mogućnost prva ben (בֵּן) a ne bo (בּוֹ) Vizuelno poređenje, gore: masoretsko čitanje אתמך בו (atamakh bo / \"podupirem ga\"); dole: obnovljeno čitanje אחמד בן (Ahmad ben / \"Ahmad sin\"). Primećuje se skoro identična sličnost između ן (završno Nun) i ו (Vav). Prvobitna reč je možda bila בֵּן (ben \"sin od\") umesto בּוֹ (bo \"njega\"). Slova נ (Nun) i ו (Vav) se lako mešaju u drevnom pismu dobro dokumentovana vrsta pisarske greške. To bi dalo izvorni tekst kao: \"Ahmad sin Abdullaha\" (أحمد بن عبد الله) uključujući i ime Poslanikovog oca u rukopisu. Ovo čitanje podržava istorijsko svedočanstvo od Ka'ba el Ahbara: Druga predaja iz Tarikh Medineti Dimashk (str. 184) priča o Jevrejinu po imenu Haribra koji je izmirio dug sa","headingId":"mogucnost-prva-ben-a-ne-bo-","headingText":"Mogućnost prva - ben (בֵּן) a ne bo (בּוֹ)"},{"text":"Poslanikom ﷺ. Istaknuti deo sadrži njegovu izjavu: \"Svedočim da nema boga osim Allaha, i svedočim da si ti Allahov Poslanik. I polovina mog imetka je na Allahovom putu. Tako mi Allaha, ono što me je navelo da ovako postupim bilo je samo to što sam pročitao tvoj opis u Tori: Muhamed ibn Abdulah njegovo rodno mesto je Mekka, njegova seoba je u Tajbu u Velikoj Siriji, on nije grub ni surov, niti viče na pijacama...\" Koren חמד je dosledno očuvan u njihovoj hebrejskoj tekstualnoj tradiciji samo se krajnja vokalizacija menjala između Ahmad i Muhamed. \"Evo sluge mog Ahmada ibn Abdullaha (أحمد بن عبد الله), izabranika mog u kome duša moja uživa. Metnuću duh svoj na njega; pravdu će narodima doneti.\"","headingId":"mogucnost-prva-ben-a-ne-bo-","headingText":"Mogućnost prva - ben (בֵּן) a ne bo (בּוֹ)"},{"text":"— Isaija 42:1 (obnovljeno)","headingId":"mogucnost-prva-ben-a-ne-bo-","headingText":"Mogućnost prva - ben (בֵּן) a ne bo (בּוֹ)"},{"text":"Mogućnost druga — bo kao korektivni dodatak Reč bo (\"njega\") može jednostavno biti korektivni dodatak koji je kasniji pisar umetnuo kako bi dovršio gramatičku rečenicu — nakon što je pogrešno pročitao Ahmad kao atamakh (zbog vizuelne greške) i uvideo da atamakh sam po sebi ne čini potpunu rečenicu kao samostalna reč, pa je dodao bo (\"njega\") da bi je gramatički dovršio.","headingId":"mogucnost-druga-bo-kao-korektivni-dodatak","headingText":"Mogućnost druga — bo kao korektivni dodatak"}]},{"slug":"Isaija-42-i-Kedar","chunks":[{"text":"Odeljak 1 utvrdio je da tekst imenuje Kedar i Selu geografske oblasti Arabije što potvrđuju Adam Klark, Džejmison–Fosit–Braun, Gillovo tumačenje, Leksikon Braun–Drajver–Brigs, rabin Raši, Koptski pravoslavni rečnik i Smitov biblijski rečnik. Kedar = Arapi = Arabijsko poluostrvo. Odeljak 2 utvrdio je da proročanstvo najavljuje duhovni preobražaj: narod Kedara koji nije obožavao Gospoda odaće Mu slavu, dok će oni koji su se uzdali u klesane likove biti osramoćeni. To se ostvarilo kroz poslanstvo Muhameda ﷺ, kada su uništeni idoli u Kabi. Rukopis Koptske patrijaršije poistovećuje Kedar sa Kurejšom. Aramejski Targum zamenjuje Kedar Arapima. Biblijski rečnik Filipa Šafa navodi da je, prema predanju, Kedar jedan od Muhamedovih predaka. Majmonid poistovećuje Kedar sa Kurejšom. Odeljak 3 pobio je hrišćansku tvrdnju kroz sedam tačaka:","headingId":"","headingText":""},{"text":"1. Stari zavet izričito odbacuje nasledni greh. 2. „Nošenje bezakonja“ označava odgovornost zbog zanemarivanja poučavanja, a ne zamensko preuzimanje tuđe krivice. 3. Isaija 53 nastavak je Isaije 52, koja govori o Izrailju a rabin Raši potvrđuje da je sluga Jakov. 4. Isaija 53:10 zahteva da sluga ima decu i dugo živi Isus nije imao ni jedno ni drugo. 5. „Spasitelj“ iz Isaije 43 izbavlja od vojnog osvajanja, a ne od greha što potvrđuju BDB i Džejmison–Fosit–Braun. 6. Prelaženje sa jednog teksta na drugi sa Isaije 42 na Isaiju 53, pa na Isaiju 43 čine oni koji nemaju neposredan odgovor. 7. Sluga iz Isaije 42 jeste pojedinac, a ne narod, što pokazuje paralela sa Isaijom 49.","headingId":"","headingText":""},{"text":"Tekst Isaija 42:1 Evo Sluge moga, kome sam potpora,izabranika moga, miljenika duše moje.Na njega sam Duha svoga izlioda donosi pravdu narodima. Isaija 42:11 Neka se uskomeša pustinja i gradovi njeni,neka odjekuju naselja kedarska,neka podvikuju stanovnici Sele,neka kliču s gorskih vrhova,","headingId":"tekst","headingText":"Tekst"},{"text":"Tvrdnja Kažemo da je ovo proročanstvo o: 1. Misiji Poslanika ﷺ, bez sumnje. 2. Veri onih koji su s njim poverovali od adnanskih ismailitskih Arapa. 3. Uništenju idola i kipova u zemlji Arapa.","headingId":"tvrdnja","headingText":"Tvrdnja"},{"text":"Odeljak 1 Arapi i njihova staništa Kažemo bez sumnje da je proročanstvo specifično za Arape i ono što se dešava u zemlji Arapa. Tekst se direktno odnosi na dve odrednice: 1. Sinovi Kedara 2. Stanovnici Sele Za obe se i sami komentatori slažu da predstavljaju arapske regione.","headingId":"odeljak-1-arapi-i-njihova-stanista","headingText":"Odeljak 1 - Arapi i njihova staništa"},{"text":"Dokazi iz komentara Klarkov komentar Komentar na Isaiju 42:11 \"Neka pustinja Najnekultivisanije zemlje, i najgrublji i najnecivilizovaniji ljudi, priznaće i slaviti sa zahvalnošću blagoslov poznanja Boga koji im je milostivo darovan. Pod pustinjom se misli na Arabiju Deserta; pod stenovitom zemljom, Arabiju Petraea; pod planinama, verovatno one slavne, Paran, Horiv, Sinaj, u istoj zemlji; kojima je takođe pripadao Kedar, klan Arapa, koji su većinom živeli u šatorima. Sela koja Kedar naseljava Arapi, prema Targumu.\" Jamieson Fausset Brown Komentar na Isaiju 42:11 \"Kedar u Arabiji Deserta (Isaija 21:16; Postanje 25:13). Kedarenci su vodili nomadski, lutalački život.\" Gill's Exposition Komentar na Isaiju 42:11 \"Arabija Deserta, i stanovnici gradova koji su u njoj. Arapi koji naseljavaju pustinju hvaliće.\" Brown Driver Briggs Leksikon Odrednica:","headingId":"dokazi-iz-komentara","headingText":"Dokazi iz komentara"},{"text":"H6938 קֵדָר: \"Pleme nomada u arapskoj pustinji. Arapi koji žive u šatorima (šatorima od crne kozje kože).\"","headingId":"dokazi-iz-komentara","headingText":"Dokazi iz komentara"},{"text":"Geografska podela Rimljani su Arabiju podelili na tri zone: 1. Arabia Petraea Jordanska pustinja + severozapadna Arabija 2. Arabia Deserta Centralna i severna Arabija 3. Arabia Felix Jemen, Nadžran, Džizan, Asir Arabia Felix = plodna južna Arabija (Encyclopaedia Britannica)","headingId":"geografska-podela","headingText":"Geografska podela"},{"text":"Zaključak odeljka 1 1. \"Kedar\" = Arapi 2. Reference na regione = Arapsko poluostrvo 3. Klasični učenjaci se jednoglasno slažu o ovoj identifikaciji, bez izuzetka Za one koji sumnjaju da je Arapsko poluostrvo ili Hidžaz deo staništa Kedarita, videti proročanstvo u Ponovljenom zakonu 33:2, rodoslov Muhameda od Ismaila, i dodatne napomene o Poslaniku Muhamedu u Bibliji.","headingId":"zakljucak-odeljka-1","headingText":"Zaključak odeljka 1"},{"text":"Revizija i objašnjenje na najbolji način 5. Mojsijeva 33:2 Reče: „Siđe Gospod sa Sinaja, sa Sira se njemu objavi, zablista s gore Farana, s hiljadama svojih svetih dođe, u desnici mu plamen Zakona. Ovaj stih u Svetoj knjizi odnosi se na proročanstvo tri poslanika, nosilaca zakona i nebeskih knjiga. Na Sinaju je Uzvišeni Allah objavio Tevrat Musau ﷺ. Seir je planina u Palestini, u jasnoj referenci na Hrista ﷺ i njegovo proročanstvo. Planina Paran je referenca na Mekku tačnije na Planinu svetlosti u njoj, jer je Paran Hidžaz, kao što ćemo sada objasniti. Objašnjenje dolazi u tri dela: 1. Utvrđivanje lokacije Parana prema Svetoj knjizi, i da su sinovi Ismaila ﷺ živeli tamo 2. Navođenje islamskih izvora koji tvrde da","headingId":"revizija-i-objasnjenje-na-najbolji-nacin","headingText":"Revizija i objašnjenje na najbolji način"},{"text":"je Paran Hidžaz 3. Navođenje neislamskih izvora koji tvrde da je Paran Hidžaz","headingId":"revizija-i-objasnjenje-na-najbolji-nacin","headingText":"Revizija i objašnjenje na najbolji način"},{"text":"Prvi deo: Utvrđivanje lokacije Parana prema Svetoj knjizi 1. Mojsijeva 25:16 18 To su sinovi Ismailovi; dvanaest knezova nad dvanaest plemena. Po njima su njihova naselja i taborišta dobila ime. Ovo su godine koje je Ismailo doživeo: stotinu trideset sedam godina. Izdahnuo je i umro i bio pridružen svojim precima. Njegovo potomstvo se naselilo od Evile do Sura, koji je nasuprot Egiptu, na putu što vodi u Asiriju. Živeli su u neprijateljstvu sa svom svojom braćom. 1. Mojsijeva 21:17 21 Ali Bog je čuo dečakov glas; Anđeo je Božiji pozvao Agaru s neba, govoreći joj: „Šta te muči, Agaro? Ne boj se, jer je Bog čuo vapaj dečakov tamo gde leži. 18Ustani, uzmi dečaka za ruku i podigni ga, jer","headingId":"prvi-deo-utvrdjivanje-lokacije-parana-prema-svetoj-knjizi","headingText":"Prvi deo: Utvrđivanje lokacije Parana prema Svetoj knjizi"},{"text":"ću od njega podići veliki narod.“ 19Tada joj Bog otvori oči, te ona opazi izvor. Otišla je, napunila mešinu vodom, i napojila dečaka. 20Bog je bio s dečakom. Odrastao je i živeo u pustinji i postao vešt u lovu lukom i strelom. 21Dok je živeo u pustinji Faran, majka mu je dovela ženu iz Egipta. 4. Mojsijeva 10:11 12 Dvadesetog dana, drugog meseca, druge godine, oblak se podigao sa Prebivališta svedočanstva, pa su Izrailjci krenuli iz Sinajske pustinje idući od mesta do mesta. Oblak se zaustavio u Faranskoj pustinji. Tri stvari koje sumiramo iz ovih stihova 1. Pustinja Paran nije pustinja Sinaj. 2. Sinovi Ismaila ﷺ i njihov deda Ismail ﷺ živeli su u Paranu. 3. Granice Parana protežu se","headingId":"prvi-deo-utvrdjivanje-lokacije-parana-prema-svetoj-knjizi","headingText":"Prvi deo: Utvrđivanje lokacije Parana prema Svetoj knjizi"},{"text":"od Havile do Šura. Prelazimo sada na dokaz da je Paran stanište sinova Ismaila ﷺ. Tvrdnja je došla iz jevrejskih izvora da je Paran stanište sinova Ismaila ﷺ a to zahteva da se Paran proteže od Havile do Šura. Rabin Raši Komentar na Ponovljeni zakon 33:2 I zasja sa Sira prema njima: Jer Bog je prvo ponudio sinovima Isava koji su živeli u Siru da prihvate Toru, ali oni nisu hteli da je prihvate. Sa planine Paran: Jer je otišao tamo i ponudio sinovima Ismaila koji su živeli u Paranu da prihvate Toru, ali ni oni nisu hteli da je prihvate. Jamieson Fausset Brown — Komentar na 1. Mojsijeva 21:20–21 Bog je bio s mladićem Paran (to jest Arabija), gde","headingId":"prvi-deo-utvrdjivanje-lokacije-parana-prema-svetoj-knjizi","headingText":"Prvi deo: Utvrđivanje lokacije Parana prema Svetoj knjizi"},{"text":"su njegovi potomci oduvek živeli (uporedi Postanje 16:12; takođe Isaija 48:19, 1. Petrova 1:25). I pošto je Ismail sada bio praktično lišen svog oca, njegova majka je pristupila sklapanju bračne veze za njega, kako se čini, među svojim rođacima. I tako postaje jasno da je oblast od Šura do Havile ista kao oblast Parana, koja je stanište sinova Ismaila ﷺ.","headingId":"prvi-deo-utvrdjivanje-lokacije-parana-prema-svetoj-knjizi","headingText":"Prvi deo: Utvrđivanje lokacije Parana prema Svetoj knjizi"},{"text":"Drugi deo: Dokaz da je Paran od Šura do Havile / Hidžaz Šta je Havila? Strong's rečnik Odrednica: H2341 חֲוִילָה: \"Oblast u Arabiji Ismailićana nazvana po drugom sinu Kuševom; verovatno oblast Kualan. Pokrajina koju su naseljavali Ismailićani, smeštena na Arapskom poluostrvu. Verovatno je to pokrajina Havlan u severozapadnom delu Jemena.\" Biblijski rečnik (Anba Takla) Odrednica: Havila: \"Semitsko ime koje znači 'peščan'. Pokrajina u zemlji Arabiji, koju delom naseljavaju Kušiti, a delom Joktani, koji su semitski narod (Postanje 7:10 i 1:29 i 1. Dnevnika 9:1 i 23). Veza između Havile, Hadramauta i drugih mesta ukazuje na lokaciju u srednjoj ili južnoj Arabiji. U Havili je reka Kišon, a region je bogat zlatom, lekovitom aromatičnom smolom i dragim kamenjem (Postanje 11:2, 12).","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"Neki radije identifikuju Havilu sa regionom Havlan, u zapadnom delu arapskih zemalja, severno od Jemena. Nije poznato dokle se Havila protezala na sever, a iz priče o Saulovoj borbi sa Amalečanima možemo zaključiti da je deo arapske pustinje, koji se protezao nekoliko stotina milja severno od Jamame, nosio ime Havila (1. Samuelova 7:15; uporedi Postanje 18:25).\" Smith's Bible Dictionary Odrednica: Havila: \"Oblast u Arabiji Felix (Postanje 10:7), nazvana po drugom sinu Kuševom; verovatno oblast Kualan, u severozapadnom delu Jemena.\" Takođe čitamo iz Smith's Bible Dictionary, strana 1009–1010: Ako je Havila oblast Havlan u Jemenu šta je onda Šur? Šta je Šur? Smith's Bible Dictionary Odrednica: Šur: \"Šur (zid), mesto odmah izvan istočne granice Egipta. Šur se prvi put pominje u","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"pripovesti o Agarinom begu od Sare (Postanje 16:7). Avram je kasnije 'boravio između Kadeša i Šura, i nastanio se u Geraru' (Postanje 20:1). Takođe se naziva Etam. Pustinju Šur ušli su Izraelci nakon što su prešli Crveno more (Izlazak 15:22–23). Nazivana je i pustinjom Etam (Brojevi 33:8). Šur je možda bio grad teritorija istočno od drevnog vrha Crvenog mora; a budući da se o njemu govori kao o granici, verovatno je bio poslednji arapski grad pre ulaska u Egipat.\" Biblijski rečnik (Anba Takla) Odrednica: Šur: \"Hebrejsko ime koje znači 'zid'. To je mesto u pustinji u južnoj Palestini, tačnije južno od Bir Lahaj Roj (Postanje 16:7 i 25:18), i istočnog Egipta (1. Samuelova 15:7; 28:8). Sinovi Izrailovi hodali su kroz","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"njega tri dana kada su prešli Crveno more (Izlazak 15:22). To se ponekad nazivalo pustinjom Etam (Brojevi 33:8). Šur se prvi put pominje u priči o Agarinom begu (Postanje 16:7). Kasnije je postao stanište Ismailićana (Postanje 25:18). Avram je boravio između Kadeša i Šura (Postanje 20:1).\" Strong's rečnik Odrednica: H7793 שׁוּר: \"Šur. Pustinjska oblast. Jugozapadno od Palestine. Granica Egipta.\" Ako se Šur nalazi istočno od Egipta i južno od Palestine (ili jugozapadno od Palestine, prema različitim mišljenjima) a naročito južno od Bir Lahaj Roj onda čitamo u Biblijskom rečniku da se ovaj bunar nalazi južno od Beer Ševe: Biblijski rečnik (Anba Takla) Odrednica: Bir Lahaj Roj: \"To je izraz koji znači 'bunar Živoga koji me vidi', izvor vode između Kadeša","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"i Bareda (Postanje 16:14 i 24:62 i 25:11) na putu od Asirije do Egipta, kome je krenula Hagara Egipćanka kada je pobegla od svoje gospodarice. Postanje 25:11 ukazuje da ovaj bunar nije daleko od Gerara. Roland kaže da je pronašao bunar u Ain Muvejlihu, 50 milja južno od Beer Ševe, i oko 11 milja zapadno od Ain Kadeša.\" Ono što smo gore rekli potkrepljuje činjenica da Biblija u 1. Mojsijeva 14 kaže: 1. Mojsijeva 14:6: I Horite u njihovoj gori Siru do Botparana, koji je kod pustinje. A Batmaparan je Eilat prema Biblijskom rečniku: Biblijski rečnik (Anba Takla) Odrednica: Botparan / Batmaparan: \"Možda je Batmaparan (Postanje 14:6) bio mesto poznato u drevnim vremenima kao Eilat, a danas kao Eilat, koje","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"se nalazi zapadno od Akabe.\" To zahteva da je deo Parana što znači da se nalazi južno od Šura i severno od Havile. Poznato je da je Eilat poslednji grad u južnoj Palestini i nalazi se na obali Akabskog zaliva. Hidžaz počinje u regionu koji se nalazi južno od njega, približno istočno od njega, sve do Havile u Jemenu. Zaključak geografskog dokaza Dakle: 1. Šur je u pustinji Negev, južno od Beer Ševe, severno od Crvenog mora, istočno od Egipta. 2. Havila je oblast Havlan u Jemenu. Ovaj geografski region od Šura do Havile je region koji Arapi poznaju kao Hidžaz. Jevrejski učenjak Ben Ezra baca kamen na sveštenike i čuvare. Jevrejski rabin priznaje pravo odredište naše majke Hagare ﷺ:","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"odredište je Arapsko poluostrvo, a ne Egipat.","headingId":"drugi-deo-dokaz-da-je-paran-od-sura-do-havile-hidzaz","headingText":"Drugi deo: Dokaz da je Paran - od Šura do Havile / Hidžaz"},{"text":"Vratimo se sada Isaiji 42 našoj glavnoj temi Kao što smo ranije rekli, reč Kedar simbolizuje u Talmudu i jevrejskim izvorima sve beduinske Arape, jer reč označava tamnu ili tamnu boju kože. Jevreji su ponekad primenjivali ovu reč na sve beduinske Arape. Geseniusov hebrejsko haldejski leksikon to potvrđuje. Smith's Bible Dictionary Odrednica: Kedar: \"Kedar (tamnoput), drugi po redu od sinova Ismailovih (Postanje 25:13; 1. Dnevnika 1:29) i ime velikog arapskog plemena naseljenog na severozapadu poluostrva i na granicama Palestine. 'Slava Kedara' zabeležena je kod proroka Isaije (Isaija 21:13–17) u proročanstvu o Arabiji; a njen značaj može se takođe zaključiti iz 'knezova Kedarskih' koje pominje Jezekilj (Jezekilj 27:21), kao i iz pastirskog karaktera plemena. Takođe se čini da su bili, kao","headingId":"vratimo-se-sada-isaiji-42-nasoj-glavnoj-temi","headingText":"Vratimo se sada Isaiji 42 našoj glavnoj temi"},{"text":"i lutalačka plemena današnjice, 'strelci' i 'jaki ljudi' (Isaija 21:17; uporedi Psalam 120:5). Da su se takođe naselili u selima ili gradovima nalazimo kod Isaije (Isaija 42:11). Pleme se čini da je bilo jedno od najistaknutijih od svih ismailitskih plemena, i stoga rabini nazivaju Arape univerzalno ovim imenom.\" Otac Antonije Fikri Komentar na Isaiju 42:11: \"Ovo je pesma otkupljenih od Jevreja i neznabožaca (Otkrivenje 7:10) i Hristos je došao da se bori protiv đavola i još se bori protiv njega u nama. On je kao ratnik. Došao je celom svetu. Kedar = zemlja Arapa. Sela = glavni grad Edoma. I ostrva = to jest daleke zemlje. I on budi svoju revnost = on se pojavio u punini vremena da spase","headingId":"vratimo-se-sada-isaiji-42-nasoj-glavnoj-temi","headingText":"Vratimo se sada Isaiji 42 našoj glavnoj temi"},{"text":"svoj narod zbog svoje revnosti za njih.\"","headingId":"vratimo-se-sada-isaiji-42-nasoj-glavnoj-temi","headingText":"Vratimo se sada Isaiji 42 našoj glavnoj temi"},{"text":"Odeljak 2 Dokaz da se proročanstvo odnosi na veru Arapa u Jednog Boga i njihovo odbacivanje idolopoklonstva To je jasno iz samog konteksta. Tekst kaže: Isaija 42:11 17 Neka se uskomeša pustinja i gradovi njeni, neka odjekuju naselja kedarska, neka podvikuju stanovnici Sele, neka kliču s gorskih vrhova, Neka slavu svoju daju Gospodu, i hvalu mu najavljuju po ostrvima. Kao junak Gospod stupa, kao ratnik on se razjario, On klikće i uz to viče, na neprijatelje se svoje ustremio. „Od davnina sam ćutao, gluv se pravio, uzdržavao, sad vičem kao porodilja, dahćem i izdišem ujedno. Sasušiću gore i bregove, i sparušiti sve biljke po njima, i pretvoriti reke u vrtače, i močvare ja ću isušiti. Slepe ljude vodiću putem što","headingId":"odeljak-2-dokaz-da-se-prorocanstvo-odnosi-na-veru-arapa-u-jednog-boga-i-njihovo-odbacivanje-idolopoklonstva","headingText":"Odeljak 2 - Dokaz da se proročanstvo odnosi na veru Arapa u Jednog Boga i njihovo odbacivanje idolopoklonstva"},{"text":"ga ne poznaju, uputiću ih na staze što ih ne poznaju. Pred njima ću tamu u svetlost pretvoriti, a džombe u zaravan. Te ću stvari učiniti i neću oklevati. U velikom stidu će uzmaći koji se u rezane kipove uzdaju, koji livenim likovima govore: ’Vi ste bogovi naši.’ To je proročanstvo koje govori o veri naroda u jednog jedinog Boga i napuštanju obožavanja klesanih likova i idola. Ono se posebno odnosi na one pomenute u tekstu, zemlju Kedara, zemlju Arapa. Gospodnji nastup poput moćnog ratnika u 13. stihu metafora je za Njegovu zapovest vernicima da se bore protiv mnogobožaca. Zatim u 17. stihu čitamo da su oni koji su se uzdali u idole bili osramoćeni. To se zaista dogodilo Božjem","headingId":"odeljak-2-dokaz-da-se-prorocanstvo-odnosi-na-veru-arapa-u-jednog-boga-i-njihovo-odbacivanje-idolopoklonstva","headingText":"Odeljak 2 - Dokaz da se proročanstvo odnosi na veru Arapa u Jednog Boga i njihovo odbacivanje idolopoklonstva"},{"text":"Poslaniku ﷺ, očistio je Arabijsko poluostrvo od svih idola i kipova.","headingId":"odeljak-2-dokaz-da-se-prorocanstvo-odnosi-na-veru-arapa-u-jednog-boga-i-njihovo-odbacivanje-idolopoklonstva","headingText":"Odeljak 2 - Dokaz da se proročanstvo odnosi na veru Arapa u Jednog Boga i njihovo odbacivanje idolopoklonstva"},{"text":"Biblijski rečnik o Kedar Biblijski rečnik (Anba Takla) Odrednica: Kedar „To semitsko ime znači ‘moćan’, ‘crn’ ili ‘tamnoput’ i pripada drugom sinu Ismaila, Avrahamovog sina (Postanje 25:13; 1. Dnevnika 29:1). On je praotac najpoznatijih arapskih plemena, a njihova zemlja takođe se naziva Kedar (Isaija 21:16; Jeremija 49:28). Uglavnom su bili nomadski pastiri koji su živeli u crnim šatorima, bili su beduini (Pesma nad pesmama 1:5). Međutim, neki od njih bili su civilizovani i živeli su u gradovima kao gradsko stanovništvo (Isaija 42:11). Imali su mnogo stoke i bili su vešti u ratovanju, naročito u streljaštvu, a Asirci su ratovali protiv njih. Navuhodonosor ih je progonio kada je sa svojom vojskom krenuo u njihovu zemlju i opustošio je. Kedar je praotac","headingId":"biblijski-recnik-o-kedar","headingText":"Biblijski rečnik o Kedar"},{"text":"arapskih plemena koja se pod tim imenom pominju u biblijskim proročanstvima od Solomonovog vremena do vavilonskog ropstva. U Isaijinom proročanstvu o arapskoj zemlji (Isaija 21:13–17), Kedar se pominje zajedno sa Dedancima i Temom, kao i to da će ‘za godinu dana… nestati sva slava Kedarova’ (Isaija 21:16 što pokazuje koliko je Kedar tada bio velik, videti i Jezekilj 27:21) i da će se ‘umanjiti ostatak broja strelaca, junaka među sinovima Kedarovim, jer je to rekao Gospod, Bog Izrailjev’ (Isaija 21:17). Slika koju nam Biblija pruža o Kedaru jeste slika beduinskog naroda, Ismailovih potomaka, koji nisu obožavali Gospoda (Jahvea). Međutim, Isaija proriče da će oni biti među narodima koji će u budućnosti uživati u Božjem carstvu (Isaija 42:11; 60:7).“","headingId":"biblijski-recnik-o-kedar","headingText":"Biblijski rečnik o Kedar"},{"text":"Kedar je Kurejš Izvori iz knjiga stranih istraživača i orijentalista potvrđuju da je Adnan, daleki predak Poslanika ﷺ, bio potomak Ismaila, sina Avrahamovog mir neka je na obojicu. U rukopisu koji je Koptska pravoslavna patrijaršija objavila na internetu, na margini uz tekst Isaije 42:11, stoji: Rukopis Koptske pravoslavne patrijaršije COP8 4, str. 65 Kedar se tumači kao Kurejš, praotac Muhamedovog plemena. Tekst uz koji se nalazi ova napomena glasi: „Neka pustinja i njeni gradovi podignu svoj glas, naselja u kojima Kedar prebiva. Neka stanovnici Sele radosno pevaju; neka kliču od radosti s vrhova planina.“ (Isaija 42:11) Sledeći dokumenti potkrepljuju vezu Kedar–Poslanik ﷺ iz naučnih izvora: Kedar Pleme od kojega Kurejši potiču","headingId":"kedar-je-kurejs","headingText":"Kedar je Kurejš"},{"text":"Majmonid i Filip Šaf Jedan od najvećih jevrejskih učenjaka, Mojsije Majmonid, poistovećuje Kedar sa plemenom Kurejš. Filip Šaf Biblijski rečnik: „Prema predanju, Kedar je jedan od Muhamedovih predaka. Aramejski Targum zamenjuje Kedar Arapima. Ovde je reč „Kedar“ doslovno zamenjena rečju „Arapi“. Upadljiva sličnost između ovog slikovitog opisa i oblasti Hidžaza jasno se vidi u komentaru Čarlsa Fostera na 42. poglavlje Knjige proroka Isaije. Foster je bio anglikanski sveštenik iz 18. veka.","headingId":"majmonid-i-filip-saf","headingText":"Majmonid i Filip Šaf"},{"text":"Rabin Natanail iz Fajuma Rabin Natanail iz Fajuma, jedan od velikih srednjovekovnih rabina, verovao je u poslaničku misiju Muhameda ﷺ, premda je smatrao da je bio poslanik samo Arapima. U svojim delima često je navodio odlomke iz Kur ana, a Poslanika ﷺ nazivao je „Pravednikom“, govoreći: „Pravednik je rekao: ‘Kada bi se ljudi istinski oslonili na Boga, On bi ih opskrbio kao što opskrbljuje ptice: one odlaze gladne, a vraćaju se site.’“","headingId":"rabin-natanail-iz-fajuma","headingText":"Rabin Natanail iz Fajuma"},{"text":"Priznanje Adama Klarka Poslanici među Arapima Misionar Adam Klark prenosi priznanje da su Jevreji u vreme Hrista ﷺ verovali u poslanstvo proroka u Kraljevstvu Sabe i među stanovnicima arapskih zemalja. To predstavlja neoboriv odgovor onima koji su poricali da su Arapima slati poslanici zato što nisu pripadali sinovima Izrailjevim, kao i onima koji su poricali poslanstvo Šuajba, Huda i Saliha ﷺ jer se oni ne pominju u njihovim knjigama. Komentar na Mateja 2:1: Dođoše mudraci sa istoka odnosno, magi dođoše iz istočnih zemalja. ‘Jevreji su verovali da je u Kraljevstvu Sabe i Arabiji bilo proroka koji su poticali od Avrahama preko Keture i koji su poučavali u ime Boga, prema predanju koje su primili iz Avrahamovih usta.’. Gotovo da nema","headingId":"priznanje-adama-klarka-poslanici-medju-arapima","headingText":"Priznanje Adama Klarka - Poslanici među Arapima"},{"text":"sumnje da je među tim narodom bilo mnogo Jevreja; takođe ima osnova za verovanje da su ti istočnjački magi bilo da su bili filozofi, astrolozi ili nešto drugo možda prvobitno pripadali toj skupini.","headingId":"priznanje-adama-klarka-poslanici-medju-arapima","headingText":"Priznanje Adama Klarka - Poslanici među Arapima"},{"text":"Mitropolit Georgije Hodr Priznanje hrišćanskog mitropolita Georgija Hodra da je naš Poslanik Muhamed ﷺ bio monoteista koji je verovao u jednog jedinog Boga: Priznanje hrišćanskog mitropolita Georgija Hodra","headingId":"mitropolit-georgije-hodr","headingText":"Mitropolit Georgije Hodr"},{"text":"Poslanstvo među Arapima i Kedarovim potomcima „Kedar je Kurejš, Muhamedov predak.“ Prema jevrejskim i arapskim izvorima, Ketura je bila Avrahamova žena. Neki jevrejski izvori navode da su Ketura i Agara, Avrahamova žena, ista osoba. Prema tome, Agara bi bila majka Madijana Jetroovog naroda i Ismaila naroda Poslanika Muhameda ﷺ. Jevreji su Keturine potomke opisivali kao moćne Arape i uvek ih povezivali sa Istokom, nazivom koji se koristio za Arape. Prema jevrejskom predanju, Agara je bila kći arapskih kraljeva koji su vladali Egiptom. Sever ibn el Mukafa Istorija patrijaraha, str. 46: „Heraklije je usnio san u kojem mu je rečeno: ‘Obrezani narod krenuće protiv tebe, pobediće te i zavladati zemljom.’ Pomislio je da su to Jevreji. Zato je naredio krštenje svih","headingId":"poslanstvo-medju-arapima-i-kedarovim-potomcima","headingText":"Poslanstvo među Arapima i Kedarovim potomcima"},{"text":"Jevreja i Samarićana u svim oblastima pod njegovom vlašću. Međutim, posle nekoliko godina među Arapima se pojavio čovek po imenu Muhamed, iz Meke i njene okoline, koji je mnogobošce na Arabijskom poluostrvu vratio spoznaji jedinog Boga i ispovedanju da je Muhamed poslanik. Njegov narod bio je telesno obrezan, ali ne prema Mojsijevom zakonu, i molio se okrenut prema mestu koje su nazivali Kaba. Zavladao je Damaskom i Levantom. Gospod je učinio da rimska vojska poklekne pred njim zbog razvrata njihovih žena i crkvenih izopštenja koja su im prvi oci nametnuli zbog Halkidonskog sabora.“ Ismail će biti praotac dvanaest naroda, od njega je potekao arapski rod, a među njima su se pojavili muslimani. U jednom koptskom pravoslavnom rukopisu (COP 18 7,","headingId":"poslanstvo-medju-arapima-i-kedarovim-potomcima","headingText":"Poslanstvo među Arapima i Kedarovim potomcima"},{"text":"Teologija 7, iz 1773. godine), dvanaest kneževa poistovećuje se sa sledećima: Banu Hašim, Banu Abas, Banu el Safah, Banu el Hatab, Banu Jezid i Muavija, Banu Sufjan, Banu Mervan, Banu Abd el Aziz, Banu Afan, Banu Džafer, Banu el Mudi, Banu el Valid i Banu Umeja. Ovo je najsnažnije priznanje da tekst predskazuje kako će oni u budućnosti poverovati u jednog jedinog Boga. Isaija ﷺ daje nam jasno proročanstvo o tome da će stanovnici Arabijskog poluostrva prihvatiti poruku islama. Autor navoda iz Biblijskog rečnika pokušao je da umanji značaj ovoga ograničavajući tekst na kedarska plemena koja su živela na jugu Jordana. To je pogrešno iz tri razloga: 1. Kedarsko kraljevstvo nestalo je u petom veku pre nove ere, a nije","headingId":"poslanstvo-medju-arapima-i-kedarovim-potomcima","headingText":"Poslanstvo među Arapima i Kedarovim potomcima"},{"text":"poznato da su njegovi potomci među Arapima prihvatili neku monoteističku religiju osim islama. 2. Čak i ako pretpostavimo što je veoma malo verovatno da je njihovo potomstvo bilo ograničeno na plemena koja žive u toj oblasti, ta plemena danas čine muslimani koji ispovedaju veru u jednog Boga. 3. Jevrejski izvori nazivali su sve arapske beduine Kedarcima, bez obzira na to da li su zaista bili Kedarovi potomci. U svakom slučaju, ovo se može odnositi jedino na islam!","headingId":"poslanstvo-medju-arapima-i-kedarovim-potomcima","headingText":"Poslanstvo među Arapima i Kedarovim potomcima"},{"text":"Odeljak 3 Odgovor na hrišćanski prigovor Tvrdnja: Matej primenjuje Isaiju 42 na Isusa Hrišćani kažu: Nedvosmisleno je potvrđeno da se ovo proročanstvo odnosi na Isusa Hrista. Dovoljno je to što je jevanđelista Matej ovo potvrdio svojim navodom u Jevanđelju po Mateju 12:15. Mateju 12:15 23 Kada je Isus to doznao, napustio je to mesto. Mnoštvo ljudi ga je sledilo i on ih je sve iscelio. Isus im je napomenuo da ne otkrivaju ko je on, da bi se ispunilo ono što je Bog rekao po proroku Isaiji: „Evo Sluge moga, koga sam izabrao,voljenog mog, miljenika duše moje.Na njega ću Duha svoga izliti,da objavi pravdu narodima. Neće se prepirati, niti vikati,niti će se glas njegov čuti po ulicama. On neće slomiti","headingId":"odeljak-3-odgovor-na-hriscanski-prigovor","headingText":"Odeljak 3 - Odgovor na hrišćanski prigovor"},{"text":"trsku napuknutu,niti će ugasiti fitilj koji tinja,dok ne dovede pravo do pobede. Ime njegovo nada narodima biće.“ Ovu vrstu argumentacije ne odlikuje broj obmana, već način na koji obmanjuje i istrže navode iz konteksta. Često počinje na ovaj način kako bi čitalac od samog početka prihvatio obmanu, a zatim nastavio da prati izlaganje polazeći od nje. Odgovor na ovu tvrdnju sastoji se iz nekoliko tačaka:","headingId":"odeljak-3-odgovor-na-hriscanski-prigovor","headingText":"Odeljak 3 - Odgovor na hrišćanski prigovor"},{"text":"Prva tačka odgovora Ovo je mišljenje anonimnog pisca Jevanđelja po Mateju, a ne samog Isusa Ovde navedene reči predstavljaju mišljenje anonimnog pisca Jevanđelja po Mateju, a ne izjavu samog Isusa ﷺ. Navod u Mateju 12:17 predstavlja komentar pripovedača „da se ispuni što je rekao prorok Isaija“ a ne Isusovu izjavu o samome sebi.","headingId":"prva-tacka-odgovora-ovo-je-misljenje-anonimnog-pisca-jevandjelja-po-mateju-a-ne-samog-isusa","headingText":"Prva tačka odgovora - Ovo je mišljenje anonimnog pisca Jevanđelja po Mateju, a ne samog Isusa"},{"text":"Druga tačka odgovora Kontekst je izostavljen jer pobija tvrdnju Hrišćani su izostavili kontekst koji prethodi ovom navodu, jer celovit kontekst ruši njihovu tvrdnju i neposredno protivreči tekstu Isaije 42. Naveli su čitaoca da poveruje kako je mnoštvo koje je sledilo Isusa pripadalo narodima pomenutim u Isaiji 42, dok su to zapravo bili samo Izrailjci. Pročitajmo celovit kontekst: Mateju 12:1 15 Tih dana je Isus prolazio kroz žitna polja. Bila je subota. Njegovi učenici su bili gladni, pa su počeli da trgaju klasje i da jedu zrnevlje. Kada su fariseji to videli, rekli su Isusu: „Pogledaj! Tvoji učenici čine što ne sme da se čini subotom.“ Isus im odgovori: „Zar niste čitali šta je David učinio kada je ogladneo, on i","headingId":"druga-tacka-odgovora-kontekst-je-izostavljen-jer-pobija-tvrdnju","headingText":"Druga tačka odgovora - Kontekst je izostavljen jer pobija tvrdnju"},{"text":"njegovi pratioci? On je ušao u Dom Božiji i zajedno sa njima jeo postavljene hlebove koje, po Zakonu, nisu smeli da jedu ni on ni njegovi pratioci, nego samo sveštenici. Ili, zar niste čitali u Zakonu da sveštenici u hramu krše subotu, a ipak nisu krivi? A ja vam kažem da se ovde zbiva nešto važnije od hrama. Kada biste znali šta znači: ’Milosrđe hoću, a ne žrtvu’, ne biste osudili nevine. Jer, Sin Čovečiji je Gospodar subote.“ Isus je otišao odande i ušao u njihovu sinagogu. Tamo se našao neki čovek sa usahlom rukom. Fariseji su upitali Isusa: „Da li je dopušteno lečiti u subotu?“ To su ga pitali, nameravajući da ga optuže.11Isus im odgovori: „Ima li takvog među","headingId":"druga-tacka-odgovora-kontekst-je-izostavljen-jer-pobija-tvrdnju","headingText":"Druga tačka odgovora - Kontekst je izostavljen jer pobija tvrdnju"},{"text":"vama, koji ne bi svoju jedinu ovcu prihvatio i izvadio ako bi ova u subotu upala u jamu? A koliko je samo čovek vredniji od ovce! Prema tome, dozvoljeno je da se subotom čini dobro.“ Onda reče čoveku sa usahlom rukom: „Ispruži svoju ruku!“ Čovek ispruži ruku i ona postade zdrava kao i druga ruka. Tada fariseji izađoše i većajući skovaše zaveru kako da ubiju Isusa. Kada je Isus to doznao, napustio je to mesto. Mnoštvo ljudi ga je sledilo i on ih je sve iscelio. Tekst je jasan. Govori o izraelskom mnoštvu, a ne o mnoštvu neznabožaca. Čitavo poglavlje predstavlja raspravu između Isusa i fariseja o zakonu o suboti. To su upravo Izrailjci koji su raspravljali o jevrejskom verskom","headingId":"druga-tacka-odgovora-kontekst-je-izostavljen-jer-pobija-tvrdnju","headingText":"Druga tačka odgovora - Kontekst je izostavljen jer pobija tvrdnju"},{"text":"zakonu. Oni nisu stanovnici kedarske pustinje niti narod Sele koji kliče s planinskih vrhova. Kasnije ćemo govoriti o tome zašto su njegovi sledbenici i njegov poziv bili ograničeni na sinove Izrailjeve.","headingId":"druga-tacka-odgovora-kontekst-je-izostavljen-jer-pobija-tvrdnju","headingText":"Druga tačka odgovora - Kontekst je izostavljen jer pobija tvrdnju"},{"text":"Treća tačka odgovora Jezički argument Pored toga, Poslanik Muhamed ﷺ došao je sa jednim jezikom arapskim i nije govorio nijednim drugim jezikom. Stoga se postavlja pitanje: kako je onda mogao biti poslat svim narodima? Mi uzvraćamo istim pitanjem: da li je Isus poznavao neki jezik osim hebrejskog i aramejskog? Isus nije poznavao čak ni grčki jezik na kojem je napisan Novi zavet. Što se tiče optužbe u vezi sa Banu Kurejzom, to je pokušaj izazivanja sumnje pomoću neodređenih tvrdnji. Da li je prigovarač pročitao sopstvenu knjigu? Može li nam, na primer, reći kakva je sudbina zadesila Hanance, Madijance i druge narode u Starom zavetu? Ko živi u staklenoj kući ne treba da gađa druge kamenjem a ova kuća slabija je","headingId":"treca-tacka-odgovora-jezicki-argument","headingText":"Treća tačka odgovora - Jezički argument"},{"text":"i od paukove mreže.","headingId":"treca-tacka-odgovora-jezicki-argument","headingText":"Treća tačka odgovora - Jezički argument"},{"text":"Četvrta tačka odgovora Preusmeravanje na Pavla i Isaiju 53 Nakon toga prigovor menja pravac: uzima tekst iz Pavlovih reči u Filipljanima 2 kako bi filozofirao o značenju reči „sluga“ u Isaiji 42: Filipljanima 2:6 7 On, po obličju Bog,nije smatrao da biti jednak Bogu,jeste plen koji treba otimati, nego je lišio sebe časti,uzevši obličje sluge,postavši sličan ljudima. Kao čovek se pojavi, Zatim se navodi Isaija 53:11 kako bi se tvrdilo da se „sluga“ iz Isaije 42 odnosi na onoga koji nosi grehe. Potom se navodi Isaija 43:10–14 kao dokaz da je Spasitelj Bog. Argument tako skače sa Isaije 42 na Isaiju 53, pa na Isaiju 43. Na takav način prelaze sa jednog teksta na drugi samo oni koji nemaju neposredan","headingId":"cetvrta-tacka-odgovora-preusmeravanje-na-pavla-i-isaiju-53","headingText":"Četvrta tačka odgovora Preusmeravanje na Pavla i Isaiju 53"},{"text":"odgovor. Razmotrimo svaki element pojedinačno:","headingId":"cetvrta-tacka-odgovora-preusmeravanje-na-pavla-i-isaiju-53","headingText":"Četvrta tačka odgovora Preusmeravanje na Pavla i Isaiju 53"},{"text":"Pobijanje A Stari zavet izričito odbacuje nasledni greh i zamensko iskupljenje Knjige Starog zaveta jasno navode da se greh ne nasleđuje i da iskupljenje u smislu koji Crkva zastupa uopšte ne postoji. 4. Mojsijeva 16:22 Ali oni padoše na zemlju i rekoše: „O, Bože duhova svih stvorenja, zar ćeš se razgneviti na svu zajednicu zato što je jedan čovek sagrešio?“ 5. Mojsijeva 24:16 Neka se očevi ne pogubljuju zbog svojih sinova i neka se sinovi ne pogubljuju zbog svojih očeva. Svako treba da bude pogubljen za svoj greh. Jezekilj 18:20 22 Umreće onaj koji zgreši. Sin neće ispaštati zbog krivice svoga oca, a ni otac neće ispaštati zbog krivice svoga sina. Pravedniku će se računati njegova pravda, a opakome njegova","headingId":"pobijanje-a-stari-zavet-izricito-odbacuje-nasledni-greh-i-zamensko-iskupljenje","headingText":"Pobijanje A - Stari zavet izričito odbacuje nasledni greh i zamensko iskupljenje"},{"text":"opakost. Ali ako se opaki odvrati od svih svojih greha koje je učinio i bude držao sve moje uredbe i vršio pravo i pravdu, zaista će živeti, neće umreti. Nijedan od njegovih prestupa neće mu se više spominjati; zaista će živeti, neće umreti. A i Isaija sam kaže: Isaija 55:7 Neka opaki put svoj ostavi i nikogović svoje zamisli, i neka se Gospodu vrati, a on će mu se smilovati; i Bogu našem zato što umnožava praštanje.","headingId":"pobijanje-a-stari-zavet-izricito-odbacuje-nasledni-greh-i-zamensko-iskupljenje","headingText":"Pobijanje A - Stari zavet izričito odbacuje nasledni greh i zamensko iskupljenje"},{"text":"Pobijanje B Pravo značenje izraza „nositi bezakonje“ u Starom zavetu Tumačenje Isaije 53 kao zamenskog iskupljenja nije prihvatljivo, jer sam Stari zavet pokazuje šta znači „nositi bezakonje“. U Knjizi brojeva 18 čitamo: 4. Mojsijeva 18:1 Gospod reče Aronu: „Ti, tvoji sinovi i tvoj otački dom s tobom bićete odgovorni za krivice u Svetilištu. A ti i tvoji sinovi bićete odgovorni za krivice koje se tiču vašeg sveštenstva. Rabin Raši Komentar na Isaiju 53:11: I nosiće njihova bezakonja: nosiće ih onako kako ih nose svi pravednici, kao što je rečeno (Brojevi 18:1): ‘Ti i tvoji sinovi nosićete bezakonje svetilišta.’ Značenje je sledeće: svi propusti tadašnjeg naroda biće stavljeni na teret sluzi i smatraće se njegovim grehom zato što ih nije dovoljno","headingId":"pobijanje-b-pravo-znacenje-izraza-nositi-bezakonje-u-starom-zavetu","headingText":"Pobijanje B - Pravo značenje izraza „nositi bezakonje“ u Starom zavetu"},{"text":"poučavao a ne zato što je nasledio njihov greh. Otac Antonije Fikri Komentar na 4. Mojsijeva 18: „Ovde se Bog, nakon što se razgnevio na njih zbog gunđanja u vezi s Korejem, ponovo stara o njima. Oni snose krivicu ako zanemare poučavanje naroda. Međutim, ako pouče i upozore narod, a ljudi zatim svojevoljno zgreše, oni su nevini (Jezekilj 3).“","headingId":"pobijanje-b-pravo-znacenje-izraza-nositi-bezakonje-u-starom-zavetu","headingText":"Pobijanje B - Pravo značenje izraza „nositi bezakonje“ u Starom zavetu"},{"text":"Pobijanje C Isaija 53 predstavlja nastavak Isaije 52, koja govori o Izrailju Tekst Isaije 53 nastavak je 52. poglavlja, koje govori o onome čemu će izraelski narod biti izložen: Isaija 52:1 6 Probudi se! Probudi se!Odeni se u svoju snagu, Sione!Odeni se ogrtačem sjajnosti svoje,Jerusalime, grade sveti,jer u tebe više ulaziti nećeneobrezani i nečisti. Stresi sa sebe prašinu i ustani,ustoliči se, Jerusalime!Skini okove sa svoga vrata,zaboravljena ćerko sionska. Jer govori Gospod:„Eto, bili ste prodanii bez novca ćete biti otkupljeni.“ Jer govori Gospodar Gospod:„U Egipat je nekada narod moj sišao da tamo stranac bude,a Asir mu je ni zbog čega nasilje činio. A sada, zašto sam ja ovde? – govori Gospod.Zato što je bez razloga porobljen moj narod,a porobljivači njegovi likuju","headingId":"pobijanje-c-isaija-53-predstavlja-nastavak-isaije-52-koja-govori-o-izrailju","headingText":"Pobijanje C - Isaija 53 predstavlja nastavak Isaije 52, koja govori o Izrailju"},{"text":"– govori Gospod –i bez prestanka, povazdanvređa se moje ime. Zato će narod moj poznati ime moje.Zato će u onaj dan znatida sam ja onaj koji govori:’Evo me!’“ Isaija 52:13 15 „Gle, moj Sluga će uspevati,uzvisiće se i uzdignuti, i veoma uzveličati. Kako su se mnogi užasnuli nad njim:tako iznakažen njegov ljudski liki pojava njegova među potomcima ljudi. Ipak, poškropiće on narode mnoge,ni pisnuti neće carevi,jer videće što im niko objavio nije,i shvatiće o kome čuli nisu.“ Pod izrazom „Moj sluga“ ovde se misli na izraelski narod. Zato su jevrejski komentatori razumeli da se ovaj izraz odnosi na Izrailj. Rabin Raši Komentar na Isaiju 52:13: „Evo, Moj sluga će napredovati: evo, na kraju dana, Moj sluga Jakov [odnosno pravednici među","headingId":"pobijanje-c-isaija-53-predstavlja-nastavak-isaije-52-koja-govori-o-izrailju","headingText":"Pobijanje C - Isaija 53 predstavlja nastavak Isaije 52, koja govori o Izrailju"},{"text":"njegovim potomcima] napredovaće.“ A evo šta Biblijski rečnik hrišćana objavljuje jasno i glasno: Filip Šaf Biblijski rečnik: „Prema predanju, Kedar je jedan od Muhamedovih predaka.“ Lažovima nema utehe.","headingId":"pobijanje-c-isaija-53-predstavlja-nastavak-isaije-52-koja-govori-o-izrailju","headingText":"Pobijanje C - Isaija 53 predstavlja nastavak Isaije 52, koja govori o Izrailju"},{"text":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje U Van Dajkovom prevodu Isaije 53 stoji: Isaija 53:1 8 Van Dajkov prevod Ko je poverovao našoj poruci i kome se otkrila ruka Gospodnja? Izrastao je pred Njim poput nežne mladice i poput korena iz suve zemlje. Nije imao ni obličja ni veličanstva da bismo ga gledali, niti izgleda da bismo ga poželeli. Bio je prezren i odbačen od ljudi, čovek bola, upoznat s patnjom; poput nekoga od koga ljudi zaklanjaju lice. Bio je prezren i nismo ga cenili. Zaista je poneo naše patnje i nosio naše boli, a mi smo smatrali da ga Bog udara, kažnjava i ponižava. Ali on je bio ranjen zbog naših prestupa i satrven zbog naših","headingId":"hriscanski-prevodi-isaije-53-izmenili-su-kontekst-i-znacenje","headingText":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje"},{"text":"bezakonja. Kazna radi našeg mira bila je na njemu i njegovim smo ranama isceljeni. Svi smo lutali poput ovaca; svako se okrenuo svojim putem, a Gospod je na njega stavio bezakonje svih nas. Bio je tlačen i ponižavan, ali nije otvorio usta. Poput jagnjeta koje vode na klanje i poput ovce koja ćuti pred onima koji je strižu, tako ni on nije otvorio usta. Od tlačenja i suda bio je odveden. Ko je među njegovim naraštajem mogao pomisliti da je odsečen iz zemlje živih i kažnjen zbog prestupa moga naroda… Hebrejski masoretski tekst: צִיָּ֔ה הָדָ֑ר וְנִרְאֵ֥הוּ אִישִׁ֔ים אִ֥ישׁ מַכְאֹב֖וֹת וִיד֣וּעַ חֹ֑לִי וּכְמַסְתֵּ֚ר פָּנִים֙ מִמֶּ֔נּוּ נִבְזֶה סְבָלָ֑ם וַֽאֲנַ֣חְנוּ חֲשַׁבְנֻ֔הוּ נָג֛וּעַ מֻכֵ֥ה מְדֻכָּ֖א … וְלֹ֥א יִפְתַּ֖ח פִּֽיו … מִפֶּ֥שַׁע עַמִּ֖י נֶ֥גַע לָֽמוֹ","headingId":"hriscanski-prevodi-isaije-53-izmenili-su-kontekst-i-znacenje","headingText":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje"},{"text":"… לֹֽא־חָמָ֣ס עָשָׂ֔ה וְלֹ֥א מִרְמָ֖ה בְּפִֽיו Masoretski prevod (Jevrejsko izdavačko društvo JPS): Isaija 53:1–12 (masoretski tekst / prevod JPS a) Ko bi poverovao našoj poruci? I kome se otkrila ruka Gospodnja? Jer izrastao je pravo poput mladice i poput korena iz suve zemlje. Nije imao ni obličja ni krasote da bismo ga gledali, niti lepote da bismo u njemu uživali. Bio je prezren i napušten od ljudi, čovek bola, upoznat s bolešću, poput onoga od koga ljudi kriju lice. Bio je prezren i nismo ga cenili. Zaista je nosio naše bolesti i poneo naše boli, dok smo mi smatrali da ga Bog udara, kažnjava i ponižava. Ali bio je ranjen zbog naših prestupa i satrven zbog naših bezakonja. Kazna radi","headingId":"hriscanski-prevodi-isaije-53-izmenili-su-kontekst-i-znacenje","headingText":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje"},{"text":"našeg blagostanja bila je na njemu i njegovim smo ranama isceljeni. Svi smo poput ovaca zalutali; svako se okrenuo svojim putem, a Gospod je učinio da na njega padne bezakonje svih nas. Bio je tlačen, ali se ponizio i nije otvorio usta. Poput jagnjeta koje vode na klanje i poput ovce koja ćuti pred onima koji je strižu, ni on nije otvorio usta. Tlačenjem i sudom bio je odveden, a ko je razmišljao o njegovom naraštaju? Jer bio je odsečen iz zemlje živih zbog prestupa moga naroda, kojem je udarac pripadao. Odredili su mu grob među zlima, a grobnicu među bogatima, premda nije počinio nasilje niti je bilo prevare u njegovim ustima. Ipak, Gospodu je bilo po volji da ga","headingId":"hriscanski-prevodi-isaije-53-izmenili-su-kontekst-i-znacenje","headingText":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje"},{"text":"satre bolešću, da vidi hoće li njegova duša prineti sebe kao žrtvu za naknadu krivice, kako bi video svoje potomstvo, produžio svoje dane i kako bi se Gospodnja namera ostvarila njegovom rukom. Videće puni plod muke svoje duše — Moj sluga, koji je svojim znanjem opravdao Pravednika pred mnogima, i nosio njihova bezakonja. Zato ću mu dati deo među velikima i deliće plen sa silnima, jer je svoju dušu izlio u smrt i bio ubrojan među prestupnike. Ipak, nosio je greh mnogih i posredovao za prestupnike.","headingId":"hriscanski-prevodi-isaije-53-izmenili-su-kontekst-i-znacenje","headingText":"Hrišćanski prevodi Isaije 53 izmenili su kontekst i značenje"},{"text":"Uočene manipulacije u prevodu Tri prevodilačke manipulacije u Isaiji 53 Manipulacija 1: Izrazi „za naše prestupe“ i „za naša bezakonja“ u 5. stihu nisu ispravno prevedeni. Ispravan prevod glasi „zbog naših prestupa“ i „zbog naših bezakonja“, jer masoretski tekst koristi predlog מִ („zbog“), a ne לְ („za“). Manipulacija 2: Izraz „naša bezakonja“ takođe je pogrešno preveden u 6. stihu. Trebalo bi da glasi „zbog našeg bezakonja“, kao što je prethodno navedeno. Manipulacija 3: Izraz „Gospod je na njega položio bezakonje svih nas“ u 6. stihu nije ispravan. Tačan prevod glasi: „Učinio je da snosi nepravdu svih nas“, jer masoretski tekst koristi reč עָוֺן ( avon ), koja označava bezakonje u smislu nepravde i kazne, a ne krivicu ili greh prenet","headingId":"uocene-manipulacije-u-prevodu","headingText":"Uočene manipulacije u prevodu"},{"text":"na drugoga. U istom poglavlju, u 9. stihu, čitamo: „Jer nije učinio nikakvo nasilje niti je bilo prevare u njegovim ustima.“ To pokazuje da je sluga opisan kao nevin, a ne kao neko ko plaća za krivicu drugih. Leksikografski dokazi Leksikon Braun–Drajver–Brigs Odrednica H5771 עָוֺן: „Bezakonje, krivica ili kazna za bezakonje. Posledica bezakonja ili kazna za njega. Isaija 53:11: snosiće posledice njihovih bezakonja. Isaija 53:6: הִפְגִּיעַ značenje Isaije 53:6 jeste da je Gospod podneo naša bezakonja protiv Njega bezakonja izraelskog naroda odnosno, oprostio ih je i umilostivio se u pogledu bezakonja svih nas, kako ne bi uništio svoj svet.“ Strongov rečnik Odrednica H5771 עָוֺן: „עָוֺן ( avon ) od H5753; izopačenost, odnosno moralno zlo krivica, bezakonje, zlodelo ili kazna za","headingId":"uocene-manipulacije-u-prevodu","headingText":"Uočene manipulacije u prevodu"},{"text":"bezakonje.“ Ispravno tumačenje 11. stiha već je prethodno navedeno. Takođe ponavljamo da je u prevodu pogrešno upotrebljen izraz „njihova bezakonja“ ispravan izraz glasi „njihova nepravda“.","headingId":"uocene-manipulacije-u-prevodu","headingText":"Uočene manipulacije u prevodu"},{"text":"Pobijanje D Isaija 53 ne može se odnositi na Isusa Prvo: Isaija 53:10 zahteva potomstvo i dug život Isaija 53:10 (masoretski tekst / prevod JPS a) Ipak, Gospodu je bilo po volji da ga satre bolešću, da vidi hoće li njegova duša prineti sebe kao žrtvu za naknadu krivice, kako bi video svoje potomstvo, produžio svoje dane i kako bi se Gospodnja namera ostvarila njegovom rukom. Isaija 53:10 (Van Dajkov prevod) Ali Gospodu je bilo po volji da ga satre; izložio ga je patnji. Ako prinese sebe kao žrtvu za greh, videće svoje potomstvo, produžiće svoje dane i volja Gospodnja napredovaće u njegovoj ruci. Dakle, da li je Isus dugo živeo ili je umro u tridesetoj godini? Da li se","headingId":"pobijanje-d-isaija-53-ne-moze-se-odnositi-na-isusa","headingText":"Pobijanje D - Isaija 53 ne može se odnositi na Isusa"},{"text":"Isus oženio i imao decu? Odgovor je: nije. Prema tome, ovo poglavlje ne možemo primeniti na Isusa. Naravno, kao što im je običaj kada naiđu na problem pri tumačenju teksta prema njegovom očiglednom značenju, pribegavaju takozvanom duhovnom tumačenju odstupaju od jasnog značenja teksta i pripisuju mu ono što ne sadrži kako bi izbegli tešku protivrečnost. Otac Antonije Fikri Komentar na Isaiju 53:10: „Videće potomstvo potomstvo su vernici koje je On iskupio. On je bio zrno pšenice koje je palo kako bi nastalo mnogo zrna. Njegovi dani biće dugi = odnosno, njegov život neće se završiti smrću. Ovo je proročanstvo o vaskrsenju.“ To je izlaz u nuždi. „Potomstvo“ su protumačili kao duhovne sledbenike, a „produženje njegovih dana“ kao vaskrsenje. To nije","headingId":"pobijanje-d-isaija-53-ne-moze-se-odnositi-na-isusa","headingText":"Pobijanje D - Isaija 53 ne može se odnositi na Isusa"},{"text":"egzegeza, već eisegeza. Ko je primoran da napusti doslovno značenje jasnog teksta kako bi spasao svoje tumačenje, već je izgubio raspravu. Drugo: Isaija 53:8 ograničava delovanje sluge isključivo na Izrailj Isaija 53:8 Od vlasti i od suda on je izuzet. I ko će da ispriča šta je posle bilo? Jer iz zemlje živih je izdvojen, zbog greha mog naroda on je tučen. Izraz „moj narod“ u ovom kontekstu odnosi se na Izrailj, a ne na čitavo čovečanstvo. To neposredno protivreči crkvenoj tvrdnji da je sluga umro zbog grehova svih ljudi.","headingId":"pobijanje-d-isaija-53-ne-moze-se-odnositi-na-isusa","headingText":"Pobijanje D - Isaija 53 ne može se odnositi na Isusa"},{"text":"Pobijanje E Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje U prigovoru se navodi Isaija 43:10–14 kako bi se tvrdilo da je „Spasitelj“ u Starom zavetu ovaploćeni Bog te da je stoga sluga koji spasava božanski Isus. Pročitajmo celovit kontekst: Isaija 43:1 16 Sada govori Gospod,koji te je stvorio, Jakove,koji te je načinio, Izrailju:„Ne boj se, jer ja sam te otkupio,po imenu te pozvao: ti si moj.Kad preko vode prelaziš,ja sam s tobom;preko reka,neće te preplaviti.Prođeš li kroz vatru,nećeš izgoreti,i plamen te opaliti neće,jer ja sam Gospod, Bog tvoj,Izrailjev Svetitelj, tvoj Spasitelj.Da tebe otkupim, dajem Egipat;umesto tebe dajem Kuš i Sevu.Jer ti si dragocen u mojim očima,cenjen si i ja te volim.Zato i dajem čoveka umesto tebe,i narode trampim","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"za život tvoj.Ne boj se, jer ja sam s tobom.Sa istoka ću potomstvo tvoje dovesti,i sa zapada ću te sakupiti.Reći ću severu: ’Daj mi!’i jugu: ’Ne zadržavaj ga!’Sinove moje dovedi izdaleka,i ćerke moje s kraja zemlje,svakog ko se imenom mojim zove,i koga sam na slavu svoju stvorio,zamislio ga, pa ga načinio.Gospod je jedini Bog Izvedi narod slep, premda ima oči,i gluv, premda ima uši.Neka se zajedno saberu sva plemena,i neka se sakupe narodi.Je li ko od njih ovo najavio,i od davnina nam predskazao?Nek dovedu svoje svedoke i opravdaju se.Neka se čuje, pa nek kažu: ’Istina je!’Vi ste svedoci moji – govori Gospod –i sluge moje koje sam izabrao,da biste znali i meni verovali,i shvatili da sam to ja.Pre mene nijedan","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"bog sazdan ne bi,a neće ni posle mene biti. Ja, ja sam Gospod,osim mene spasitelja nema. Ja sam najavio i spasao i predskazao,i među vama tuđinaca nema!A vi ste svedoci moji – govori Gospod –i ja sam Bog. Od večnosti ja to jesam,i niko iz moje ruke izbaviti neće.Učiniću, a ko će izmeniti?“ Govori Gospod,vaš Otkupitelj, Izrailjev Svetitelj:„Vas radi poslao sam prema Vavilonu,i oboriću begunce, sve njih;a Haldejci će klicati u lađama. Ja sam Gospod, vaš Svetitelj,Izrailjev stvoritelj, vaš car!“ Govori Gospod,koji načini put po moru,i po vodama silnim prolaz, Poglavlje počinje tako što se Bog obraća Jakovu, odnosno Izrailju. Izraz „Moj sluga, koga sam izabrao“ odnosi se na Jakova to jest na Izrailj a ne na Hrista ﷺ. Kontekst","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"predstavlja govor između Svemogućeg Boga i izraelskog naroda: „Vi ste Moji svedoci, o narodi, i Moj sluga Jakov, koga sam izabrao.“ Rabin Raši Komentar na Isaiju 43:10: „I Moj sluga: Jakov, koga sam izabrao. I on će posvedočiti da sam mu dao obećanje kada je otišao u Mesopotamiju i da sam svoje obećanje ispunio. Da biste spoznali: sve sam to učinio kako biste primili k srcu da Me upoznate.“ Džejmison–Fosit–Braun Komentar na Isaiju 43:10: „I Moj sluga odnosno, čitav jevrejski narod (Isaija 41:8).“ Reč „Spasitelj“ ovde označava političko izbavljenje, a ne iskupljenje od greha Što se tiče upotrebe reči „Spasitelj“, i to predstavlja zloupotrebu teksta. U prigovor se umeće učenje o iskupljenju na način koji kontekst ne podržava. Iz samog","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"konteksta čitamo da je Spasitelj ovde poslao narod protiv Vavilona, srušio njegove zasune i oterao Haldejce na njihove lađe. Reč je o nacionalnom izbavljenju od vojnog osvajanja, a ne o duhovnom iskupljenju od greha. Ista reč upotrebljena je u istom značenju i u Osiji: Osije 13:4 11 „A ja sam bio Gospod,Bog tvoj, još od zemlje egipatske,osim mene ne znaš za druge bogove.Osim mene Spasitelja nema. Ja sam tebe posmatrao u pustinji,u zemlji sasušenoj. Nasitili su se na pašnjaku svome.Nasitili su se, srcem ogordilii zato me zaboravili. Poput lava ja ću za njih biti,poput risa što kraj puta vreba.8Presrešću ih kao medvedica kojoj su oteli medvediće,do srca im grudi rastrgnuti.Proždraću ih onde kao lav,raskomadaće ih divlje zveri.Satrven si, Izrailju,jer si","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"protiv mene, protiv svoga pomoćnika!Gde je sada car tvoj da te spaseu svim tvojim gradovima, tvoje sudije?A za njih si govorio: ’Daj mi cara i glavare!’I u gnevu svome cara sam ti dao,ali sam ga i uzeo u jarosti svojoj. Isto čitamo u Jeremiji 14: Jeremija 14:7 10 Naše krivice svedoče protiv nas.A ti ipak, Gospode, deluj radi svoga imena,jer su mnoga naša otpadništva.Protiv tebe smo sagrešili!Nado Izrailjeva,Spasitelju njegov u času nevolje!Zašto si poput došljaka u zemljii putnika što bi tek usput da prenoći?Zašto si kao smeten čovek,kao junak nemoćan da spase?A ti si među nama, o, Gospode,i tvoje je ime prizvano na nas.Ne napuštaj nas!Evo šta kaže Gospod ovom narodu:„Oni baš vole da lutaju,ne sputavaju u tome korake svoje.I","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"Gospod ih nije prihvatioi sada se seća njihovih krivicai kazniće njihove grehe.“ Spasitelj je u kontekstu ovih tekstova onaj koji izbavlja narod od spoljašnje opasnosti ili strane najezde. To potvrđuje i leksikon: Leksikon Braun–Drajver–Brigs Odrednica H3467 יָשַׁע: „Glagol u hifilu izbaviti. O Bogu, koji spasava svoj narod od spoljašnjih zala. Prema tome, Bog je Spasitelj Isaija 43:11; Isaija 45:15, 21; Isaija 63:8; Osija 13:4.“","headingId":"pobijanje-e-argument-o-spasitelju-iz-isaije-43-ne-potvrdjuje-ovaplocenje","headingText":"Pobijanje E - Argument o „Spasitelju“ iz Isaije 43 ne potvrđuje ovaploćenje"},{"text":"Pobijanje F Argument o izrazu „u kome uživa Moja duša“ Zaustavimo se na još jednoj važnoj rečenici iz hrišćanskog argumenta: „Moj izabranik, u kome uživa Moja duša.“ Prigovarač pita: ko je taj u kome uživa Božja duša? Zatim navodi: Matej 3:17 Tada se začuo glas s neba: „Ovo je Sin moj voljeni, koji mi je sva radost!“ Postavlja se pitanje: da li je vaš poslanik jedini Sin Božji, kojim je Božja duša bila zadovoljna? Odgovor je jednostavan. Ovo pitanje meša dve različite stvari. Izraz „u kome uživa Moja duša“ u Isaiji 42:1 odnosi se na slugu izabranog za misiju donošenja pravde narodima. Stih iz Mateja 3:17 predstavlja jevanđelistov izveštaj o glasu koji se čuo prilikom Isusovog krštenja. To su dva","headingId":"pobijanje-f-argument-o-izrazu-u-kome-uziva-moja-dusa","headingText":"Pobijanje F - Argument o izrazu „u kome uživa Moja duša“"},{"text":"potpuno različita tekstualna konteksta. Skakanje između njih od Isaije 42, preko Isaije 53 i Isaije 43, do Mateja 3:17 predstavlja mešanje potpuno različitih stvari. To čine samo oni koji nemaju neposredan odgovor.","headingId":"pobijanje-f-argument-o-izrazu-u-kome-uziva-moja-dusa","headingText":"Pobijanje F - Argument o izrazu „u kome uživa Moja duša“"},{"text":"Pobijanje G Prigovor „Sluga = Izrailj“ Prigovor: „Isaija 41:8 u prethodnom poglavlju veoma jasno određuje ko je ‘sluga’. To nije pojedinac, već Bnei Jisrael izraelski narod.“ Ipak, Targum primenjuje Isaiju 42 na pojedinca Mesiju. U poglavljima Isaije 40–55 ne postoji samo jedan sluga, već dvojica. Isaija 49 izričito govori o pojedinačnom sluzi. Isaija 49 i Isaija 42 imaju mnogo više zajedničkih jezičkih paralela nego Isaija 41 i Isaija 42. Prema tome, sluga iz Isaije 42 nije izraelski narod, već pojedinačni sluga opisan i u Isaiji 49. To je spomenuo i Ibn Ezra, videti njegove komentare na Isaiju 42 i Isaiju 49. Da, Isaija 41 je tekstualno bliža Isaiji 42. Međutim, Isaija 49 joj je bliža po paralelnom jeziku. Zato se","headingId":"pobijanje-g-prigovor-sluga-izrailj","headingText":"Pobijanje G - Prigovor „Sluga = Izrailj“"},{"text":"mnogi slažu da su sluga iz Isaije 42 i sluga iz Isaije 49 ista osoba. Možete proveriti i druge rabine, široko je prihvaćeno da se Isaija 49 odnosi na pojedinca. Razmotrimo sledeće: u Isaiji 49 misija sluge usmerena je prema Izrailju. Izraelski narod ne može biti poslat izraelskom narodu. Sluga je poslat da obnovi Izrailj i vrati Jakova Bogu: Njegova misija usmerena je prema Izrailju. Poslat je da vrati Jakova Bogu. Poslat je da obnovi Izrailj. Prema tome, sluga je pojedinac, a ne narod. Čak ni rabini koji su Isaiju 49 primenjivali na proroka Isaiju nisu razumeli reč „Izrailj“ kao doslovno ime naroda. Ona se može objasniti kao pesnički izraz, sluga se naziva „Izrailjem“ zato što je njegova misija povezana","headingId":"pobijanje-g-prigovor-sluga-izrailj","headingText":"Pobijanje G - Prigovor „Sluga = Izrailj“"},{"text":"sa Izrailjem ili kao funkcionalna, a ne doslovna oznaka. Rabini su ispravno razumeli da se Isaija 49 odnosi na pojedinca. Pogrešili su kada su je primenili na samog proroka Isaiju. To je pogrešno zato što Isaija nije ispunio ono što se navodi u pesmama o sluzi. Na primer, nije priveo narode monoteizmu.","headingId":"pobijanje-g-prigovor-sluga-izrailj","headingText":"Pobijanje G - Prigovor „Sluga = Izrailj“"}]},{"slug":"Mojsijev-zavet-i-racun-godina","chunks":[{"text":"Kuran pominje da će sinovi Izrailjevi dva puta činiti nered i da će dva puta biti kažnjeni, što veoma podseća na obrazac iz Mojsijevog zaveštanja . Knjiga zatim navodi da će od Mojsijeve smrti i sahrane do dolaska očekivanog proroka proći 250 sedmica godina. Pošto 250 sedmica godina iznosi 1.750 godina, a Mojsijeva smrt može se smestiti približno u 1183. godinu pre nove ere, očekivani prorok trebalo bi da bude rođen između 567. i 574. godine nove ere. Poslanik Muhamed ﷺ rođen je 570. godine nove ere, upravo unutar tog razdoblja. Snaga ovog argumenta jeste u tome što je relevantni rukopis pronađen u Milanu tek 1861. godine i što je vekovima ostao nepoznat, zbog čega Poslanik ﷺ nikako nije mogao","headingId":"","headingText":""},{"text":"preuzeti njegov sadržaj. Zato ovo proročanstvo zaslužuje pažljivo razmatranje kao jedan od izuzetnih znakova koji upućuju na dolazak Poslanika Muhameda ﷺ.","headingId":"","headingText":""},{"text":"Još jedno proročanstvo o očekivanom proroku Još jedno proročanstvo nalazi se u pseudepigrafskom delu Mojsijevo zaveštanje . Ova knjiga govori o tome kako je Mojsije pred smrt predao svome sledbeniku Jošui, sinu Nunovom, knjigu koja predskazuje šta će se događati Jevrejima u budućim razdobljima.","headingId":"jos-jedno-prorocanstvo-o-ocekivanom-proroku","headingText":"Još jedno proročanstvo o očekivanom proroku"},{"text":"Mojsijevo zaveštanje i njegovo otkriće","headingId":"mojsijevo-zavestanje-i-njegovo-otkrice","headingText":"Mojsijevo zaveštanje i njegovo otkriće"},{"text":"Istorijska pozadina Bog ih potom, posredstvom jednog milostivog kralja, vraća u Obećanu zemlju. Hram se ponovo gradi, a Bog ih osnažuje potomstvom i brojnim ljudstvom. Međutim, Izrailjci se ponovo bune protiv Boga, pa On šalje kralja sa Zapada koji drugi put razara Sveti dom i spaljuje deo svetog Hrama. Ovo drugo razaranje teže je od prvog. Nakon izvesnih događaja pojavljuju se očekivani prorok i Božje carstvo, 250 sedmica posle Mojsijeve smrti mir neka je na njega.","headingId":"istorijska-pozadina","headingText":"Istorijska pozadina"},{"text":"Otkriće knjige Rukopis potiče iz šestog veka nove ere, što znači da je njegovim vlasnicima ostao nepoznat više od trinaest vekova. Do sada je pronađen samo ovaj rukopis knjige. Napisan je na latinskom, prema hebrejskom ili aramejskom izvorniku nastalom u prvom veku nove ere. Naučnici smatraju da je pripadao jevrejskoj sekti Esena. Ovo je navedeno u uvodu knjige Starozavetni pseudepigrafi .","headingId":"otkrice-knjige","headingText":"Otkriće knjige"},{"text":"Zašto Poslanik ﷺ ovo nije mogao preuzeti Nemoguće je da je Poslanik ﷺ pročitao ovu knjigu na njenom jeziku ili da mu ju je neko pročitao, da je zatim otkrio ovo zapanjujuće podudaranje i znak o vremenu pojavljivanja proroka prema sledbenicima Knjige, pa na osnovu toga proglasio svoje poslanstvo i obavestio Jevreje i hrišćane da se to nalazi u njihovim spisima.","headingId":"zasto-poslanik-ovo-nije-mogao-preuzeti","headingText":"Zašto Poslanik ﷺ ovo nije mogao preuzeti"},{"text":"Proročanstvo i sura El Isra Pre razmatranja pojedinosti radosne vesti, prvo zapažamo da ovo proročanstvo snažno podseća na početak sure El Isra. El Isra 17:4–8 I Mi smo u Knjizi objavili Izrailjevim sinovima: „Vi ćete zaista dva puta nered na Zemlji da učinite i uveliko da se oholite.“ Kada dođe vreme prve pretnje, poslaćemo protiv vas Naše sluge žestoke snage, oni će uzduž i popreko zemlju vašu da pregaze, i obećanje o kazni će da se ispuni. Zatim ćemo da vam damo pobedu protiv njih i povećaćemo vam imovinu i sinove i učinićemo vas brojnijim. Sve što činite činite sebi, dobro i zlo. A kad dođe vreme druge pretnje, poslaćemo ih da na licima vašim tugu i jad ostave i","headingId":"prorocanstvo-i-sura-el-isra","headingText":"Proročanstvo i sura El-Isra"},{"text":"da u Hram kao i prvi put, ponovo provale i da sve što osvoje do temelja poruše. I Gospodar će vam se vaš opet smilovati; ali ako se vratite neredu, vratićemo se i Mi kazni. A Pakao smo za nevernike učinili tamnicom.","headingId":"prorocanstvo-i-sura-el-isra","headingText":"Proročanstvo i sura El-Isra"},{"text":"Prvo i drugo razaranje Izrailjaca Jedna grupa protumačila je ovo kao buduće događaje. Prema tom tumačenju, muslimani su Božji robovi koji su prvi put ušli u Hram, odnosno Jerusalim, i ponovo će ući u njega pred kraj vremena. Druga grupa smatrala je da se radi o prošlim događajima, ali su se njeni pripadnici razišli u određivanju naroda koji su pobedili Jevreje.","headingId":"prvo-i-drugo-razaranje-izrailjaca","headingText":"Prvo i drugo razaranje Izrailjaca"},{"text":"Prvo razaranje kralj sa Istoka Prvo razaranje, koje je izvršio kralj sa Istoka, moglo bi se odnositi na uništenje severnog izraelskog kraljevstva koje je izvršio asirski kralj Salmanasar, kao u Drugoj knjizi o kraljevima 17, ili na uništenje južnog Judejskog kraljevstva koje je izvršio vavilonski kralj Navuhodonosor, kao u Drugoj knjizi o kraljevima 21. Obojica su došla sa Istoka, odnosno iz oblasti istočno od Palestine. Ipak, verovatnije je da se misli na vavilonskog kralja, jer je taj događaj bio veći i poznatiji i jer je tada Hram razoren, kao što se navodi u proročanstvu. U ropstvo je odvedeno Judino pleme, što dodatno potvrđuje da se misli na vavilonskog kralja.","headingId":"prvo-razaranje-kralj-sa-istoka","headingText":"Prvo razaranje - kralj sa Istoka"},{"text":"Drugo razaranje kralj sa Zapada U pitanju su kraljevi sa Zapada, kao što proročanstvo navodi. Oni su ponovo razorili Hram, što se takođe pominje u proročanstvu. Videti istorijsku tabelu u uvodu Svetog pisma , izdanje Dar el Šark.","headingId":"drugo-razaranje-kralj-sa-zapada","headingText":"Drugo razaranje - kralj sa Zapada"},{"text":"Tumačenje sure El Isra 4–8 Videli smo da Tora i istorijske knjige navode da su prvo razaranje izvršili Vavilonci, a drugo Rimljani. To podržava tumačenje prema kojem su dva razaranja pomenuta u suri El Isra prošli događaji: prvo su izvršili Vavilonci, a drugo Rimljani.","headingId":"tumacenje-sure-el-isra-48","headingText":"Tumačenje sure El-Isra 4–8"},{"text":"Značenje izraza „Naši robovi“","headingId":"znacenje-izraza-nasi-robovi","headingText":"Značenje izraza „Naši robovi“"},{"text":"Mogući prigovor Neki muslimanski komentatori tvrdili su da se izraz „Naši robovi“ mora odnositi na muslimane jer se izrazi „Božji robovi“ i „robovi Milostivog“ koriste samo za one koji su pokorni Bogu.","headingId":"moguci-prigovor","headingText":"Mogući prigovor"},{"text":"Odgovor Međutim, opis prvih pobednika nad Jevrejima u Kur anu glasi: „Naši robovi, silno moćni.“ Jeremija 25:9 Evo, ja šaljem i donosim sve rodove sa severa – govori Gospod – i Navuhodonosora, cara Vavilona, moga slugu. Dovešću ih na ovu zemlju, na njene stanovnike i na sve ove okolne narode. Izručiću ih kletom uništenju, pretvoriću ih u pustoš, u ruglo i ruševine večne. Šta sprečava Navuhodonosora da, po Božjoj zapovesti, krene u rat protiv Jevreja kako bi ih kaznio, iako je bio nevernik? U tom smislu pripadnici njegove vojske mogu se nazvati „Božjim robovima“ jer su izvršavali božansku kaznu. Kur an ovaj izraz koristi i za nevernike na budućem svetu, jer tada neće imati izbora osim da se pokore Bogu.","headingId":"odgovor","headingText":"Odgovor"},{"text":"Sura El Furkan 25:17 A na Dan kada ih On sakupi, a i one koje su pored Allaha obožavali, pa upita: „Jeste li vi ove Moje sluge zaveli u zabludu, ili su oni sami zalutali sa Pravog puta?“","headingId":"odgovor","headingText":"Odgovor"},{"text":"Povratak iz vavilonskog ropstva Neobično je što Kur anski odlomak navodi da su Jevreji, nakon prvog poraza svojih osvajača, ponovo dobili snagu i postali brojniji i sposobniji za pružanje pomoći. 2. knjiga dnevnika 36:22–23 Prve godine Kira, cara Persije, da bi se ispunila reč Gospodnja kazana preko Jeremije, Gospod je podigao duh Kira, cara Persije. Tako je on dao da celim njegovim carstvom prođe proglas, i još ga je objavio napismeno. „Ovako kaže Kir, car Persije: ’Sva zemaljska carstva mi je dao Gospod Bog nebeski. On mi je i zapovedio da mu izgradim Dom u Jerusalimu, u Judi. Ko god je među vama od sveg njegovog naroda, neka je sa njim Gospod, Bog njegov, i neka ide gore.’“ Tora navodi","headingId":"povratak-iz-vavilonskog-ropstva","headingText":"Povratak iz vavilonskog ropstva"},{"text":"da su se Jevreji vratili iz vavilonskog ropstva uz pomoć persijskog kralja Kira. Ovo podržavaju i reči Svemogućeg nakon pripovedanja o tim događajima: El Isra 17:8 I Gospodar će vam se vaš opet smilovati; ali ako se vratite neredu, vratićemo se i Mi kazni. A Pakao smo za nevernike učinili tamnicom. Značenje je da bi ih Svemogući Bog mogao ponovo kazniti novim razaranjem, pored dva već pomenuta.","headingId":"povratak-iz-vavilonskog-ropstva","headingText":"Povratak iz vavilonskog ropstva"},{"text":"Kur anski odlomak i Mojsijevo zaveštanje „Možda će vam se vaš Gospodar smilovati…“ Moguće značenje jeste da će ih Bog ponovo kazniti ako ne poveruju u očekivanog proroka koji je najavljen u njihovim spisima i koji će se pojaviti nakon dva razaranja, kao što navodi Mojsijevo zaveštanje . Zanimljivo je da Kur an kaže: „I Mi smo u Knjizi objavili sinovima Izrailjevim…“ A zatim u Mojsijevom zaveštanju čitamo da je Mojsije ovo proročanstvo ostavio Jošui zapisano u knjizi. Kuranski odlomak iz sure El Isra, stihovi 4–8, gotovo se podudara sa Mojsijevim zaveštanjem , koje je pronađeno tek u devetnaestom veku.","headingId":"kuranski-odlomak-i-mojsijevo-zavestanje","headingText":"Kur`anski odlomak i Mojsijevo zaveštanje"},{"text":"Vreme pojavljivanja očekivanog proroka Kada govori o vremenu pojavljivanja očekivanog proroka, što je naša tema, Mojsijevo zaveštanje najpre navodi da se on neće pojaviti pre drugog razaranja, odnosno nakon 135. godine nove ere: Prvo razaranje izvršio je kralj sa Istoka. Drugo razaranje izvršio je kralj sa Zapada.","headingId":"vreme-pojavljivanja-ocekivanog-proroka","headingText":"Vreme pojavljivanja očekivanog proroka"},{"text":"Izračunavanje 250 sedmica Mojsije govori Jošui da se prorok poslednjeg vremena neće pojaviti pre nego što od njegove smrti prođe 250 sedmica. Jedna sedmica u jevrejskim proročkim knjigama predstavlja sedam godina. Prema tome: 250 × 7 = 1.750 godina To znači da će se prorok poslednjeg vremena roditi tokom 251. sedmice, odnosno između: 1.750 i 1.757 godina nakon Mojsijeve smrti mir neka je na njega.","headingId":"izracunavanje-250-sedmica","headingText":"Izračunavanje 250 sedmica"},{"text":"Datum Mojsijeve smrti Hrišćanski i jevrejski istoričari gotovo se ne razilaze u mišljenju da je Ramzes II bio faraon iz Mojsijevog vremena. Videti, na primer, istorijsku tabelu u uvodu Svetog pisma , izdanje Dar el Mašrik. Mojsije je morao umreti najmanje četrdeset godina nakon toga, odnosno nakon razdoblja lutanja, kao što navode Kur an i Tora. Kuran u suri El Maida govori o razdoblju lutanja. Al Maidah 5:26 „Četrdeset godina oni će zemljom da lutaju“, reče On, „jer će Sveta zemlja da im bude zabranjena, a ti ne tuguj za grešnim narodom.“ Knjiga brojeva takođe pominje četrdesetogodišnje lutanje. 4. Mojsijeva 14:33 Vaša deca će biti pastiri u pustinji četrdeset godina i ispaštati zbog vašeg neverstva, dok vaša tela do poslednjeg","headingId":"datum-mojsijeve-smrti","headingText":"Datum Mojsijeve smrti"},{"text":"ne propadaju mrtva u pustinji.","headingId":"datum-mojsijeve-smrti","headingText":"Datum Mojsijeve smrti"},{"text":"Proračun Prema tome, Mojsije mir neka je na njega umro je 1183. godine pre nove ere ili nešto kasnije.","headingId":"proracun","headingText":"Proračun"},{"text":"Razdoblje rođenja očekivanog proroka Ako datum rođenja očekivanog proroka računamo u odnosu na rođenje Isusa Hrista, od razdoblja pomenutog u proročanstvu oduzimamo datum Mojsijeve smrti: 1.757 − 1.183 = 574. godina nove ere Dobijamo razdoblje: 567–574. godine nove ere Poznato je da je Poslanik islama ﷺ rođen 570. godine nove ere. Dakle, rođen je upravo unutar tog razdoblja.","headingId":"razdoblje-rodjenja-ocekivanog-proroka","headingText":"Razdoblje rođenja očekivanog proroka"},{"text":"Svitci sa Mrtvog mora i Mojsijevo zaveštanje Među Svicima sa Mrtvog mora pronađen je primerak Mojsijevog zaveštanja . Ovi svici objavljeni su 1992. godine. Tekst se ne razlikuje mnogo od ranije pomenutog rukopisa pronađenog u Ambrozijanskoj biblioteci u Milanu.","headingId":"svitci-sa-mrtvog-mora-i-mojsijevo-zavestanje","headingText":"Svitci sa Mrtvog mora i Mojsijevo zaveštanje"},{"text":"Kumranska verzija Kumranski tekst — Odeljci 1–2 „Sada će, po Tvojoj milosti, ući u zemlju koju je On odredio i obećao da će dati njihovim precima. Uspostavićeš im kraljevstvo. A zatim će delovati protiv Gospodnjeg saveza i oskrnaviti zakletvu koju je Gospod sklopio s njima. Žrtvovaće svoju decu stranim bogovima, postaviće idole u Šatoru i služiće im.“ Kumranski tekst — Odeljak 3 „Spaliće njihove naseobine zajedno sa svetim Hramom Gospodnjim i opljačkati sve svete predmete.“ Kumranski tekst — Odeljak 5 „A kada se približi vreme suda, biće poniženi pred stranim bogovima.“ Kumranski tekst — Odeljak 6 „Njihove zemlje napаšće odredi moćnog kralja sa Zapada, koji će ih mrzeti, odvesti u ropstvo, spaliti deo njihovog Hrama i neke od njih razapeti","headingId":"kumranska-verzija","headingText":"Kumranska verzija"},{"text":"oko njihove naseobine.“ Kumranski tekst — Odeljak 10 „Od moje smrti i počinka do njegovog dolaska proći će 250 razdoblja.“ Dve stotine pedeset sedmica godina, odnosno 1.750 godina. Navedeno prema knjizi Kumran Svitci sa Mrtvog mora, drugi deo.","headingId":"kumranska-verzija","headingText":"Kumranska verzija"}]},{"slug":"Osija-9-6-i-rec-mahmad","chunks":[{"text":"U nevokalizovanom hebrejskom tekstu Osije 9:6 javlja se četvoroslovni oblik mem het mem dalet, koji se može čitati i kao vlastito ime i kao pridev u značenju dragocenost. Septuaginta ga prenosi kao Mahmas, dakle kao vlastito ime, što Pulpit Commentary objašnjava time da su ga prevodioci uzeli za lično ime. Gezenijus u svojoj gramatici preporučuje čitanje mahmadi kaspam.","headingId":"","headingText":""},{"text":"Nevokalizovani hebrejski tekst Pre razmatranja prevoda, čitalac mora znati da je izvorni hebrejski tekst Starog zaveta napisan bez oznaka za samoglasnike. Ostao je nevokalizovan sve dok masoreti, između 6. i 10. veka nove ere, nisu dodali sistem vokalizacije kojim se određuju pravilan izgovor i značenje svake reči. To znači da se hebrejski tekst Starog zaveta, pre dodavanja vokalizacije, mogao čitati na više načina. Vokalizacija koju danas vidimo u Osiji 9:6 odražava masoretsko razumevanje i tumačenje teksta zabeleženo vekovima nakon pojave islama.","headingId":"nevokalizovani-hebrejski-tekst","headingText":"Nevokalizovani hebrejski tekst"},{"text":"Stih Osija 9:6 (nevokalizovani hebrejski tekst) Nevokalizovani hebrejski tekst Osije 9:6 glasi: כי הנה הלכו משד מצרים תקבצם מף תקברם מחמד לכספם קמוש יירשם חוח באהליהם Predmet ove analize jeste četvoroslovna reč מחמד. Ona sadrži sledeća slova: מ ( mem ) ח ( het ) מ ( mem ) ד ( dalet ) Pre dodavanja vokalizacije ova reč mogla se legitimno čitati na dva načina: Kao vlastito ime: מֻחַמַּד Muhamed (ﷺ) Kao pridev: מַחְמַד mahmad („dragocena stvar“) Oba načina čitanja istih četiriju hebrejskih slova: u gornjem redu nalazi se ime מֻחַמַּד Muhamed i njegov arapski ekvivalent; u donjem redu pridev מַחְמַד mahmad , „dragocen“ i njegov arapski ekvivalent. Masoreti su izabrali pridevsko čitanje. Mi tvrdimo da je ispravno čitanje vlastito","headingId":"stih-osija-96-nevokalizovani-hebrejski-tekst","headingText":"Stih Osija 9:6 (nevokalizovani hebrejski tekst)"},{"text":"ime Muhamed, na osnovu četiri grupe dokaza.","headingId":"stih-osija-96-nevokalizovani-hebrejski-tekst","headingText":"Stih Osija 9:6 (nevokalizovani hebrejski tekst)"},{"text":"Struktura Osije 9:6 rimovani niz kazni Stih se nalazi unutar niza kazni upućenih Jevrejima, uređenog prema strogom i doslednom dvodelnom obrascu rime: Obrazac: svaka celina = ime + sudbina Svaka rečenica u ovom nizu tačno prati tu strukturu: kratka kazna iskazana dvema rečima, od kojih je prva ime, a druga opisuje njegovu sudbinu. Sve se završavaju nastavkom ם ( mem ), koji označava „njih“ i odnosi se na Jevreje kao kolektiv. Nevokalizovani hebrejski tekst Osije 9:6 sa označenim obrascem kazne: svaka celina sastoji se od imena i njegove sudbine. Položaj reči מחמד označen je upitnikom kao jedino mesto čije je čitanje sporno.","headingId":"struktura-osije-96-rimovani-niz-kazni","headingText":"Struktura Osije 9:6 - rimovani niz kazni"},{"text":"Ako se čita kao ime Muhamed Kada se מחמד čita kao vlastito ime Muhamed ﷺ, obrazac ostaje dosledan u čitavom stihu: svaka celina sastoji se od imena i njegove sudbine. Prevod: „Egipat će ih sakupiti, Memfis će ih sahraniti, Muhamed će naslediti njihovo srebro, Kemoš će ih naslediti, a trnje će biti u njihovim šatorima.“","headingId":"ako-se-cita-kao-ime-muhamed","headingText":"Ako se čita kao ime - Muhamed"},{"text":"Ako se čita kao pridev mahmad („dragocena stvar“) Kada se מחמד čita kao pridev „dragocena stvar“ središnja celina dobija strukturu „pridev + sudbina“ umesto „ime + sudbina“, čime se bez opravdanja narušava dosledan obrazac čitavog niza. To je u skladu sa opštim obrascem Svetog pisma: kada god je Bog želeo da kazni Jevreje oduzimanjem njihovog bogatstva, uvek je slao neku osobu da to učini a ne trnov grm. Zaključak izveden iz obrasca: Ispravna vokalizacija mora ovu reč učiniti vlastitim imenom, a ne pridevom, jer dosledna i sistematična struktura teksta zahteva upravo ime.","headingId":"ako-se-cita-kao-pridev-mahmad-dragocena-stvar","headingText":"Ako se čita kao pridev _mahmad_ („dragocena stvar“)"},{"text":"Gesenijusova hebrejska gramatika potvrđuje čitanje kao vlastitog imena Gesenijusova hebrejska gramatika komentar na Osiju 9:6: „Ali verovatno treba čitati מחמדי כספם (Muhammadi kaspam).“ Gesenijus vodeći autoritet za gramatiku klasičnog hebrejskog jezika, izričito preporučuje čitanje מחמדי כספם (Muhammadi kaspam), u značenju: „Muhamedu njihovo srebro/bogatstvo.“ To nije marginalno mišljenje; ono se nalazi u standardnom drugom engleskom izdanju najmerodavnije postojeće gramatike hebrejskog jezika. Prema ovom izmenjenom čitanju, bogatstvo Jevreja postaće plen Muhameda ﷺ, sažeta izjava o kazni koja se savršeno uklapa u obrazac stiha.","headingId":"gesenijusova-hebrejska-gramatika-potvrdjuje-citanje-kao-vlastitog-imena","headingText":"Gesenijusova hebrejska gramatika potvrđuje čitanje kao vlastitog imena"},{"text":"Ispravljeno čitanje prema Gesenijusovom predlogu Ispravljeno čitanje prema Gesenijusovom predlogu glasi: „Muhamedu njihovo bogatstvo“ Pri čemu je מחמד ime, a לכספם njegova sudbina. Svaka celina sada prati obrazac „ime + sudbina“, dok se rima na ם dosledno zadržava u čitavom stihu. Ova izmena uklanja gramatičku poteškoću na koju ukazuju svi značajniji komentatori i vraća tekst potpuno doslednom obrascu.","headingId":"ispravljeno-citanje-prema-gesenijusovom-predlogu","headingText":"Ispravljeno čitanje prema Gesenijusovom predlogu"},{"text":"Problem prevoda u standardnim verzijama Sirijska Pešita jedan od najstarijih prevoda Biblije potvrđuje da je reč מחמד u Osiji 9:6 shvaćena u značenju želje ili požude ( šehva ): Prevod Svete Biblije Pešite Osija 9:6: „Jer oni odoše u propast; Egipat će ih sakupiti, Mefes će ih sahraniti; stranci će naslediti ono za čim žude u svom srebru, a trnje će biti u njihovim šatorima.“ Prevod, dakle, glasi: stranci nasleđuju ono za čim žude u svom srebru. To potvrđuje da je i Pešita razumela reč מחמד kao nešto željeno, odnosno kao predmet žudnje a ne kao biljku ili korov, i da to nasleđuje čovek, odnosno stranci. Arapska Van Dajkova Biblija prevodi stih ovako: „Otišli su u propast iz Egipta; Memfis","headingId":"problem-prevoda-u-standardnim-verzijama","headingText":"Problem prevoda u standardnim verzijama"},{"text":"će ih sakupiti, Memfis će ih sahraniti. Dragocenosti njihovog srebra skupina će ih naslediti; trnje će biti u njihovim šatorima.“ Osija 9:6 Ovaj prevod gramatički je usiljen: izraz „dragocenosti njihovog srebra“ stvara umetnutu rečenicu koja nema nikakvu vezu sa nizom kazni najavljenih u tekstu. Time se narušava unutrašnja logika stiha. Oksfordska Biblija sa napomenama to otvoreno priznaje: „Koprive će naslediti njihove dragocenosti od srebra.“ Fusnota: „Značenje hebrejskog teksta nije izvesno.“ Hebrejska Biblija , str. 1285. Nova oksfordska Biblija sa napomenama u sopstvenoj fusnoti priznaje da je značenje hebrejskog teksta neizvesno, upravo zato što pridevsko čitanje stvara nesuvislu rečenicu.","headingId":"problem-prevoda-u-standardnim-verzijama","headingText":"Problem prevoda u standardnim verzijama"},{"text":"Makintošev komentar naučno priznanje problema A. A. Makintoš, „Osija“ ( Međunarodni kritički komentar , Kembridž), str. 349: „Poteškoća nastaje zato što se nastavak za treće lice množine ‘naslediće ih’ prethodno preveden kao ‘biće njihovi naslednici’ izgleda ne slaže sa antecedentom u jednini ‘slava njihovog srebra’, koji se, u svakom slučaju, mora razumeti kao abstractum pro concretis . U novije vreme imenica je izmenjena u oblik množine ממדי i uz brisanje narednog slova ל protumačena kao ‘srebrni idoli’ ili ‘riznice’… U tom slučaju postavlja se pitanje: zašto se pominju srebrni idoli ili zašto bi riznice nasledio čičak, a ne pljačkaši?“ Čak i Makintoš koji se iz konfesionalnih razloga pridržava masoretske vokalizacije izričito priznaje sve gramatičke probleme koje smo naveli. Zatim odbacuje","headingId":"makintosev-komentar-naucno-priznanje-problema","headingText":"Makintošev komentar - naučno priznanje problema"},{"text":"vokalizaciju koja ovu reč čini vlastitim imenom, tvrdeći da ona mora predstavljati abstractum pro concretis naziv nečega konkretnog upotrebljen apstraktno odnosno da mora biti ime osobe, a ne osobina.","headingId":"makintosev-komentar-naucno-priznanje-problema","headingText":"Makintošev komentar - naučno priznanje problema"},{"text":"Septuaginta prevodioci LXX prepoznali su Muhameda kao vlastito ime Septuaginta (LXX), drevni grčki prevod hebrejske Biblije, prenosi Osiju 9:6 koristeći ime Μαχμάς ( Mahmas ): Septuaginta LXX — Osija 9:6 na grčkom: „…καὶ θάψει αὐτοὺς Μαχμάς“ — „…i Mahmas će ih sahraniti.“ Arapski prevod Septuaginte ( الأسفار النبوية ) sadrži fusnote u kojima se navodi da u masoretskom tekstu stoji محمد Muhamed i da su prevodioci LXX, smatrajući da je reč o imenu grada, to preneli kao „Mihmas“. Brentonov engleski prevod Septuaginte: „…i Mahmas će ih sahraniti; što se tiče njihovog srebra, propast će ga naslediti; trnje će biti u njihovim šatorima.“ Prevodioci LXX očigledno su razumeli מחמד kao vlastito ime, a ne kao pridev, jer: Fonetski su ga preneli","headingId":"septuaginta-prevodioci-lxx-prepoznali-su-muhameda-kao-vlastito-ime","headingText":"Septuaginta - prevodioci LXX prepoznali su Muhameda kao vlastito ime"},{"text":"na grčki kao Μαχμάς Mahmas . Tretirali su ga kao gramatički subjekat koji vrši radnju: „sahraniće ih“. Njihov prevod čuva obrazac „ime + sudbina“: „Mahmas će ih sahraniti.“ To potvrđuje i The Complete Pulpit Commentary , delo hrišćanskih stručnjaka: „(3) Zbunjeni rečju maehmad , pogrešno su je smatrali vlastitim imenom: ‘Stoga, evo, oni odlaze iz egipatske nevolje; Memfis će ih primiti, a Mahmas (Μα᾽χμας) će ih sahraniti.’“ The Complete Pulpit Commentary\\ \\ (6. tom, Od Osije do Malahije ), Džozef S. Eksel i Henri D. M. Spens Komentar izričito navodi da su prevodioci LXX bili zbunjeni rečju maehmad Muhamed i da su je pogrešno smatrali vlastitim imenom, iako ona to zapravo jeste. Zatim su je fonetski preneli kao „Mahmas“.","headingId":"septuaginta-prevodioci-lxx-prepoznali-su-muhameda-kao-vlastito-ime","headingText":"Septuaginta - prevodioci LXX prepoznali su Muhameda kao vlastito ime"},{"text":"Zašto „Mahmas“ ne može biti ime grada Ova reč izgovorena kao Mahmas ili Mihmas podseća na ime grada Mihmasa (מִכְמָשׁ) u Svetoj zemlji. Međutim, značenje koje masoretski tekst daje ovom odlomku nikako se ne može primeniti na jedno palestinsko selo. Nijedna razumna osoba ne može tvrditi da bi neko nepoznato selo u Palestini „nasledilo srebro“ Jevreja u kontekstu Osijinog proročanstva. Reč מחמד u ovom odlomku ne može biti ime mesta. Ona može biti samo ime osobe a osoba u čijem se imenu dosledno pojavljuje koren חמד jeste Poslanik Muhamed ﷺ.","headingId":"zasto-mahmas-ne-moze-biti-ime-grada","headingText":"Zašto „Mahmas“ ne može biti ime grada"},{"text":"Uporedni navod isti koren u Isaiji 42:1 Isto vizuelno poređenje između אתמך ( atamah „podržavam“) i אחמד ( Ahmed ) iz Isaije 42:1 potvrđuje da koren חמד u više biblijskih tekstova dosledno odgovara Poslanikovom imenu.","headingId":"uporedni-navod-isti-koren-u-isaiji-421","headingText":"Uporedni navod isti koren u Isaiji 42:1"},{"text":"Ispunjenje proročanstva Banu Nadir Obnovljeno čitanje Osije 9:6 „Muhamedu njihovo bogatstvo“ (מחמד לכספם / Muhammad li kaspam ) ispunilo se sa zapanjujućom preciznošću tokom pohoda protiv Banu Nadira. Poslanik ﷺ opkolio je jevrejsko pleme Banu Nadir nakon što su prekršili savez sklopljen s njim, pa su pobegli iz Medine, ostavljajući svoju imovinu i bogatstvo. Potpuno obnovljeni tekst Osije 9:6, sa doslednim obrascem, glasi: „Egipat će ih sakupiti, Memfis će ih sahraniti, Muhamed će naslediti njihovo bogatstvo, Kemoš će ih naslediti, a trnje će biti u njihovim šatorima.“ Uzvišeni Alah ﷻ ovo je opisao u Kuranu: Al Hashr 59:6 A vi niste gonili konje ni kamile zbog onoga što je Allah od njih, kao plen, darovao Svome Poslaniku, nego, Allah prepušta","headingId":"ispunjenje-prorocanstva-banu-nadir","headingText":"Ispunjenje proročanstva - Banu Nadir"},{"text":"vlast Svojim poslanicima nad onima nad kojima On hoće; Allah nad svime ima moć. To potvrđuje i predanje Omera ibn el Hattaba neka je Allah zadovoljan njime: „Imovina Banu Nadira pripadala je onome što je Alah vratio Svome Poslaniku ﷺ, a da muslimani radi toga nisu pokretali ni konje ni kamile. Ona je pripadala isključivo Alahovom Poslaniku ﷺ. Iz nje je podmirivao godišnje potrebe svoje porodice, a ostatak ulagao u oružje i opremu na Alahovom putu.“ Sahih el Buhari, 4885","headingId":"ispunjenje-prorocanstva-banu-nadir","headingText":"Ispunjenje proročanstva - Banu Nadir"},{"text":"Zaključak ukratko Svi navedeni dokazi upućuju na isto čitanje: | Dokaz | Šta pokazuje | | | | | Rimovani obrazac stiha | Svaka celina prati obrazac „ime + sudbina“; jedino čitanje kao imena čuva taj obrazac | | Gesenijusova hebrejska gramatika | Izričito preporučuje čitanje Muhammadi kaspam u Osiji 9:6 | | Oksfordska Biblija sa napomenama | Za pridevsko čitanje priznaje: „Značenje hebrejskog teksta nije izvesno“ | | Makintošev ICC komentar | Priznaje problem nastavka za množinu, što ukazuje da reč mora označavati konkretno ime | | Septuaginta (LXX) | Prepoznala je מחמד kao vlastito ime i fonetski ga prenela | | Pulpit Commentary | Priznaje da su prevodioci LXX reč „pogrešno smatrali vlastitim imenom“ što ona zapravo jeste","headingId":"zakljucak-ukratko","headingText":"Zaključak - ukratko"},{"text":"| | Istorijsko ispunjenje | Bogatstvo Banu Nadira pripalo je Muhamedu ﷺ bez borbe | Na kraju ove rasprave ne možemo a da se ne prisetimo reči samog Poslanika ﷺ: „Tako mi Onoga u čijoj je ruci Muhamedova duša, niko iz ovog naroda bio Jevrejin ili hrišćanin neće čuti za mene, a zatim umreti ne poverovavši u ono sa čime sam poslat, a da neće biti među stanovnicima Vatre.“ Sahih Muslim, 153","headingId":"zakljucak-ukratko","headingText":"Zaključak - ukratko"}]},{"slug":"Parakletos-u-Jovanu-16","chunks":[{"text":"Osam međusobno usklađenih linija dokaza jesu: Lingvistička: grčka etimologija podržava vezu između imena Ahmad i izraza Perikletos . Rukopisna: postoje rane tekstualne varijante i izmene koje priznaju i sami hrišćanski izvori. Teološka: rani hrišćani očekivali su ljudskog proročkog Paraklita, što pokazuju Montan, Mani i Tertulijan. Kontekstualna: jevanđeljski odlomci opisuju ljudskog proroka sa određenim ulogama, a ne samo duhovnu silu. Akademska: hrišćanski i sekularni naučnici, uključujući Rejmonda Brauna, Karen Armstrong priznaju poteškoće pri prevođenju. Ispunjenje: Kur an i Poslanik ﷺ potpuno i jedinstveno ispunjavaju jovanovske kriterijume. Arapsko prenošenje: starija arapska jevanđeljska svedočanstva dosledno su čuvala tehnički izraz الفارقليط / فارقليط, umesto da ga svedu na jedan običan prevodni ekvivalent.","headingId":"","headingText":""},{"text":"Isusovo predskazanje Isus je predskazao da će nakon njega doći proročka ličnost koja će govoriti reči koje joj Bog bude dao, uveriti ljude u njihove grehe, uputiti ih u više stvari nego što je Isus učinio, podsetiti ih na istinska Isusova učenja i izneti istinita proročanstva o budućnosti. Jasno je da Muhamed ﷺ ispunjava svaki kriterijum koji je Isus naveo, te da je on Paraklet čiji je dolazak Isus najavio kao radosnu vest. Isus predskazuje dolazak proročke ličnosti u ljudskom obličju koja će nakon njega: 1. Doći tek nakon što Isus ode Bogu 2. Uveriti svet u pogledu greha i pravednosti 3. Govoriti samo ono što čuje 4. Podsećati ljude na Isusova učenja 5. Uputiti ljude u svu istinu 6.","headingId":"isusovo-predskazanje","headingText":"Isusovo predskazanje"},{"text":"Proricati ono što će doći Na koga vas sve ovo podseća…?","headingId":"isusovo-predskazanje","headingText":"Isusovo predskazanje"},{"text":"Uveriti svet u pogledu greha i pravednosti Jovan 16:8 A kad on dođe, pokazaće svetu šta je greh, šta je pravda i šta je sud. Al A raf 7:157 „onima koji će da slede Poslanika, Verovesnika, koji neće da zna ni da čita ni da piše, kojeg oni kod sebe, u Tori i Jevanđelju, nalaze zapisanog, koji će od njih da traži da čine dobra dela, a od odvratnih da odvraća, koji će lepa jela da im dozvoli, a ružna zabrani, koji će da ih tereta i teškoća koje su oni imali oslobodi. A oni koji u njega budu verovali, koji ga budu podržavali i pomagali i svetlo po njemu poslato sledili oni će sigurno uspeti.“","headingId":"uveriti-svet-u-pogledu-greha-i-pravednosti","headingText":"Uveriti svet u pogledu greha i pravednosti"},{"text":"Govoriti samo ono što čuje Jovan 16:13 A kada dođe on, Duh istine, uputiće vas u svu istinu, jer neće govoriti po svome, nego će govoriti ono što čuje, i najavljivaće vam buduće događaje. Al Najm 53:3 4 On ne govori po svojim prohtevima. To je samo Objava koja mu se obznanjuje.","headingId":"govoriti-samo-ono-sto-cuje","headingText":"Govoriti samo ono što čuje"},{"text":"Podsećati ljude na Isusova učenja Jovan 14:25 26 Ovo vam kažem dok sam još sa vama. A Pomagač Utešitelj, Duh Sveti, koga Otac šalje u moje ime, poučiće vas svemu i podsetiće vas na sve što sam vam rekao. Ali Imran 3:50 51 Potvrđujući tako istinitost Tore, objavljene pre mene, i dopuštajući nešto što vam je bilo zabranjeno, ja vam donosim dokaz od vašega Gospodara. Pa, bojte se Allaha, a meni budite pokorni! Allah je zaista i moj i vaš Gospodar i samo Njega obožavajte. To je Pravi put!","headingId":"podsecati-ljude-na-isusova-ucenja","headingText":"**Podsećati** ljude na Isusova učenja"},{"text":"Uputiti ljude u svu istinu Jovan 16:12 13 Imam još mnogo šta da vam kažem, ali sada bi to bilo previše za vas. A kada dođe on, Duh istine, uputiće vas u svu istinu, jer neće govoriti po svome, nego će govoriti ono što čuje, i najavljivaće vam buduće događaje. An Nahl 16:89 A na Dan kada iz svakog naroda dovedemo po jednog svedoka koji će da svedoči protiv svog naroda, a tebe dovedemo kao svedoka protiv ovih! Mi tebi objavljujemo Knjigu kao objašnjenje za sve i kao uputu i milost i radosnu vest za one koji jedino u Njega veruju.","headingId":"uputiti-ljude-u-svu-istinu","headingText":"Uputiti ljude u svu istinu"},{"text":"Proricati ono što će doći Jovan 16:12 13 Imam još mnogo šta da vam kažem, ali sada bi to bilo previše za vas. A kada dođe on, Duh istine, uputiće vas u svu istinu, jer neće govoriti po svome, nego će govoriti ono što čuje, i najavljivaće vam buduće događaje. Ar Rum 30:3 4 u najnižoj zemlji, ali oni će, posle poraza svog, sigurno pobediti, za nekoliko godina – i pre i posle, Allahova je odluka – i tad će se vernici radovati, Poznati istoričar potvrđuje proročanstvo:","headingId":"proricati-ono-sto-ce-doci","headingText":"Proricati ono što će doći"},{"text":"Odeljak 1 Struktura govora: Jovan 14 odvojen je od Jovana 15 16 Ključna, ali često zanemarena osnova argumenta o Parakletu jeste da Jovan 14 predstavlja tekstualno i strukturno zaseban govor u odnosu na poglavlja 15 i 16. Ako u Jovanu 14 prihvatimo čitanje u sadašnjem vremenu, ono bi neposredno protivrečilo Jovanu 15 i 16. To podržava stav da su u pitanju različite tekstualne celine koje se ne mogu uskladiti u jedinstveno obećanje o istoj osobi. Jovan 16:7 13 Ja vam govorim istinu: za vas je bolje da odem, jer ako ja ne odem, Pomagač Utešitelj neće doći k vama. Ali ako odem, poslaću ga k vama. A kad on dođe, pokazaće svetu šta je greh, šta je pravda i šta","headingId":"odeljak-1-struktura-govora-jovan-14-odvojen-je-od-jovana-15-16","headingText":"Odeljak 1 - Struktura govora: Jovan 14 odvojen je od Jovana 15-16"},{"text":"je sud. Greh je to što ne veruje u mene. Pravda je to što odlazim k Ocu i što me nećete više videti. Sud je to što je vladar ovoga sveta osuđen. Imam još mnogo šta da vam kažem, ali sada bi to bilo previše za vas. A kada dođe on, Duh istine, uputiće vas u svu istinu, jer neće govoriti po svome, nego će govoriti ono što čuje, i najavljivaće vam buduće događaje. Jovan 14:25 26 Ovo vam kažem dok sam još sa vama. A Pomagač Utešitelj, Duh Sveti, koga Otac šalje u moje ime, poučiće vas svemu i podsetiće vas na sve što sam vam rekao. Džejms M., stručnjak za tekstualnu kritiku, tvrdi da Jovan 14 predstavlja zaseban","headingId":"odeljak-1-struktura-govora-jovan-14-odvojen-je-od-jovana-15-16","headingText":"Odeljak 1 - Struktura govora: Jovan 14 odvojen je od Jovana 15-16"},{"text":"govor u odnosu na Jovana 15 i 16. Rejmond Braun slaže se sa tim tumačenjem. Ovo nije tvrdnja muslimanskog porekla, već priznat stav u zapadnoj nauci o Novom zavetu, naveden u fusnoti NET Biblije uz Jovana 14:17. Fusnota NET Biblije uz Jovana 14:17 izričito razmatra napetost između čitanja u sadašnjem i budućem vremenu u različitim jovanovskim govorima, priznajući njihov strukturni diskontinuitet.","headingId":"odeljak-1-struktura-govora-jovan-14-odvojen-je-od-jovana-15-16","headingText":"Odeljak 1 - Struktura govora: Jovan 14 odvojen je od Jovana 15-16"},{"text":"Odeljak 2 Ko je Parakletos / Perikletos ?","headingId":"odeljak-2-ko-je-parakletos-perikletos-","headingText":"Odeljak 2 - Ko je _Parakletos / Perikletos_ ?"},{"text":"Paraklet je Prorok Uprkos onome što hrišćani mogu tvrditi, raspolažemo obiljem svedočanstava različitih grupa, uključujući i poznate crkvene oce, koji su verovali da je Paraklet proročka ličnost u ljudskom obličju, a ne samo duhovno biće!","headingId":"paraklet-je-prorok","headingText":"Paraklet je Prorok"},{"text":"Paraklet je kao Prorok Mojsije 5. Mojsijeva 18:18 22 Zato ću podići proroka između tvoje braće kao što si ti; ja ću staviti svoje reči u njegova usta, pa će govoriti sve što mu zapovedim. Ako neko ne posluša ono što prorok bude rekao u moje ime, toga ću ja smatrati odgovornim. A ako se neki prorok drzne da u moje ime kaže nešto što nisam zapovedio, ili da govori u ime drugih bogova, taj prorok neka se pogubi.’ Ti se možda pitaš u sebi: ’Kako da prepoznamo reč koju Gospod nije saopštio?’ Ako prorok objavi nešto u ime Gospodnje, a to se ne ostvari, niti se ispuni, to je reč koju Gospod nije saopštio. Prorok je to govorio iz","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"sopstvene drskosti; ne boj ga se. Jovan 16:12 13 Imam još mnogo šta da vam kažem, ali sada bi to bilo previše za vas. A kada dođe on, Duh istine, uputiće vas u svu istinu, jer neće govoriti po svome, nego će govoriti ono što čuje, i najavljivaće vam buduće događaje. Znamo da je Prorok poput Mojsija verovatno bio poistovećen i egzegetski spojen sa anđelom iz 2. Mojsijeve 23 odnosno Božjim glasnikom koji će Izrailce izvesti iz fizičkog izgnanstva i uvesti ih u Obećanu zemlju. Međutim, gotovo je nesporno da Malahija 3:1 preuzima tekst iz 2. Mojsijeve 23, premda neki smatraju da je reč o Isaiji 40:3 i predstavlja ga kao buduće proročanstvo. Paraklet ispunjava upravo one uloge koje su","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"u Ponovljenom zakonu 18 pripisane Proroku poput Mojsija. Sada pogledajmo sledeća dva odlomka, koja će nam pomoći da razumemo vreme u kojem se možda očekivao dolazak tog proroka: Knjiga proroka Malahije 3:1 „Evo, šaljem poslanika svoga koji će mi put pripraviti. Gospod, onaj koga tražite, će iznenada doći u svoj hram, i poslanik saveza kome se radujete. Evo, on dolazi“ – kaže Gospod nad vojskama. 2. Mojsijeva 23:20 Evo, ja šaljem Anđela pred tobom da te čuva na putu, dok te ne dovede do mesta koje sam pripremio. Napomena naučnika: „Moguće je da je čitalac Malahije, imajući pred sobom čitavo Petoknjižje, egzegetskim putem spojio glasnika iz Izlaska i proroka iz Ponovljenog zakona u jednu osobu. Obojica su obećana, obojica dolaze","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"i obojica su ličnosti koje Izrailj mora poslušati.“ Dokaz koji potkrepljuje prethodnu tvrdnju naučnika: „Širi kontekst Ponovljenog zakona obrađuje nosioce autoriteta: najpre starešine i sudije, zatim kraljeve i sveštenike i, na kraju, proroke. Zahtev za posebnošću u Ponovljenom zakonu 18 dodatno učvršćuje njegov program pravilnog vršenja verskog autoriteta od strane njegovih zakonitih nosilaca. Ova veza uspostavlja se i književnim putem kada naredni odlomak nalaže Izrailju da sluša ovlašćenog proroka, koristeći isti glagol tišma'un (Ponovljeni zakon 18:15) koji je u Ponovljenom zakonu 18:14 upotrebljen za opisivanje privrženosti starosedelačkih naroda vračarima i gatarima (jišma'u). Perikopa iz Ponovljenog zakona 18 završava se slično kao Ponovljeni zakon 12 upozorenjem da se Božje odredbe moraju precizno slediti što odražava zajedničku nameru ovih poglavlja da centralizuju","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"verski autoritet. Ovim odlomcima iz Petoknjižja Izlasku 23, Ponovljenom zakonu 12, Ponovljenom zakonu 18 i, konačno, Levitskoj knjizi 18 zajednički je zahtev da se Izrailj razlikuje od drugih, pokrenut njegovim dolaskom u zemlju i susretom sa starosedelačkim stanovništvom. Najupadljivija razlika među ovim odlomcima odnosi se na vrstu običaja koje svaki od njih problematizuje: Izlazak 23 obožavanje drugih bogova; Ponovljeni zakon 12 načini i mesta bogosluženja; Ponovljeni zakon 18 posrednici bogosluženja; Levitska knjiga 18 zavisno od tumačenja, ukupnost starosedelačkih običaja ili posebno njihovi polni običaji Pošto je Malahija živeo nakon vavilonskog ropstva, ovaj Glasnik saveza a samim tim i Prorok poput Mojsija, odnosno Paraklet morao je doći nakon drugog izgnanstva , za koje znamo da se dogodilo 132. godine nove ere,","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"tokom Bar Kohbinog ustanka.","headingId":"paraklet-je-kao-prorok-mojsije","headingText":"Paraklet je kao Prorok Mojsije"},{"text":"Rana verovanja hrišćana Više pojedinaca tokom prva tri veka hrišćanstva Montan, Mani i drugi tvrdilo je da su upravo oni Paraklit. Svi su ga razumeli kao buduću ljudsku proročku ličnost, a ne kao duhovnu silu koja je već prisutna u Crkvi. Svi su odbačeni kao lažni pretendenti, ali njihova pojava u različitim vekovima i geografskim oblastima potvrđuje trajno ranohrišćansko shvatanje da će Paraklit biti ljudski prorok koji tek treba da dođe. Jedini pretendent u čitavoj istoriji koji ispunjava sve jovanovske kriterijume poučavanje, podsećanje, svedočenje, osvedočavanje sveta i proslavljanje Isusa jeste poslanik Muhammed ﷺ.","headingId":"rana-verovanja-hriscana","headingText":"Rana verovanja hrišćana"},{"text":"Crkveni otac Origen (185. n. e.) Crkveni otac Origen (185. n. e.) njegovi učenici su verovali da je 'Pavle' iz Tarza bio Paraklet:","headingId":"crkveni-otac-origen-185-n-e","headingText":"Crkveni otac Origen (185. n. e.)"},{"text":"Tertulijan (160. n. e.) Tertulijan (160. n. e.) je verovao da je 'Montan' Paraklet: Tertulijan je verovao da su proroci postojali i nakon Isusove smrti. Prema profesoru Judžinu Boringu, Paraklit predstavlja jedinstvo anđela koji donosi objavu i proroka ličnu, otelovljenu proročku figuru, a ne bezličnu božansku silu.","headingId":"tertulijan-160-n-e","headingText":"Tertulijan (160. n. e.)"},{"text":"Mani (216–274/277. n. e.) Mani (216–274/277. n. e.) je sebe smatrao Parakletom: „Mani se predstavljao kao Paraklit kojeg je Hrist obećao, a isto su činili i mnogi drugi. Napisao je brojne knjige na persijskom i sirijskom jeziku.“ Enciklopedija crkvenih otaca (1. tom, str. 256)","headingId":"mani-216274277-n-e","headingText":"Mani (216–274/277. n. e.)"},{"text":"Crkveni otac Avgustin (354. n. e.) Crkveni otac Avgustin (354. n. e.) je verovao najmanje 9 godina da je Mani Paraklet:","headingId":"crkveni-otac-avgustin-354-n-e","headingText":"Crkveni otac Avgustin (354. n. e.)"},{"text":"Poveznica prijašnih proroka Na osnovu naučnika koje sam prethodno naveo i dokaza kojima sam potkrepio njihove tvrdnje, znamo da je Prorok poput Mojsija verovatno bio poistovećen i egzegetski spojen sa anđelom iz Izlaska 23 — odnosno Božjim glasnikom koji će Izrailjce izvesti iz fizičkog izgnanstva i uvesti ih u Obećanu zemlju. Međutim, gotovo je nesporno da Malahija 3:1 preuzima tekst iz Izlaska 23 — premda neki smatraju da je reč o Isaiji 40:3 — i predstavlja ga kao buduće proročanstvo. Pošto je Malahija živeo nakon vavilonskog ropstva, ovaj Glasnik saveza — a samim tim i Prorok poput Mojsija, odnosno Paraklet — morao je doći nakon drugog izgnanstva , za koje znamo da se dogodilo 132. godine nove ere, tokom Bar","headingId":"poveznica-prijasnih-proroka","headingText":"Poveznica prijašnih proroka"},{"text":"Kohbinog ustanka. Mojsija i Isusa Navina 5. Mojsijeva 31:1 8 Mojsije izađe i reče ove reči celom Izrailju. Rekao im je: „Danas mi je stotinu dvadeset godina, i ne mogu više izlaziti i vraćati se. Gospod mi je rekao: ’Nećeš preći preko Jordana.’ Sam Gospod, Bog tvoj, preći će pred tobom; on će da istrebi ove narode pred tobom, pa ćeš ih izgnati. Isus će ići pred tobom, kao što je Gospod rekao. Gospod će postupiti sa njima onako kako je postupio sa Sihonom i Ogom, carevima amorejskim, i njihovom zemljom, kada ih je istrebio. Gospod će vam ih predati, a ti ćeš postupiti sa njima prema svim zapovedima koje sam vam dao. Zato budite jaki i odvažni! Ne bojte","headingId":"poveznica-prijasnih-proroka","headingText":"Poveznica prijašnih proroka"},{"text":"se, niti strahujte od njih! Jer, Gospod, Bog tvoj, ide sa tobom; on neće odstupiti od tebe niti će te ostaviti.“ Mojsije pozva Isusa i reče mu pred celim Izrailjem: „Budi jak i odvažan, jer ćeš ti ući sa ovim narodom u zemlju za koju se Gospod zakleo njihovim ocima da će im je dati. Ti ćeš im je predati u nasledstvo. Sam Gospod ide pred tobom. On će biti sa tobom; on neće odstupiti od tebe, niti će te ostaviti. Ne boj se i ne strahuj!“ Ilija i Jelisej 2. Kjiga o carevima 2:9 15 Kad su prošli, Ilija reče Jeliseju: „Traži nešto od mene pre nego što budem uzet.“ On mu reče: „Neka dvostruka mera tvoga duha dođe","headingId":"poveznica-prijasnih-proroka","headingText":"Poveznica prijašnih proroka"},{"text":"na mene.“ Ilija mu reče: „Tražio si tešku stvar; ipak, ako me vidiš kad budem bio uzet od tebe, neka ti bude tako; ako ne budeš video, onda se to neće dogoditi.“ Dok su oni tako hodali i razgovarali, pojave se ognjene kočije i ognjeni konji i dođu između njih, pa u vihoru odnesu Iliju na nebo. Kad je to Jelisej video, povikao je: „Oče moj, oče moj, kočije i konjanici Izrailjevi!“ I nije ga više video. Zatim je uzeo njegov ogrtač i poderao ga na dva dela. Onda je podigao Ilijin ogrtač, koji je spao s njega, pa se vratio i stao na obalu Jordana. Tada je uzeo Ilijin ogrtač, koji je spao s njega, i udario po vodi.","headingId":"poveznica-prijasnih-proroka","headingText":"Poveznica prijašnih proroka"},{"text":"Rekao je: „Gde je Gospod, Bog Ilijin?“ Udario je po vodi i voda se razdelila na jednu i na drugu stranu. Jelisej prođe. Proročki sinovi iz Jerihona koji su ga posmatrali izdaleka, rekoše: „Ilijin duh je počinuo na Jeliseju!“ Kad su došli da se sretnu s njim, poklonili su mu se licem do zemlje.","headingId":"poveznica-prijasnih-proroka","headingText":"Poveznica prijašnih proroka"},{"text":"Odeljak 3 Jezička veza: Parakletos / Perikletos Ahmed Ovaj odeljak zahteva veliku pažnju i razumevanje jer je verovatno najvažniji i najzanimljiviji deo. U njemu ću etimološki povezati grčku reč „Parakletos“ sa arapskim imenom „Ahmed“, pomenutim u Kur anu.","headingId":"odeljak-3-jezicka-veza-parakletos-perikletos-ahmed","headingText":"Odeljak 3 - Jezička veza: _Parakletos / Perikletos_ - Ahmed"},{"text":"Problem prevoda Postoji problem prilikom prevođenja grčke reči παράκλητος (paraklētos). Uobičajeni prevodi glase: „Zastupnik“, „Utešitelj“ i „Pomoćnik“. Oni izdvajaju samo deo uloga koje četvrto Evanđelje pripisuje ovoj ličnosti. Kao svedočanstva o tom problemu možemo videti kod hrišćanskih autora: Postoji očigledan raskorak između naziva ‘Paraklet’ i uloga koje mu Jovan pripisuje. Poteškoća postaje vidljiva pri pokušaju prevođenja tog izraza… Međutim, nijedan [od prevoda] nije naišao na široko prihvatanje. Nijedan ne uspeva da precizno i sveobuhvatno prenese način na koji Jovan koristi ovaj naziv, kojem pripisuje uloge učitelja, onoga koji podseća, svedoka i onoga koji osvedočava. The work of the Holy Spirit in light of John 14 16, str. 20 21 „Etimologija reči parakletos i njeno značenje u Jovanovim spisima pokazali su","headingId":"problem-prevoda","headingText":"Problem prevoda"},{"text":"se kao zbunjujući problem.“ The Anointed Community: The Holy Spirit in the Johannine Tradition, str. 6 Naučnici otvoreno priznaju da je najveći problem u vezi sa ovim izrazom njegovo značenje, naročito aktivne funkcije koje mu se pripisuju uprkos njegovom pasivnom obliku. Drugim rečima, postoji očigledan raskorak između titule „Paraklet“ i uloga koje joj Jovan pripisuje. Teškoća postaje vidljiva već pri pokušaju prevođenja ovog izraza. Među predloženim prevodima nalaze se: Utešitelj, Zastupnik, Posrednik, Onaj koji uverava, Okrepitelj, Pomoćnik i Prijatelj. Međutim, nijedan nije naišao na opšte prihvatanje. Svi oni ne uspevaju da precizno i sveobuhvatno obuhvate Jovanovu upotrebu ove titule, kojoj on pripisuje uloge učitelja, onoga koji podseća, svedoka i onoga koji dokazuje krivicu. Delo Svetog Duha u svetlosti Jovana 14","headingId":"problem-prevoda","headingText":"Problem prevoda"},{"text":"16 Glen Nilsen Šta nam ime dato ovoj spasiteljskoj ličnosti govori o njoj? Ni najpažljivija istraživanja još nisu pronašla hebrejsku ili aramejsku titulu čiji bi paraklētos bio jasan prevod. Zato je moguće da Jovanov paraklētos predstavlja grčku retroverziju pozajmljene reči, a ne prevod istinske hebrejske titule. Ukratko, nijedan pojedinačni prevod reči paraklētos ne obuhvata svu složenost pravnih i drugih funkcija koje ova ličnost ima. Paraklet je: svedok koji brani Isusa i njegov zastupnik tokom suđenja pred neprijateljima; utešitelj učenika, jer među njima zauzima Isusovo mesto; učitelj i vodič učenika, a time i njihov pomoćnik. Prevodeći ovu grčku reč na latinski za Vulgatu, Jeronim je mogao birati između izraza iz starolatinskih prevoda, poput advocatus i consolator , ili običaja da se","headingId":"problem-prevoda","headingText":"Problem prevoda"},{"text":"izraz jednostavno prenese kao paracletus . U Jevanđelju je izabrao poslednje rešenje, dok se advocatus pojavljuje u Prvoj Jovanovoj poslanici. Isti pristup sledile su sirijska i koptska tradicija. Verovatno bi bilo mudro da se i u savremenim prevodima zadrži izraz „Paraklet“ — gotovo doslovna transliteracija koja čuva jedinstvenost titule i ne ističe jednu njenu funkciju na štetu ostalih. Evandjelje po Jovanu Raymond F. Brown Da li je Isus mogao najaviti Duha ovim izrazima? Ili, još temeljnije, da li je Paraklet prvobitno bio nezavisna spasiteljska ličnost koja je kasnije poistovećena sa Svetim Duhom, kao što tvrde Bultmann i Betz? Najzad, etimologija reči παράκλητος i njeno jovanovsko značenje pokazali su se kao izuzetno zamršen problem. Da li objašnjenje treba tražiti u protognostičkim","headingId":"problem-prevoda","headingText":"Problem prevoda"},{"text":"izvorima (Bauer, Bultmann) ili u jevrejskim prethodnicama (Mowinckel, Behm)? Treba li istraživati vezu Parakleta sa Duhom istine i u njoj prepoznavati tragove kumranskog uticaja (Betz, Johnston), ili se dovoljno istorijske pozadine može pronaći u ortodoksnom judaizmu (Bornkamm, Müller)? Sveti Duh u Jovanovoj tradiciji Gary M. Burge","headingId":"problem-prevoda","headingText":"Problem prevoda"},{"text":"Etimološka analiza reči „para“ Predlog παρά ( para ) je definisan na sledeći način: παρά ( para ) predlog sa značenjem „iznad, preko ili ekvivalentno sa više od\" Theayers Greek English lexicon of the New Testament παρά ( para ) predlog sa značenjem „mimo, preko, iznad i povrh, pored toga, više od, u višku preko\" Liddell and Scott Greek English Lexicon Dakle, para može da se prevede u kvantitativnom smislu kao „više od\" ili „u višku preko\". παρά ( para ) zadržava ta kvantitativna značenja čak i kada je deo složenice, kao u slučaju reči parakletos, što potvrđuje Strong: „u složenicama zadržava istu raznolikost primene\". Strong's exhaustive concordance Profesorka lingvistike Despina Čila Marko takođe potvrđuje da je παρά ( para","headingId":"etimoloska-analiza-reci-para","headingText":"Etimološka analiza reči „para“"},{"text":") nosilo ovo kvantitativno značenje viška barem još od helenističkih vremena, navodeći primer složenice paragerao koja znači „stariti prekomerno\". Grammaticalisation and Lexicalisation: Reconsidering a controversial relation\", str. 179 192 Grčka verzija Starog zaveta poznata kao Septuaginta pruža Biblijski primer upotrebe παρά ( para ) u složenici u kvantitativnom smislu: θερμαίνω ( thermainō ) glagol sa značenjem „zagrevati“ ili „utopliti“ Ovde je reč prevedena kao „bes\" grčka složenica Parathermainō / παραθερμανται, koja u Ralfovom izdanju Septuaginte definisano je kao „preterano zagrevati“.","headingId":"etimoloska-analiza-reci-para","headingText":"Etimološka analiza reči „para“"},{"text":"Etimološka analiza reči „kletos“ Glagol/pridev κλέος ( kletos ) ima dve moguće etimologije od kojih može da bude izveden: zvati slaviti Kako potvrđuje antički grčki gramatičar Hesihije iz Aleksandrije: κλέος ( kletos ) „onaj koji je pozvan imenom\", „sveslavni\". Hesychii Alexandrini Lexicon, Tom II Profesor Gregory Nagy, specijalista za arhaičnu grčku poeziju, napisao je da se glagolski oblici druge etimologije obično prevode kao „hvaliti\" i „biti hvaljen\". Comparative Studies in Greek and Indic Meter κλείω pesnički oblik glagola κλέω: pripovedati o nekome, učiniti poznatim, proslavljati ili veličati. Grčko Engleski rečnik Henry George Liddell i Robert Scott κλέος ( kleos ) slava, glasovitost, hvala; glas, izveštaj, ugled. Strongov rečnik Jevrejski filozof Filon, Isusov savremenik, takođe je koristio srodni imenički oblik kleos","headingId":"etimoloska-analiza-reci-kletos","headingText":"Etimološka analiza reči „kletos“"},{"text":"u kontekstu slave: „Ali moj skiptar biće knjiga prepisa zakona; to će biti moja hvala i moja neosporna slava. The Special Laws, IV, 164 Endoxos deli koren hmd sa arapskim imenima Muhamed i Ahmed. Ovo nije fonetski trik, već dokumentovana značenjska podudarnost između grčke i semitske jezičke porodice. Lanac značenjske podudarnosti potvrđuju grčki leksički izvori: Kletos = doxa = endoxos („hvaljen/slavan“). https://portail.biblissima.fr/en/ark:/43093/mdatab390a1131cf5b277d39966642d940e2a214b4cd5 Ovde možemo videti da je endoxos preveden kao mahmud u prevodu Hubejša ibn Ishaka. https://glossga.bbaw.de/words/133006 Upravo zbog ove uzajamne zamene oblika kletos i kleitos , leksikon Kirila Aleksandrijskog iz 5. veka definiše kletos izrazima doxa i endoxos , koji odgovaraju arapskim rečima hamd i mahmud","headingId":"etimoloska-analiza-reci-kletos","headingText":"Etimološka analiza reči „kletos“"},{"text":"Pravo značenje reči „Paraklet“ Nakon razmatranja drevnih primera, izvedenica i etimoloških veza unutar složenice parakletos, možemo zaključiti da se ova reč može protumačiti kao titula ili ime sa značenjem „izuzetno hvaljen“ ili „izuzetno proslavljen“. Takvo tumačenje rešava problem značenja Parakleta: | Ahmed | Paraklet | | | | | Više hvaljen/proslavljen | Izuzetno hvaljen/proslavljen | To znači da će dolazeći Paraklet biti osoba hvaljenija i proslavljenija od svih drugih. Isto tako, arapska reč Ahmed ime za koje Kur an navodi da ga je Isus pomenuo takođe znači „više“ ili „izuzetno hvaljen i proslavljen“. Vidimo da se ovo tumačenje reči parakletos izuzetno precizno podudara sa imenom „Ahmed“. Oba izraza prenose komparativnu ideju osobe koja je više hvaljena ili proslavljena, ne navodeći","headingId":"pravo-znacenje-reci-paraklet","headingText":"Pravo značenje reči „Paraklet“"},{"text":"izričito s kim se poredi. Time se poređenje ostavlja otvorenim, što predstavlja rečit način da se kaže kako će dolazeća osoba biti hvaljenija i proslavljenija od svih ostalih. Ako se parakletos protumači kao ime, a ne kao funkcija poput „Zastupnika“, „Utešitelja“ ili „Pomoćnika“, kako ga obično prevode prevodioci Novog zaveta, elegantno se rešava akademska lingvistička poteškoća poznata kao „problem Parakleta“. U svetlu svih ovih jezičkih veza, podudarnost između grčkog izraza parakletos i arapskog imena Ahmed može se dodati vezama prepoznatim u Biblijskim proročanstvima.","headingId":"pravo-znacenje-reci-paraklet","headingText":"Pravo značenje reči „Paraklet“"},{"text":"Abdul Ahad Davud bivši haldejski katolički sveštenik Kur an u suri Es Saff (61:6) beleži da je Isus najavio poslanika čije će ime biti upravo Ahmad a ne Muhamed. Ta razlika je lingvistički precizna i teološki značajna. Muhamed je prost participni oblik koji znači „hvaljen“, dok je Ahmad oblik superlativa sa značenjem „najhvaljeniji“. Grčki Perikletos takođe je oblik superlativa. Kur an, dakle, upotrebljava superlativ, a ta preciznost pokazuje poznavanje grčke etimologije koje nepismen Arapin iz 7. veka nije mogao posedovati osim putem božanskog otkrivenja. To predstavlja jedan od najsnažnijih unutrašnjih dokaza Božanskog porekla Kur ana. Abdul Ahad Davud bivši haldejski katolički sveštenik : „Ovo je jedan od najsnažnijih dokaza Muhamedovog poslanstva i da je Kur an zaista božanska objava, jer","headingId":"abdul-ahad-davud-bivsi-haldejski-katolicki-svestenik","headingText":"Abdul-Ahad Davud - bivši haldejski katolički sveštenik"},{"text":"Muhamed nije mogao znati da reč ‘Paraklit’ znači ‘Ahmad’ osim putem objave.“","headingId":"abdul-ahad-davud-bivsi-haldejski-katolicki-svestenik","headingText":"Abdul-Ahad Davud - bivši haldejski katolički sveštenik"},{"text":"Stari arapski prevodi Jevanđelja sačuvali su izraz umesto da ga prevedu Nekoliko starijih arapskih izdanja Jevanđelja i Novog zaveta nije jednostavno prevelo reč „Paraklet“ kao „Utešitelj“, već ju je sačuvalo u oblicima: الفارقليط / البارقليط / فارقليط To samo po sebi ne dokazuje islamsko čitanje, ali snažno potvrđuje uži zaključak koji je teže osporiti. Arapski hrišćanski prevodioci često su ovu reč tretirali kao poseban stručni izraz ili vlastito ime, a ne kao običnu reč sa jednim ustaljenim prevodom. Ova stara stranica arapskog Jevanđelja čuva naziv obećane ličnosti iz Jovana 14:16 u obliku فارقليط آخر „drugi Paraklet“. Prevodilac ovaj izraz nije sveo na uobičajeni arapski ekvivalent poput reči „Utešitelj“. Skenirana stranica podržava tvrdnju da je izraz bio shvaćen kao poseban stručni","headingId":"stari-arapski-prevodi-jevandjelja-sacuvali-su-izraz-umesto-da-ga-prevedu","headingText":"Stari arapski prevodi Jevanđelja sačuvali su izraz umesto da ga prevedu"},{"text":"termin, zbog čega je u arapskoj jevanđeljskoj tradiciji zadržan u transliterovanom obliku. Ova stranica Novog zaveta opisuje obećanu ličnost u kontekstu Jovana 16 izrazima شفاعة / شفيع „posredovanje“ i „zastupnik“. To neposredno ne podržava etimološko povezivanje sa imenom Ahmed, ali proširuje i potvrđuje značenjsko polje ove reči: Paraklet nije samo „uteha“ kao osećanje, već lični zastupnik i posrednik. To se uklapa u argument koji Parakleta povezuje sa proročkom ličnošću koja brani, svedoči, poučava i posreduje. Ova stranica potiče iz lajdenske tradicije arapskog Novog zaveta i prikazuje Jovana 14:26 sa istaknutim izrazom الفارقليط . Okolni tekst opisuje onoga koga Otac šalje u Isusovo ime, navodeći da će on poučavati i podsećati. Dokazna vrednost ove stranice nije u tome što neposredno potvrđuje","headingId":"stari-arapski-prevodi-jevandjelja-sacuvali-su-izraz-umesto-da-ga-prevedu","headingText":"Stari arapski prevodi Jevanđelja sačuvali su izraz umesto da ga prevedu"},{"text":"ime „Ahmed“, već u činjenici da je jedan stari arapski hrišćanski biblijski tekst sačuvao grčku pozajmljenicu umesto da je zameni jednim običnim arapskim prevodom. Kako pravilno koristiti ove dokaze Snažna tvrdnja jeste da su stari arapski hrišćanski prevodi često zadržavali naziv Paraklit/Faraklit kao tehnički termin. Umerenija tvrdnja jeste da zbog toga kasniji prevod „Utešitelj“ deluje više kao tumačenje nego kao neutralan prevod. Ne sme se, međutim, preterivati: ovi skenovi sami po sebi ne dokazuju da je u svakom rukopisu prvobitno stajalo Periklitos.","headingId":"stari-arapski-prevodi-jevandjelja-sacuvali-su-izraz-umesto-da-ga-prevedu","headingText":"Stari arapski prevodi Jevanđelja sačuvali su izraz umesto da ga prevedu"},{"text":"Arheološki argument Godfrija Higinsa Iz dela Apology to Mohamed (str. 718): „Tvrdnja muhamedanaca da grčki prevod te reči glasi ‘Paracletetus’, a ne ‘Paracletus’, dobija snažnu potvrdu u metodu koji je sveti Jeronim primenio prilikom prevođenja Vulgate na latinski, gde je tu reč preveo kao ‘Paracletus’ umesto ‘Paracletus’. To pokazuje da je predložak sa kojeg je sveti Jeronim prevodio morao sadržati reč ‘periklutos’, a ne ‘Paraclete’.“ Muslimani su takođe ukazivali na to da su primerci Jevanđelja na hebrejskom koji su bili u opticaju sačuvali vokalizaciju koja upućuje na Periklutos/Fraklitos , a ne na standardni oblik Parakletos . To nagoveštava da sadašnji grčki oblik možda predstavlja izmenu uvedenu krajem 3. ili početkom 4. veka.","headingId":"arheoloski-argument-godfrija-higinsa","headingText":"Arheološki argument Godfrija Higinsa"},{"text":"Izraz Paraklit nije božanska titula, već ljudski pomagač Reč „Paraklit“ u Jovanovom jevanđelju NIJE neko nejasno božansko ime. To je ustaljen termin koji znači pomagač, posrednik i branilac konkretno, ljudsko biće koje pomaže drugom ljudskom biću. Tekst tu ulogu povezuje sa poučavanjem, podsećanjem i svedočenjem, a ne sa ovaploćenjem ili nezavisnom božanstvenošću. Kasnije pretvaranje ovog „pomagača“ u punopravnu Ličnost Trojstva predstavljalo je razvoj postjovanovske teologije, a ne izvorno značenje tog izraza.","headingId":"izraz-paraklit-nije-bozanska-titula-vec-ljudski-pomagac","headingText":"Izraz Paraklit - nije božanska titula, već ljudski pomagač"},{"text":"Analiza Karen Armstrong Karen Armstrong nezavisna sekularna svedokinja Orijentalistkinja Karen Armstrong koja ne veruje u Muhamedovo ﷺ poslanstvo ipak je iznela tri značajna priznanja: izraz „Paraklit“ preveden je na sirijski kao al Munaḥmanna , reč koja je po značenju bliska imenu „Muhamed“; reč „Paraklit“ mogla bi se prevesti kao Ahmad ; i ona smatra da je Poslanikovo poznavanje ovog proročanstva navelo Muhameda ﷺ da tvrdi kako je ono bilo spomenuto u Isusovoj knjizi.","headingId":"analiza-karen-armstrong","headingText":"Analiza Karen Armstrong"},{"text":"Paraklet će svedočiti o Isusu Jovan 15:26 on će svedočiti za mene. Poslanik ﷺ doneo je Kur an, koji sadrži potpun i istinit prikaz Hrista, njegovog začeća, rođenja, poslanstva i čuda, od čega mnogo toga nije zabeleženo u poznatim Evanđeljima. Stoga je pitanje presudno: odakle je nepismeni Poslanik ﷺ mogao dobiti te informacije, ako ne putem objave?","headingId":"paraklet-ce-svedociti-o-isusu","headingText":"Paraklet će svedočiti o Isusu"},{"text":"Zaključak Kada se objedini celokupna ova analiza, alternativni doslovni prevod izraza parakletos , čiji je dolazak Isus prorekao, glasi „više hvaljen“ ili „više slavljen“. To znači da će dolazeći Paraklit biti osoba koja će biti hvaljena i slavljena više od svih drugih. Isto tako, arapska reč Ahmad , koju smo ranije razmatrali kao ime za koje Kur an tvrdi da ga je Isus spomenuo, takođe znači „više hvaljen“ ili „više slavljen“. Vidimo, dakle, da se ovo tumačenje reči parakletos izuzetno precizno podudara sa imenom Ahmad . Razlog je to što i parakletos i Ahmad izražavaju komparativnu ideju veće hvaljenosti ili slavljenosti, ne navodeći izričito s kim se poređenje vrši. Time se poređenje ostavlja otvorenim, što predstavlja upečatljiv način da se","headingId":"zakljucak","headingText":"Zaključak"},{"text":"istakne kako će dolazeća osoba biti hvaljenija i slavljenija od svih ostalih.","headingId":"zakljucak","headingText":"Zaključak"},{"text":"Odgovor na hrišćanske prigovore","headingId":"odgovor-na-hriscanske-prigovore","headingText":"Odgovor na hrišćanske prigovore"},{"text":"Prigovor 1: Da li je to „Sveti“ duh? Hrišćani navode Jovan 14:26 kao dokaz da je Paraklit Sveti Duh. Međutim, to je jedino mesto u Jovanovim oproštajnim govorima na kojem se uz Paraklita upotrebljava izraz „Sveti Duh“. Nekoliko rukopisnih varijanti izostavlja reč 'sveti', dok druge čitaju 'Duh istine'... neki naučnici su odbili da poistovete Parakleta sa Svetim Duhom. John The NIV Application Commentary, str. 398, pogledati izvor 20 U ovom stihu(14:26) reči τὸ ἅγιον, koje dolaze posle τὸ πνεῦμα, treba izostaviti u skladu sa Sinajskim sirijskim rukopisom, jer takvo čitanje najbolje objašnjava postojeće varijante. Nigde drugde kod Jovana ne susrećemo pun izraz τὸ πνεῦμα τὸ ἅγιον, \\ \\ pa se s pravom može posumnjati da je njegova pojava ovde posledica","headingId":"prigovor-1-da-li-je-to-sveti-duh","headingText":"Prigovor 1: Da li je to „Sveti“ duh?"},{"text":"kasnije ortodoksne teologije. Dodatak τὸ ἅγιον možda je prepisivač uneo bez loše namere kako bi tekst uskladio sa drugim novozavetnim odlomcima i simbolima vere. Za donekle sličnu izmenu dodavanje reči τὸ πνεῦμα videti 3:34. 26. τὸ πνεῦμα τὸ ἅγιον tako stoji u većini rukopisa; nekoliko njih usklađuje tekst sa izrazom τὸ πνεῦμα τῆς ἀληθείας iz stihova 14:17, 15:26 i 16:13. Sinajski sirijski rukopis izostavlja τὸ ἅγιον; ovo kraće čitanje možda je izvorno, jer bi objasnilo nastanak obe varijante. Zamenica ἐκεῖνος veoma je naglašena; izostavljaju je P⁶⁶ i D. Umesto εἶπον, rukopis D ima ἂν εἴπω. Time se delovanju Paraklita daje sasvim drugačije značenje. Sklonost dodavanju reči ἅγιον bila je i prirodna i široko rasprostranjena među hrišćanskim prepisivačima, dok bi njeno","headingId":"prigovor-1-da-li-je-to-sveti-duh","headingText":"Prigovor 1: Da li je to „Sveti“ duh?"},{"text":"izostavljanje bilo neobjašnjivo da je ta reč postojala u izvornom tekstu. Prepisivači su unosili različite izmene.. Pored toga, Codex Syriacus iz 5. veka pronađen u manastiru na Sinaju sadrži čitanje „Paraklit, Duh“, a NE „Paraklit, Sveti Duh“. Sam Novi zavet na više mesta koristi reč „duh“ kada govori o prorocima. Ako čak i prihvatimo njihov stav da je to \"Sveti\" duh, iako znamo da nije, možemo reći da su ljudi na drugim mestima u Bibliji nazvani \"Svetim\" duhom. S obzirom na kumransku i kasniju hrišćansku upotrebu, zanimljivo je da se izraz „sveti duh“ u Knjizi jubileja 1:21, 23, izgleda primenjuje na čoveka. Mojsije je nazvan „svetim duhom“ (11:16). Protivrečnost u vremenskom redosledu U Jovanu 16:7 stoji: Jovan 16:7 Ja vam","headingId":"prigovor-1-da-li-je-to-sveti-duh","headingText":"Prigovor 1: Da li je to „Sveti“ duh?"},{"text":"govorim istinu: za vas je bolje da odem, jer ako ja ne odem, Pomagač Utešitelj neće doći k vama. Ali ako odem, poslaću ga k vama. Ipak, Jovan 20:22 beleži da je Isus pre svog vaznesenja „dahnuo na njih i rekao: ‘Primite Svetoga Duha.’“ Jovan 20:17 22 Isus joj reče: „Ne dotiči me, jer još nisam uzašao svome Ocu. Nego, idi mojoj braći i reci im: ’Uzlazim svome Ocu i vašem Ocu, svome Bogu i vašem Bogu!’“ Rekavši ovo, dunuo je i rekao im: „Primite Duha Svetoga. Ako je Sveti Duh trebalo da siđe tek nakon Isusovog odlaska, kako ga je Isus mogao poslati učenicima pre svog vaznesenja? To predstavlja neposrednu unutrašnju protivrečnost koju tumačenje Paraklita kao Svetog Duha ne","headingId":"prigovor-1-da-li-je-to-sveti-duh","headingText":"Prigovor 1: Da li je to „Sveti“ duh?"},{"text":"može razrešiti. To znači da Paraklit ne može biti Sveti Duh!","headingId":"prigovor-1-da-li-je-to-sveti-duh","headingText":"Prigovor 1: Da li je to „Sveti“ duh?"},{"text":"Prigovor 2: Nazvan je duhom U kasnijim Jovanovskim spisima duhovi se poistovećuju sa prorocima, a vernici se pozivaju da iskušavaju te duhove kako bi se uverili da dolaze od Boga. To ne znači da su oni doslovno duhovna bića, već da se mogu nazvati duhovima zato što predstavljaju Duha koji prebiva u njima. 1. Jovanova 4:1 3 Voljeni moji, ne verujte svakom duhu, nego proveravajte duhove dolaze li od Boga, jer je mnogo lažnih proroka izašlo u svet. Po ovome se poznaje onaj koji ima Božijeg Duha: svako ko ispoveda da je Isus Hristos došao u telu, dolazi od Boga, a svaki duh koji ne priznaje Isusa ne dolazi od Boga. Taj ima duha antihristovog, za kojega ste čuli da","headingId":"prigovor-2-nazvan-je-duhom","headingText":"Prigovor 2: Nazvan je duhom"},{"text":"će doći, i već sada je u svetu.","headingId":"prigovor-2-nazvan-je-duhom","headingText":"Prigovor 2: Nazvan je duhom"},{"text":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed Na primer, Jovan 14:16 pominje Isusa koji izjavljuje da će Bog dati vama drugog Parakleta, što implicira da je i Isus Paraklet. Jovan 14:16 a ja ću izmoliti od Oca da vam da drugog Paraklet/Pomagača Utešitelja da bude sa vama doveka. Dakle, ako je paraklētos ime Ahmad, kao što sam tvrdio, onda implikacija glasi da je i Isus Ahmad, što je besmisleno. Kao odgovor, u ovom prigovoru se krije velika pretpostavka, naime da je jedan jedini autor po imenu Jovan odgovoran za zapisivanje svih izreka o Parakletu. Zapravo postoje dobri razlozi da se veruje da Jevanđelje po Jovanu ima više autora. Na primer, kraj Jovanovog jevanđelja nas obaveštava: Jovan 21:24 Taj","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"učenik svedoči za ovo i on je ovo zapisao, i mi znamo da je njegovo svedočanstvo istinito. Obratite pažnju na množinu zamenice \"mi\", što ukazuje da komentator ovde nije pojedinac, već grupa ili zajednica ljudi. Kao što biblijski naučnik Raymond Brown potvrđuje: „Raspravljali smo o fenomenu dupliranih govora u Jovanu, i ovde se očigledno bavimo još jednim primerom tog fenomena. Iste teme, pa čak i iste izreke, propovedane su, sakupljene i zapisane u dve različite zbirke koje mogu poticati iz različitih perioda u istoriji jovanovske tradicije, ili iz različitih krugova u jovanovskoj zajednici.\" The Gospel According to John [xiii – xxi], str. 594 Što se tiče konkretno izreka o Parakletu, one pokazuju dokaze više različitih izvora. Podsetimo se da izreke","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"o Parakletu koje sam obradio javljaju se u tri odvojena poglavlja Jevanđelja po Jovanu: poglavljima 14, 15 i 16. Zapazite sledeće komentare učenika u 14. poglavlju: Jovan 14:5 Toma mu reče: „Gospode, ne znamo gde ideš. Kako možemo da znamo put?“ Vidimo da u 14. poglavlju učenici postavljaju Isusu pitanja o tome kuda ide, a onda 16. poglavlje čudno prikazuje Isusa kako komentariše da ga niko ne pita kuda ide: Jovan 16:5 Sada odlazim k onome koji me je poslao, a niko od vas me ne pita: ’Kuda odlaziš?’ Jasno je da izreke o Parakletu u 16. poglavlju predstavljaju tok tradicije različit od onog u izrekama o Parakletu iz 14. poglavlja, jer se međusobno protivreče. Kao što sam naglasio na","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"poćetku u odeljku 1. Ovaj zaključak da su izreke o Parakletu sastavljene iz više izvora široko je prihvaćen u akademskim krugovima. Kao što tekstualni naučnik Bart Ehrman potvrđuje: „Čitaoci su tokom godina smišljali različite načine da objasne ovakve vrste književnih problema, ali možda je najjednostavnije reći da su oni nastali kao posledica autorove odluke da u svoju pripovest uplete različite pisane izvore. Postoji ponavljanje između 14. i 16. poglavlja zato što su ona zapravo bila dva izveštaja o istom događaju spojena zajedno.\" The Most Intriguing Evidence that John Used Sources\" Bart Ehrman Blog, March 31, 2020 Vidimo da razna poglavlja koja sadrže izreke o Parakletu nisu uzeta iz jednog izvora, već su to više izvora spojenih zajedno. Otuda nije nezamislivo","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"da su ti različiti izvori primenjivali pojam paraklētos na različite načine. Kao što teolog Kenneth Gyon potvrđuje: „Ako se čini neverovatnim da se različita značenja reči paraklētos nalaze tako blizu jedno drugom, može se odgovoriti da se Jovan 14 i Jovan 15–16 danas široko smatraju varijantnim oblicima jednog završnog govora, koji je verovatno sastavljen tako da odgovara različitim situacijama.\" El Ilelul kubra, str. 172. Ako se čini neverovatnim da se različita značenja reči paraklētos nalaze tako blizu jedno drugom, može se odgovoriti da se Jovan 14 i Jovan 15–16 danas široko smatraju varijantnim oblicima jednog završnog govora, koji je verovatno sastavljen tako da odgovara različitim situacijama. Novi testament Tekst i Jezik Druga mogućnost koju treba razmotriti jeste da autorima izvora","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"koji Isusa nazivaju Parakletom nije bilo prijatno sa pomišlju da bi mogao doći neko posle Isusa koji će biti više hvaljen i slavljen od njega. Drugim rečima, Isus je iz teoloških razloga pretvoren u još jednog Parakleta. Jedan hronološki sled koji objašnjava kako bi takva situacija mogla nastati jeste sledeći: Prvo, autor najstarijeg izvora izreke o Parakletu promenio je Ahmad iz njegovog izvornog semitskog jezika zamenivši ga grčkim ekvivalentom po značenju, paraklētos, kao što smo već raspravljali. Drugo, kasniji autori drugih tekstova koji eksplicitno nazivaju Isusa Parakletom bili su svesni ovog ranijeg izvora izreke o Parakletu kada su sastavljali svoje spise. Takođe bi bili svesni višestrukih značenja reči paraklētos, od kojih je jedno „hvaljen u višku preko\" ili „slavljen u","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"višku preko\". Mogla ih je uznemiriti pomisao da bi neko mogao biti više hvaljen i slavljen od Isusa. Otuda su iz teoloških razloga odlučili da i Isusa nazovu Parakletom, kako bi uzdigli njegov status, da bude na istoj ravni sa prorečenim Parakletom. Ovaj scenario nije tako nategnut ako uzmemo u obzir da smo već videli dokaze da su pisari umetali reč „sveti\" u izreke o Parakletu kako bi Parakleta pretvorili iz ljudske figure u Svetog Duha.","headingId":"prigovor-3-ako-je-parakletahmed-onda-je-i-isusahmed","headingText":"Prigovor 3: Ako je Paraklet=Ahmed onda je i Isus=Ahmed"},{"text":"Prigovor 3: Da li je Duh „u“ vama? Samo tri stiha kasnije, da li su vernici doslovno „u“ Isusu? Očigledno nisu; to jednostavno znači da su sjedinjeni u istoj misiji ili, kako stoji u fusnoti uz 17. stih, da je Duh „među“ njima. New Revised Standard Version Updated Edition 14.17 Or among Jovan 14:7 On je Duh istine. Njega svet ne može da primi, jer ga ne vidi i ne poznaje. Vi ga poznajete, jer sa vama boravi i biće u vama. Jovan 14:20 U taj dan ćete saznati da sam ja u svom Ocu, a da ste vi u meni i ja u vama.","headingId":"prigovor-3-da-li-je-duh-u-vama","headingText":"Prigovor 3: Da li je Duh „u“ vama?"},{"text":"Prigovor 4: Da li će biti sa vama „zauvek“? Mojsije i proroci u tom trenutku već odavno nisu bili živi, pa ipak Avraham tvrdi da su i dalje sa ljudima. Jasno je da to nije doslovno, već se odnosi na njihove spise ili učenja. Iako je Muhamed ﷺ umro, ostavio nam je Kur an i Sunnet da ih sledimo. Jovan 14:16 a ja ću izmoliti od Oca da vam da drugog Pomagača Utešitelja da bude sa vama doveka. Luka 16:27 29 Bogataš nastavi: ’Onda te molim, oče, da pošalješ Lazara u dom moga oca, gde imam petoro braće. Neka ide i upozori ih da ne bi došli na ovo mesto mučenja.’ Avraham reče: ’Oni imaju Mojsija i Proroke, pa neka","headingId":"prigovor-4-da-li-ce-biti-sa-vama-zauvek","headingText":"Prigovor 4: Da li će biti sa vama „zauvek“?"},{"text":"ih slušaju!’","headingId":"prigovor-4-da-li-ce-biti-sa-vama-zauvek","headingText":"Prigovor 4: Da li će biti sa vama „zauvek“?"},{"text":"Prigovor 5: Da li Isus „šalje“ Duha? Način na koji Isus „šalje“ Duha nije isti kao način na koji ga šalje Otac. Isus ga šalje posredstvom svoje MOLITVE, moleći Boga da im pošalje budućeg vodiča koji će pomoći da se njegovo učenje upotpuni. Jovan 14:16 a ja ću izmoliti od Oca da vam da drugog Pomagača Utešitelja da bude sa vama doveka. Jovan 15:26 A kada dođe Pomagač Utešitelj, koga ću vam poslati od Oca, Duha istine, Duh koji od Oca ishodi – on će svedočiti za mene. Kada Isus kaže: „Poslaću ga k vama“, slično kao što u Mateju kaže: „Poslaću im proroke“, iz Lukinog prikaza istog govora vidimo da Isus zapravo citira BOGA OCA. Međutim, autor izostavlja tu","headingId":"prigovor-5-da-li-isus-salje-duha","headingText":"Prigovor 5: Da li Isus „šalje“ Duha?"},{"text":"napomenu, iako se ona podrazumeva. Zato bi odlomak trebalo čitati ovako: „Ako ja (Isus) ne odem, Zastupnik neće doći k vama; ali ako ja (Isus) odem, [Otac kaže:] ‘Poslaću ga k vama.’“ Jovan 16:7 a vam govorim istinu: za vas je bolje da odem, jer ako ja ne odem, Pomagač Utešitelj neće doći k vama. Ali ako odem, poslaću ga k vama. Matej 23:34 Stoga, evo, ja vam šaljem proroke, mudrace i znalce Svetoga pisma. Neke od njih ćete pobiti i razapeti, a neke ćete bičevati po vašim sinagogama i terati iz vaših gradova. Luka 11:49 Zato Bog po svojoj mudrosti reče: ’Poslaću im proroke i apostole; neke će ubiti, a neke prognati.’ Nema čak ni promene perspektive! Primenićemo istu","headingId":"prigovor-5-da-li-isus-salje-duha","headingText":"Prigovor 5: Da li Isus „šalje“ Duha?"},{"text":"hrišćansku logiku. Mojsije se obraća celom Izraelu, govori o Gospodu u trećem licu i opisuje sve što je Bog učinio za njih. Međutim, u petom stihu Mojsije tvrdi da ih je četrdeset godina vodio kroz pustinju, a zatim, bez ikakvog nagoveštaja promene govornika, poput reči „Ovako govori Gospod“ kaže: „Da biste znali da SAM JA GOSPOD, BOG VAŠ!“ Nijedan hrišćanin pri zdravoj pameti ne bi tvrdio da se Mojsije ovde predstavlja kao Jahve. Morao bi, međutim, priznati da se podrazumeva kako Mojsije citira Boga. Isto tumačenje zato treba primeniti i na odlomak o Paraklitu. 5. Mojsijeva 29:2 6 Mojsije pozva sve Izrailjce i reče im: Vi ste videli sve što je Gospod na vaše oči učinio u Egiptu faraonu, svim","headingId":"prigovor-5-da-li-isus-salje-duha","headingText":"Prigovor 5: Da li Isus „šalje“ Duha?"},{"text":"njegovim dvoranima i celoj njegovoj zemlji. Svojim očima si video velika iskušenja, znakove i ona velika čudesa. Gospod vam sve do danas nije dao um da razumete, oči da vidite i uši da čujete. Četrdeset godina sam vas vodio po pustinji; odeća vam se nije pocepala, niti vam se obuća na vašim nogama poderala. Hleba niste jeli, vina i žestoka pića niste pili, da biste znali da sam ja Gospod, Bog vaš.","headingId":"prigovor-5-da-li-isus-salje-duha","headingText":"Prigovor 5: Da li Isus „šalje“ Duha?"},{"text":"Prigovor 6: Da li se obraća učenicima? Isus kaže: „TI ćeš ga videti kako dolazi na oblacima“ obraćajući se prvosvešteniku (o drugom dolasku videti Marko 8:38–9:1). Da li je prvosveštenik doživeo taj dolazak? Nije. Hrišćanin zato mora priznati da se zamenica „ti“ može odnositi i na ljude u budućnosti uopšte. Marko 14:61 62 Ali Isus je ćutao i nije ništa odgovorio. Prvosveštenik ga ponovo upita: „Jesi li ti Hristos, Sin Boga blagoslovenoga?“ „Jesam – odgovori Isus. A vi ćete videti Sina Čovečijeg kako sedi s desne strane Svesilnoga i dolazi na oblacima nebeskim.“ Bog obećava proroka poput Mojsija koji će doći između VAS Izrailjaca i kojem se VI morate pokoravati. Međutim, prema njihovom tumačenju, Isus je taj Prorok (Jovan 6:14;","headingId":"prigovor-6-da-li-se-obraca-ucenicima","headingText":"Prigovor 6: Da li se obraća učenicima?"},{"text":"7:40; Dela apostolska 3:22–23), iako je došao 1.400 godina posle Mojsija! 5. Mojsijeva 18:15 16 Gospod, Bog tvoj, podići će ti proroka među vama, od vaše braće, kao što sam ja. Njega slušajte! 16To je ono što si tražio od Gospoda, Boga svoga, na gori Horiv na dan zbora: ’Neću više da slušam glas Gospoda, Boga svoga, niti da gledam ovaj veliki oganj, da ne umrem!’","headingId":"prigovor-6-da-li-se-obraca-ucenicima","headingText":"Prigovor 6: Da li se obraća učenicima?"},{"text":"Prigovor 7: Da li je Duh već sa njima? Takođe se kaže da duh Antihrista dolazi… ali da je već među ljudima. Da li je Antihrist već tamo? Naravno da nije. To samo znači da je prisutan duh koji nekoga nadahnjuje i daje mu snagu. Jovan 14:17 On je Duh istine. Njega svet ne može da primi, jer ga ne vidi i ne poznaje. Vi ga poznajete, jer sa vama boravi i biće u vama. 1. Jovanova 4:3 a svaki duh koji ne priznaje Isusa ne dolazi od Boga. Taj ima duha antihristovog, za kojega ste čuli da će doći, i već sada je u svetu. Sada upućujem izazov hrišćanima: pokažite mi makar JEDNO mesto na kojem piše da je","headingId":"prigovor-7-da-li-je-duh-vec-sa-njima","headingText":"Prigovor 7: Da li je Duh već sa njima?"},{"text":"PARAKLIT kao osoba već bio prisutan. Takvo mesto ne postoji. Kaže se samo da je Duh prisutan, a iz Prve Jovanove 4 znamo da se on poistovećuje sa duhom koji je u proroku.","headingId":"prigovor-7-da-li-je-duh-vec-sa-njima","headingText":"Prigovor 7: Da li je Duh već sa njima?"},{"text":"Prigovor 8: Da li je Duh poslat „u Isusovo ime“? To što je Paraklit poslat „u Isusovo ime“ znači da dolazi po njegovom ovlašćenju i kao predstavnik njegove misije; taj izraz sam po sebi ne dokazuje da je Paraklit božansko biće. Zato što izraz „u nečije ime“ označava ovlašćenje, a ne prirodu bića . Na primer, ambasador govori „u ime kralja“, ali nije kralj. Apostoli propovedaju i čine dela „u Isusovo ime“, ali time ne postaju božanska bića. Dakle, Jovan 14:26 kaže ko šalje i čiji autoritet Paraklit predstavlja , ali izraz „u moje ime“ sam po sebi ne govori da li je Paraklit božanska ličnost. Jovan 14:26 A Pomagač Utešitelj, Duh Sveti, koga Otac šalje u moje ime, poučiće","headingId":"prigovor-8-da-li-je-duh-poslat-u-isusovo-ime","headingText":"Prigovor 8: Da li je Duh poslat „u Isusovo ime“?"},{"text":"vas svemu i podsetiće vas na sve što sam vam rekao. Matej 10:41 Ko prihvata proroka zato što je prorok , taj će primiti proročku platu. Ko prihvata pravednika zato što je pravednik, taj će primiti pravedničku platu.","headingId":"prigovor-8-da-li-je-duh-poslat-u-isusovo-ime","headingText":"Prigovor 8: Da li je Duh poslat „u Isusovo ime“?"},{"text":"Prigovor 9: „Sve što Otac ima moje je“ Isus kaže da će Duh uzeti od onoga što je njegovo i objaviti to ljudima. Ako pratimo smisao teksta unazad, vidimo da je uloga Duha da objavljuje Isusova UČENJA. Zato se izraz „sve što Otac ima“ odnosi na učenja koja je Isus primio od Oca, a ne doslovno na sve što postoji. Jovan 16:15 Sve što ima Otac, pripada i meni. Zato sam vam rekao da će od mene uzeti i vama najavljivati. Jovan 8:28 Isus im tada reče: „Kada podignete Sina Čovečijeg, tada ćete shvatiti da Ja Jesam. Ja ništa ne činim sam od sebe, nego govorim kako me je naučio Otac. Jovan 14:28 A Pomagač Utešitelj, Duh Sveti, koga Otac","headingId":"prigovor-9-sve-sto-otac-ima-moje-je","headingText":"Prigovor 9: „Sve što Otac ima moje je“"},{"text":"šalje u moje ime, poučiće vas svemu i podsetiće vas na sve što sam vam rekao.","headingId":"prigovor-9-sve-sto-otac-ima-moje-je","headingText":"Prigovor 9: „Sve što Otac ima moje je“"},{"text":"Prigovor 10: Da li Isus daje objavu? Interlinearni prevod pokazuje da će Duh jednostavno uzeti od Hristovih učenja, a ne neposredno od njega primiti objavu. Jovan 16:14 On će me proslaviti, jer će od mene primiti i vama najavljivati.","headingId":"prigovor-10-da-li-isus-daje-objavu","headingText":"Prigovor 10: Da li Isus daje objavu?"}]},{"slug":"Ponovljeni-zakon-18-18","chunks":[{"text":"Proročanstvo postavlja četiri uslova: da će to biti poslanik, a ne bog niti bogočovek; da će biti između braće sinova Israilovih, dakle ne iz samih sinova Israilovih; da će biti poput Musaa; i da će mu Bog Svoje reči staviti u usta, što znači da će primati neposrednu objavu. Ograničavajuća odredba „između vas\", koja bi proročanstvo svela na Israilćane, izostaje u Septuaginti, samarićanskom Petoknjižju, rukopisima Ponovljenog zakona sa Mrtvog mora i u navodu u Delima apostolskim.","headingId":"","headingText":""},{"text":"Tekst proročanstva Ponovljeni zakon 18:15 18 Gospod Bog tvoj podignuće ti proroka između braće tvoje, kao što sam ja, njega slušajte… Podignuću im proroka između braće njihove, kao što si ti, i metnuću reči svoje u usta njegova, i kazivaće im sve što mu zapovedim.","headingId":"tekst-prorocanstva","headingText":"Tekst proročanstva"},{"text":"Četiri uslova 1. Biće poslanik, a ne bog niti bogočovek. 2. Biće između braće sinova Israilovih, dakle ne iz samih sinova Israilovih. 3. Biće poput Musaa. 4. Bog će mu Svoje reči staviti u usta, što znači da će primati neposrednu objavu.","headingId":"cetiri-uslova","headingText":"Četiri uslova"},{"text":"Ko su braća sinova Israilovih Postanje 25:18 I nastaniše se među svom braćom svojom. Postanje 16:12 I nastaniće se prema svoj braći svojoj. I Edomci se u Bibliji nazivaju braćom, iako su rođaci, a ne potomci Israilovi: Ponovljeni zakon 23:7 Nemoj se gaditi na Edomca, jer ti je brat. Majmonid je priznao da se izraz „između braće tvoje\" prirodno odnosi na Isava i Ismaila, bez dodatnih ograda, i da je potreban poseban argument da bi se svelo samo na Israilćane. Majmonid.","headingId":"ko-su-braca-sinova-israilovih","headingText":"Ko su braća sinova Israilovih"},{"text":"Rukopisno pitanje Odredba „između vas\", koja bi proročanstvo ograničila na Israilćane, ne javlja se u Septuaginti, samarićanskom Petoknjižju, rukopisima Ponovljenog zakona sa Mrtvog mora, ni u navodu u Delima apostolskim. Ona se javlja isključivo u masoretskom tekstu.","headingId":"rukopisno-pitanje","headingText":"Rukopisno pitanje"},{"text":"Samarićansko Petoknjižje I neće se više podići u Israilu prorok poput Musaa. Reč je o trajnoj negaciji u budućnosti, za razliku od masoretske konstrukcije u prošlom vremenu: Ponovljeni zakon 34:10 I ne usta više prorok u Izrailju kao Mojsije.","headingId":"samaricansko-petoknjizje","headingText":"Samarićansko Petoknjižje"},{"text":"Ocena katoličkog sveštenika Otac Pol el Fegali primetio je da je čitanje zasnovano na doslovnom tumačenju pokazalo da Isus ne može biti poslanik kojeg je Musa najavio, i to zbog nepodudaranja sa samim uslovima proročanstva. Otac Pol el Fegali.","headingId":"ocena-katolickog-svestenika","headingText":"Ocena katoličkog sveštenika"},{"text":"Istorijska jevrejska svedočanstva Ibn Hišam u svojoj Siri beleži kazivanje o jevrejskom susedu koji je govorio da će doći poslanik iz ovih krajeva, pokazujući ka Meki i Jemenu. Ibn Hišam, Sira. Teofan je zabeležio da je deset jevrejskih prvaka isprva prihvatilo Muhammedovo ﷺ poslanstvo, verujući da je on očekivani Mesija. Teofan Ispovednik, Hronografija.","headingId":"istorijska-jevrejska-svedocanstva","headingText":"Istorijska jevrejska svedočanstva"}]},{"slug":"Ponovljeni-zakon-18-20-i-lazni-poslanici","chunks":[{"text":"Ponovljeni zakon 18:20 postavlja merilo: poslanik koji govori u Božije ime ono što mu nije naređeno, umreće. To se razume tako da lažni poslanik biva ubijen ili umire pre nego što dovrši svoju misiju. Primenjeno na poznate pretendente, merilo daje dosledan ishod, dok je poslanica Muhammeda ﷺ dovršena, što potvrđuje ajet o upotpunjenju vere.","headingId":"","headingText":""},{"text":"Merilo Ponovljeni zakon 18:20 Ali prorok koji bi se usudio govoriti šta u moje ime što mu ja ne zapovedim da govori, ili koji bi govorio u ime drugih bogova, takav prorok da se pogubi. To se razume tako da lažni poslanik biva ubijen ili umire pre nego što dovrši svoju misiju.","headingId":"merilo","headingText":"Merilo"},{"text":"Jovan Krstitelj Jovan Krstitelj nije tvrdio da je on očekivani poslanik, nego je iščekivao dolazak drugoga. Matej 11:3 Jesi li ti onaj što će doći, ili drugoga da čekamo?","headingId":"jovan-krstitelj","headingText":"Jovan Krstitelj"},{"text":"Isa, mir neka je na njega Ako se to proročanstvo primeni na Isaa, uz hrišćansko verovanje da je ubijen, onda bi po tom merilu ispao lažan. Muslimani, međutim, ne prihvataju da je Isa ubijen. Kur'an navodi da nije ni ubijen ni raspet, nego da je uzdignut Allahu. Ovaj argument, dakle, pogađa hrišćansko shvatanje, a ne muslimansko.","headingId":"isa-mir-neka-je-na-njega","headingText":"Isa, mir neka je na njega"},{"text":"Muhammed ﷺ Njegova poslanica dovršena je u najpotpunijem obliku, što potvrđuje i objava: Sura El Maida 5:3 Sada sam vam veru vašu usavršio i blagodat Svoju prema vama upotpunio i zadovoljan sam da vam islam bude vera.","headingId":"muhammed-","headingText":"Muhammed ﷺ"},{"text":"Poznati pretendenti i njihov ishod 1. Musejlema ubijen u Bici na Jemami. 2. El Esved el Ansi ubijen u svom dvorcu. 3. Mirza Gulam Kadijani umro u neočekivanim okolnostima nakon jedne verske rasprave. 4. Bab zatvoren, a zatim pogubljen. 5. Rašad Halifa ubijen od strane bliskih saradnika.","headingId":"poznati-pretendenti-i-njihov-ishod","headingText":"Poznati pretendenti i njihov ishod"}]},{"slug":"Ponovljeni-zakon-33-2-i-Paran","chunks":[{"text":"Ponovljeni zakon 33:2 spominje tri mesta: Sinaj, Seir i Paran. Masoretski tekst na jednom mestu ima oblik ואתה, dok samarićanski, Septuaginta, Vulgata, targumi i sirijski imaju ואתו. Sama jevrejska predanja, Midraš Tanhuma, Targum Jonatan i Raši, Paran izričito vezuju za sinove Ismailove, a Seir za sinove Isavove.","headingId":"","headingText":""},{"text":"Tekst Ponovljeni zakon 33:2 Gospod izađe sa Sinaja, i pokaza im se sa Seira; zasja s gore Faranske. Avakum 3:3 Bog dođe od Temana i Svetac s gore Farana.","headingId":"tekst","headingText":"Tekst"},{"text":"Rukopisna razlika Masoretski tekst na jednom mestu ima oblik ואתה, u čitanju kao „dođe\", dok samarićanski tekst, Septuaginta, Vulgata, targumi i sirijski prevod imaju ואתו, u čitanju „s njim\". Svi drevni tekstovi, dakle samarićanski, grčki, latinski, aramejski i sirijski, na tom mestu odstupaju od hebrejskog masoretskog teksta.","headingId":"rukopisna-razlika","headingText":"Rukopisna razlika"},{"text":"Gde je Paran Postanje 21:21 A on življaše u pustinji Faranu. Postanje 25:12 18 A življahu od Evila do Sura prema Egiptu. Naziv Paran u Bibliji nema jedno jedino mesto. U Brojevima se smešta na Sinajsko poluostrvo, u predeo Vadi Fejrana, dok ga Ponovljeni zakon 1:1 smešta istočno od Jordana. Adam Klark u svom komentaru navodi da Paran leži na samim granicama Obećane zemlje, na ogromnoj udaljenosti od prethodno spomenutog mesta. Adam Clarke, komentar Biblije. Sam izvorni tekst priznaje da tu postoji zabuna. Enciklopedija Biblika navodi da nije lako razumeti sva starozavetna mesta koja se odnose na Paran. Uz to, 1. Samuilova 25:1 spominje Paran, dok Septuaginta na istom mestu ima Maon, što ukazuje na oštećenje teksta.","headingId":"gde-je-paran","headingText":"Gde je Paran"},{"text":"Jevrejska predanja Sveti je ponudio Toru svim narodima… Seir se odnosi na sinove Isavove, a gora Paran na sinove Ismailove. Izvor: Midraš Tanhuma. Midraš Tanhuma. Targum Jonatan navodi da je Bog Zakon ponudio sinovima Ismailovim kod Parana, ali da ga oni nisu prihvatili. Targum Jonatan. Raši, uz Avakuma 3:3, navodi: „Ponudio si ga Isavu i Ismailu, i oni ga nisu prihvatili.\" Raši, uz Avakuma 3:3. Značaj tih predanja je u tome što ne dolaze iz muslimanskih izvora. Sama jevrejska tradicija Paran vezuje za Ismaila i njegovo potomstvo, nezavisno od bilo kakvog islamskog tumačenja.","headingId":"jevrejska-predanja","headingText":"Jevrejska predanja"},{"text":"Pitanje glagolskog vremena Prigovor da je glagol u prošlom vremenu, pa da se ne može odnositi na budućnost, ne stoji, jer se proročanstva u hebrejskom redovno izriču u prošlom vremenu. Isaija 53:7 Mučen bi i zlostavljen, ali ne otvori usta svojih. I to je proročanstvo izrečeno u prošlom vremenu, iako se odnosi na budućnost.","headingId":"pitanje-glagolskog-vremena","headingText":"Pitanje glagolskog vremena"},{"text":"Prevodilačka nedoslednost U pojedinim arapskim prevodima hebrejska množina עַמִּים, dakle narodi, prevedena je jedninom, kao narod, čime se prikriva šira primenljivost teksta izvan Israila.","headingId":"prevodilacka-nedoslednost","headingText":"Prevodilačka nedoslednost"}]},{"slug":"Psalam-120-i-satori-Kedarovi","chunks":[{"text":"Aramejski targum uz Psalam 120 naziv Kedar zamenjuje izrazom „šatori Arapa\", čime sama drevna jevrejska tumačiteljska tradicija Kedar razume etnički, kao Arape. Hebrejski oblik mešeh može označavati i trajanje, a ne nužno naziv mesta, jer hebrejski izvorno nije imao samoglasničke oznake. Tako se peti stih može čitati kao „dugo sam boravio\", što psalam čini opisom dugotrajnog progona.","headingId":"","headingText":""},{"text":"Tekst Psalam 120:5 7 Teško meni kad sam tuđin u Mesehu, živim među šatorima Kidarskim. Dugo živi duša moja s onima koji mrze mir. Ja sam miran, ali kad progovorim, oni su na rat.","headingId":"tekst","headingText":"Tekst"},{"text":"Kedar kao Arapi Aramejski targum uz Psalam 120 naziv Kedar zamenjuje izrazom „šatori Arapa\". Aramejski targum uz Psalme. To pokazuje da je drevna jevrejska tumačiteljska tradicija Kedar razumela etnički, kao Arape, a ne samo simbolički.","headingId":"kedar-kao-arapi","headingText":"Kedar kao Arapi"},{"text":"Rukopisna svedočanstva Arapsko latinsko svedočanstvo Psalama u delu David Regis et Prophetae, koje je priredio J. J. L. Barže 1861. godine, čuva tekst: „Teško meni što dugo boravim… i živim u šatorima Kedarovim.\" David Regis et Prophetae, prir. J. J. L. Bargès, 1861. Arapski hrišćanski psaltir bazilijanske crkve iz 1871. godine čuva oblik: „Boravio sam u staništima, odnosno šatorima Kedarovim.\" Bazilijanski psaltir, 1871.","headingId":"rukopisna-svedocanstva","headingText":"Rukopisna svedočanstva"},{"text":"O reči mešeh Hebrejski oblik משך, mešeh, može označavati trajanje ili dugo razdoblje, a ne nužno naziv mesta. Hebrejski jezik izvorno nije imao samoglasničke oznake, a masoretska vokalizacija uvedena je znatno kasnije. Bez vokalizacije, peti stih može se čitati kao „dugo sam boravio\", umesto „boravim u Mesehu\".","headingId":"o-reci-meseh","headingText":"O reči mešeh"},{"text":"Čitanje psalma Tako se psalam čita kao opis dugotrajnog tlačenja u Meki, boravka među Kurejšijama, odnosno Kedarom, i položaja vernika koji su mirni, a kojima se odgovara ratom, dakle stanja muslimana pre Hidžre.","headingId":"citanje-psalma","headingText":"Čitanje psalma"},{"text":"O Majmonidovom tumačenju Majmonid je u svom pismu Jemenu taj psalam primenio na jevrejsko stradanje pod muslimanskom vlašću, navodeći: „Teško meni što živim sa Mesehom i među šatorima Kedarovim.\" Majmonid, Pismo Jemenu. Na to se odgovara pitanjem: ako Kedar označava Kurejšije i Arape, da li su Jevreji doslovno živeli među mekanskim šatorima? Psalam, dakle, opisuje muslimane koji stradaju među Kurejšijama pre Hidžre.","headingId":"o-majmonidovom-tumacenju","headingText":"O Majmonidovom tumačenju"}]},{"slug":"Psalam-72-i-narod-Sabe","chunks":[{"text":"Hebrejski naziv Šeba u Psalmu 72 rečnici određuju kao narod i oblast Srećne Arabije, a niz arapskih hrišćanskih rukopisa, od jedanaestog do osamnaestog veka, to mesto prevodi izrazom Arapi. Metju Henri priznaje da se mnoga mesta u tom psalmu ne mogu primeniti na Sulejmanovu vladavinu.","headingId":"","headingText":""},{"text":"Tekst Psalam 72:10 11 Carevi Tarsiski i ostrvljani doneće dare, carevi Šavski i Savski daće danak. Klanjaće mu se svi carevi, svi narodi biće mu pokorni. Psalam 72:17 Ime će njegovo ostati doveka; dokle traje sunce, ime će se njegovo množiti. I blagosiljaće se u njemu, svi ga narodi zvati blaženim.","headingId":"tekst","headingText":"Tekst"},{"text":"Ko su narodi Šebe Brown Driver Briggsov hebrejski rečnik Šebu određuje kao narod i oblast Srećne Arabije. Brown Driver Briggs Hebrew Lexicon, odrednica Šeba. Isto navodi i Gezenijusov hebrejsko haldejski rečnik. Gesenius' Hebrew Chaldee Lexicon. Na to upućuje i rečnička odrednica uz izdanje JPS iz 1985. godine. JPS 1985, Sefaria.","headingId":"ko-su-narodi-sebe","headingText":"Ko su narodi Šebe"},{"text":"Arapski hrišćanski rukopisi Niz arapskih hrišćanskih rukopisa, koji se prostiru od jedanaestog do osamnaestog veka, hebrejski naziv Šeba dosledno prenosi izrazom العرب, dakle Arapi. Treba biti precizan: rečnici Šebu određuju kao narod i oblast, a ne kao jednu osobu. Ono što ti rukopisi pokazuju jeste da su rani hrišćanski čitaoci to mesto razumeli kao upućivanje na Arape, a ne da u samom tekstu stoji lično ime.","headingId":"arapski-hriscanski-rukopisi","headingText":"Arapski hrišćanski rukopisi"},{"text":"Šta kažu hrišćanski komentatori Metju Henri navodi da se mnoga mesta u tom psalmu ne mogu primeniti na Sulejmanovu vladavinu. Matthew Henry, komentar Psalama.","headingId":"sta-kazu-hriscanski-komentatori","headingText":"Šta kažu hrišćanski komentatori"},{"text":"Zašto to ne može biti Sulejman Psalam govori o vladavini koja traje dokle traje sunce, o pokornosti svih naroda i o imenu koje se množi kroz sva vremena, što prevazilazi okvire jedne istorijske vladavine.","headingId":"zasto-to-ne-moze-biti-sulejman","headingText":"Zašto to ne može biti Sulejman"},{"text":"Ime koje se blagosilja Ime koje se u psalmu spominje i koje se množi dovodi se u vezu sa korenom u značenju hvaljen, od kojeg dolazi i ime Muhammed, u značenju hvaljeni.","headingId":"ime-koje-se-blagosilja","headingText":"Ime koje se blagosilja"}]},{"slug":"Psalam-84-i-Bekka","chunks":[{"text":"Više drevnih prevoda Psalma 84 to mesto donosi tako da povezuje Bekku sa tri postojana elementa: sa određenim čovekom koji je u njoj rođen i u njoj boravi, sa davanjem novog Zakona, i sa davanjem blagoslova. Kirkpatrik u svom komentaru napominje da reč baka potiče od korena koji znači plakati, ali da nigde u Bibliji ne znači plakanje, te da balzamovo drveće obilno raste u sušnoj mekanskoj dolini.","headingId":"","headingText":""},{"text":"Tekst Psalam 84:5 6 Blago onima kojima je sila u Tebi… Prolazeći dolinom plača pretvaraju je u izvore.","headingId":"tekst","headingText":"Tekst"},{"text":"Drevni prevodi 1. Koptsko arapski prevod Psalama: „Blago čoveku koji se u Tebe uzda, Gospode; Zakonodavac daje blagoslove svojim sledbenicima.\" 2. Prevod Psalama sa teksta Septuaginte, 1954: „Blago čoveku kojem Ti pomažeš, koji je odlučio da se popne u dolinu Baka; penje se ka mestu koje dobro poznaje i koje namerava; na tom mestu Sudija, Bog, daje mu blagoslov.\" 3. Prevod jezuitskih otaca, 1897: „Prolaze dolinom plača i čine je mestom izvora. Jer Zakonodavac ih obasipa svojim blagoslovima.\" 4. Prevod Starog zaveta, 1811: „Blago čoveku kojeg si Ti izbavio od Sebe, koji je Božije zakone stavio u svoje srce. Rođen je u dubini Bekke, i tu je bilo njegovo boravište; tu uspostavlja novi Zakon.\" 5. Verzija Dejvida Tomasa: „Blago čoveku","headingId":"drevni-prevodi","headingText":"Drevni prevodi"},{"text":"koji se u Tebe uzda, kojeg si Ti izbavio od Sebe. Ti si ga, Bože, smestio u Bekku; u Bekki on uspostavlja Zakon.\" 6. Verzija Ibn el Assala: „Blago čoveku kojeg si Ti izbavio od Sebe, koji je Tvoje zakone stavio u svoje srce. Rođen je u Bekki, i ona je bila njegovo boravište; tu daje Zakon i blagoslove.\" Svaki drevni prevod, dakle, Bekku povezuje sa tri postojana elementa: sa određenim čovekom koji je u njoj rođen i u njoj boravi, sa davanjem novog Zakona, i sa davanjem blagoslova. Van Dajkov arapski prevod tu osobu potpuno izostavlja, iako je svaki stariji prevod čuva.","headingId":"drevni-prevodi","headingText":"Drevni prevodi"},{"text":"Kirkpatrikov komentar Baka potiče od korena koji znači plakati, ali nigde u Bibliji ne znači plakanje, jer se za to koriste reči drugog oblika. Za balzamovo drveće se kaže da voli suva staništa, pa tako obilno raste, na primer, u sušnoj dolini Meke. Izvor: A. F. Kirkpatrik. A. F. Kirkpatrick, The Book of Psalms: Introduction and Notes, tom 2, str. 507.","headingId":"kirkpatrikov-komentar","headingText":"Kirkpatrikov komentar"},{"text":"Kur'anska mesta Sura Ali Imran 3:96 Prvi hram sagrađen za ljude jeste onaj u Bekki, blagoslovljen je on i putokaz svetovima. Sura Ibrahim 14:37 Gospodaru naš, ja sam neke potomke svoje naselio u kotlini u kojoj se ništa ne seje, kod Tvoga Časnog hrama.","headingId":"kuranska-mesta","headingText":"Kur'anska mesta"},{"text":"Svedočanstvo Mudžahida Ja sam Bog Bekke. Smestio sam je između ove dve planine. Oblikovao sam Sunce i Mesec, okružio je sa sedam uspravnih meleka, a opskrbu njenih stanovnika učinio da dolazi sa tri puta, jer se ljudima Meke prilazi samo sa tri puta: gornjom dolinom, donjom dolinom i Kudom. I blagoslovio sam njene stanovnike u mesu i vodi. Izvor: preneseno od Mudžahida, preko Husajfa ibn Abdur Rahmana. Ahbar Mekka, str. 138, izd. Abdul Melik ibn Duhajš, 2003.","headingId":"svedocanstvo-mudzahida","headingText":"Svedočanstvo Mudžahida"},{"text":"Podudarnost sa hadisom Psalam 84:10 Jer je bolji dan u dvorima Tvojim nego hiljada. Namaz u mojoj džamiji bolji je od hiljadu namaza na drugom mestu, osim u Časnoj džamiji. Izvor: Buhari i Muslim. Sahih Buhari, 1190; Sahih Muslim, 1394.","headingId":"podudarnost-sa-hadisom","headingText":"Podudarnost sa hadisom"},{"text":"Pet podudarnosti sa Mekom 1. Naziv Bekka, koji se javlja i u Kur'anu. 2. Položaj između dve planine, Safe i Merve. 3. Izvor vode, Zemzem. 4. Neplodna dolina, kako navodi i Kur'an. 5. Umnožena vrednost namaza na tom mestu.","headingId":"pet-podudarnosti-sa-mekom","headingText":"Pet podudarnosti sa Mekom"},{"text":"Jezička napomena Masoretski tekst na tom mestu ima אדם בטח בך, dok Jerusalimski Talmud ima אדם בוטח בך. Arapski nadimak el Abtahi i hebrejski oblik butah dele isti semitski troslovni koren. El Abtah je šljunkovito korito doline između Meke i Mine.","headingId":"jezicka-napomena","headingText":"Jezička napomena"}]},{"slug":"Rukopisne-razlike-u-Jovanovom-jevandjelju","chunks":[{"text":"U Jovanu 7:52 papirusi 66 i 75, iz drugog veka, imaju određeni član ispred reči poslanik, pa tekst glasi „Poslanik\", a ne „poslanik\". Isto ima i sahidski koptski rukopis. U Jovanu 1:27 izraz „koji je preda mnom postao\" izostaje u papirusima 66 i 75, u Sinajskom, Vatikanskom i Efremovom kodeksu, a prvi put se javlja u aleksandrijskom rukopisu iz petog veka.","headingId":"","headingText":""},{"text":"Jovan 7:52 i određeni član Sinajski i Vatikanski kodeks na tom mestu imaju: „Ispitaj i vidi da prorok iz Galileje ne dolazi.\" Papirusi 66 i 75, iz drugog veka, ispred reči prorok imaju određeni član, ὁ προφήτης, pa tekst glasi „Poslanik\", dakle onaj određeni, očekivani poslanik. Sahidski koptski rukopis to mesto donosi rečima: „Poslanik nije trebalo da dođe iz Galileje.\"","headingId":"jovan-752-i-odredjeni-clan","headingText":"Jovan 7:52 i određeni član"},{"text":"Šta o tome kažu istraživači Brus Meciger i Bart Erman navode da prisustvo određenog člana menja smisao, tako da tekst govori o tome da određeni Poslanik ne dolazi iz Galileje. Bruce Metzger i Bart Ehrman, o tekstualnoj kritici Novog zaveta. Otac Fehim Aziz primećuje da čitanje Jovana 7:52 iz papirusa 66 rešava problem koji je komentatore dugo zbunjivao. Otac Fehim Aziz. Razlika je značajna zato što bez određenog člana tekst poriče da iz Galileje dolazi bilo koji poslanik, što je istorijski netačno, jer su iz tog kraja bili i raniji poslanici. Sa određenim članom, tekst govori o jednom određenom očekivanom Poslaniku, čime taj problem nestaje.","headingId":"sta-o-tome-kazu-istrazivaci","headingText":"Šta o tome kažu istraživači"},{"text":"Jovan 1:27 i naknadni dodatak Izraz „koji je preda mnom postao\", ὃς ἔμπροσθέν μου γέγονεν, ne javlja se u sledećim rukopisima: 1. Papirus 66 2. Papirus 75 3. Sinajski kodeks 4. Vatikanski kodeks 5. Efremov kodeks Taj dodatak prvi put se javlja u aleksandrijskom rukopisu iz petog veka. Kritička izdanja Nestle Aland, Vestkot Hort i UBS taj dodatak izostavljaju, i to upravo na osnovu najstarijih rukopisa. Nestle Aland; Westcott Hort; UBS Greek New Testament.","headingId":"jovan-127-i-naknadni-dodatak","headingText":"Jovan 1:27 i naknadni dodatak"},{"text":"Svedočanstvo iz drugog veka Dionisije Korintski, u drugom veku, žali se da prepisivači brišu i dodaju stvari u tekstovima Pisma. Dionisije Korintski.","headingId":"svedocanstvo-iz-drugog-veka","headingText":"Svedočanstvo iz drugog veka"}]},{"slug":"Stara-karta-gore-Paran","chunks":[{"text":"Maleova ručno crtana karta Arabije, objavljena u Parizu 1685. godine, planine Paran smešta neposredno uz Medinu. Strongov hebrejski rečnik Paran određuje kao pustinju Arabije. Ibn Ezra pustinju u kojoj je Ismail živeo poistovećuje sa Arapskim poluostrvom, a bunar iz Postanja 16 sa Zemzemom.","headingId":"","headingText":""},{"text":"Tekst Ponovljeni zakon 33:2 Gospod izađe sa Sinaja, i pokaza im se sa Seira; zasja s gore Faranske, i dođe s mnoštvom hiljada svetaca. Uobičajena hrišćanska tvrdnja jeste da se Paran nalazi u Palestini.","headingId":"tekst","headingText":"Tekst"},{"text":"Kartografsko svedočanstvo Ručno crtana karta Arabije koju je Male objavio u Parizu 1685. godine prikazuje Arapsko poluostrvo sa oznakom „planine Paran\" neposredno uz Medinu. Alain Manesson Mallet, karta Arabije, Pariz, 1685. Poređenje sa savremenom kartom Saudijske Arabije potvrđuje položaj Medine u odnosu na tu istorijsku kartografiju.","headingId":"kartografsko-svedocanstvo","headingText":"Kartografsko svedočanstvo"},{"text":"Rečnička odrednica Strongov hebrejski rečnik Paran određuje kao pustinju Arabije. Strong's Hebrew Dictionary, odrednica Paran.","headingId":"recnicka-odrednica","headingText":"Rečnička odrednica"},{"text":"Jevrejska tumačenja Ibn Ezra, jevrejski tumač Tore, pustinju u kojoj je Ismail živeo poistovetio je sa Arapskim poluostrvom. Ibn Ezra. Saadja Gaon, jevrejski rabin iz desetog veka, mesta koja se odnose na Hadžerin put preveo je izrazom koji upućuje na hidžasko područje, čime se kazivanje vezuje za predeo Meke. Saadja Gaon. Ibn Ezra bunar iz Postanja 16 poistovetio je sa Zemzemom, koji se nalazi kod Meke. Ibn Ezra, uz Postanje 16.","headingId":"jevrejska-tumacenja","headingText":"Jevrejska tumačenja"},{"text":"Postanje 21:21 Postanje 21:21 A on življaše u pustinji Faranu, i mati ga oženi iz zemlje misirske. Ismailovo naselje smešta se, dakle, u Paran, koji se ovde poistovećuje sa Arabijom, u blizini Medine.","headingId":"postanje-2121","headingText":"Postanje 21:21"}]}];
